window.KhaemenesScience9FinalQuestionBank=[{"unit":"Unit 00","domain":"Safety","prompt":"A planned investigation has a serious risk that cannot be controlled with available equipment. What should happen first?","options":["Revise or replace the method before beginning.","Proceed with fewer trials.","Ask participants to accept the risk.","Continue if the scientific question is important."],"answer":0,"explanation":"An investigation must not begin until serious risks are removed or reasonably controlled.","id":"legacy-q001","source":"unit-00","difficulty":"cumulative"},{"unit":"Unit 00","domain":"Personal protection","prompt":"Which action is appropriate when an approved activity requires splash goggles?","options":["Share one pair while materials are being handled.","Wear correctly fitting splash goggles for the entire exposure period.","Wear ordinary eyeglasses instead.","Remove the goggles whenever they fog."],"answer":1,"explanation":"Required protective equipment must be correctly fitted and worn throughout the relevant activity.","id":"legacy-q002","source":"unit-00","difficulty":"cumulative"},{"unit":"Unit 00","domain":"Chemical habits","prompt":"What is the safest rule for an unlabeled substance?","options":["Taste a tiny amount.","Mix it with water to see what happens.","Do not handle or use it; inform the supervising adult.","Smell it closely to identify it."],"answer":2,"explanation":"Unknown and unlabeled substances must be treated as potentially hazardous.","id":"legacy-q003","source":"unit-00","difficulty":"cumulative"},{"unit":"Unit 00","domain":"Emergency response","prompt":"A liquid splashes into a student’s eye during a supervised laboratory activity. What is the correct immediate response?","options":["Finish recording data before responding.","Rub the eye with a dry towel.","Wait to see whether pain develops.","Use the approved eyewash procedure immediately and alert the supervisor."],"answer":3,"explanation":"Immediate flushing and adult notification are required; treatment must not be delayed.","id":"legacy-q004","source":"unit-00","difficulty":"cumulative"},{"unit":"Unit 00","domain":"Data integrity","prompt":"A result does not match the other trials. What is the most responsible response?","options":["Document it, check the method and equipment, and repeat if appropriate.","Delete it without explanation.","Change it to equal the mean.","Conclude that all other trials are wrong."],"answer":0,"explanation":"Unexpected data should be investigated and reported transparently.","id":"legacy-q005","source":"unit-00","difficulty":"cumulative"},{"unit":"Unit 00","domain":"Ethics","prompt":"Which study plan requires informed consent and additional ethical safeguards?","options":["Timing a paper helicopter.","Collecting identifiable health information from human participants.","Measuring the length of classroom pencils.","Using a published anonymous dataset."],"answer":1,"explanation":"Identifiable human data require consent, privacy protection, and appropriate oversight.","id":"legacy-q006","source":"unit-00","difficulty":"cumulative"},{"unit":"Unit 00","domain":"Environmental responsibility","prompt":"Which field practice is appropriate?","options":["Remove rare specimens for a personal collection.","Publish exact locations of vulnerable species.","Observe from a permitted stable location and minimize disturbance.","Enter a protected nesting area for a closer photograph."],"answer":2,"explanation":"Safe scientific observation protects habitats, organisms, cultural resources, and sensitive locations.","id":"legacy-q007","source":"unit-00","difficulty":"cumulative"},{"unit":"Unit 00","domain":"Scientific habits","prompt":"Which notebook entry best supports reproducibility?","options":["Only the final conclusion.","A copied procedure with no changes recorded.","A list of results without units.","Date, materials, exact method, measurements, changes, and unexpected events."],"answer":3,"explanation":"Reproducibility requires a transparent record of what was actually done and observed.","id":"legacy-q008","source":"unit-00","difficulty":"cumulative"},{"unit":"Unit 01","domain":"Variables","prompt":"A student changes light intensity and measures the oxygen production rate of an aquatic plant. What is the independent variable?","options":["Light intensity.","Oxygen production rate.","Plant species.","Elapsed measurement time."],"answer":0,"explanation":"The independent variable is deliberately changed.","id":"legacy-q009","source":"unit-01","difficulty":"cumulative"},{"unit":"Unit 01","domain":"Measurement","prompt":"Repeated measurements are 12.2 cm, 12.2 cm, 12.3 cm, and 12.2 cm. What can be concluded from these values alone?","options":["There is no measurement uncertainty.","The measurements are precise.","The measurements are accurate.","The true value is 12.225 cm."],"answer":1,"explanation":"Closely grouped values show precision; accuracy requires comparison with a trusted value.","id":"legacy-q010","source":"unit-01","difficulty":"cumulative"},{"unit":"Unit 01","domain":"Data processing","prompt":"What is the mean of 4.0, 4.5, 5.0, and 4.5 seconds?","options":["4.75 seconds.","18.0 seconds.","4.5 seconds.","4.0 seconds."],"answer":2,"explanation":"The sum is 18.0 seconds and 18.0 ÷ 4 = 4.5 seconds.","id":"legacy-q011","source":"unit-01","difficulty":"cumulative"},{"unit":"Unit 01","domain":"Graphs","prompt":"Which graph is generally most suitable for showing the relationship between temperature and reaction rate?","options":["A pie chart.","A pictogram.","A single-category bar chart.","A scatter plot or line graph with two numerical axes."],"answer":3,"explanation":"Both variables are quantitative, so paired numerical axes are appropriate.","id":"legacy-q012","source":"unit-01","difficulty":"cumulative"},{"unit":"Unit 01","domain":"Reliability","prompt":"Why are repeated trials useful?","options":["They reveal variation and improve confidence in an estimate such as the mean.","They prove the hypothesis.","They remove all random error.","They guarantee accuracy."],"answer":0,"explanation":"Repeats show variability and strengthen estimates but do not guarantee correctness.","id":"legacy-q013","source":"unit-01","difficulty":"cumulative"},{"unit":"Unit 01","domain":"Causation","prompt":"An observational study finds an association between screen time and sleep duration. Which conclusion is justified?","options":["No confounding variable could exist.","The variables were associated in the observed sample, but causation is not established.","Screen time caused every sleep difference.","Sleep duration caused all screen use."],"answer":1,"explanation":"Observational association alone does not establish a causal mechanism.","id":"legacy-q014","source":"unit-01","difficulty":"cumulative"},{"unit":"Unit 01","domain":"Claim-evidence-reasoning","prompt":"Which statement is scientific reasoning rather than a claim or a measurement?","options":["The reaction lasted 24 seconds.","Three trials were completed.","Greater surface area increases collision opportunities, explaining the faster measured reaction.","The powdered sample reacted faster."],"answer":2,"explanation":"Reasoning connects evidence to a claim through a scientific principle.","id":"legacy-q015","source":"unit-01","difficulty":"cumulative"},{"unit":"Unit 01","domain":"Uncertainty","prompt":"A ruler has millimetre markings. Which report best reflects its resolution for a direct length reading?","options":["Report twenty decimal places.","Report no units.","Claim the length is exact.","Report to the nearest millimetre and acknowledge reading uncertainty."],"answer":3,"explanation":"The reporting precision should match the instrument resolution and method.","id":"legacy-q016","source":"unit-01","difficulty":"cumulative"},{"unit":"Unit 02","domain":"Cell theory","prompt":"Which statement is part of modern cell theory?","options":["All living organisms consist of one or more cells.","Every cell has a nucleus.","Viruses are complete cells.","Cells arise only from nonliving matter."],"answer":0,"explanation":"Cell theory identifies cells as the basic units of living systems.","id":"legacy-q017","source":"unit-02","difficulty":"cumulative"},{"unit":"Unit 02","domain":"Cell structures","prompt":"Which structures occur in all known cells?","options":["A Golgi apparatus and lysosomes.","A plasma membrane and ribosomes.","A nucleus and mitochondria.","Chloroplasts and a cell wall."],"answer":1,"explanation":"All cells require a boundary membrane and ribosomes for protein synthesis.","id":"legacy-q018","source":"unit-02","difficulty":"cumulative"},{"unit":"Unit 02","domain":"Classification","prompt":"Which feature distinguishes a typical eukaryotic cell from a typical prokaryotic cell?","options":["It has a plasma membrane.","It contains genetic material.","Most DNA is enclosed in a membrane-bound nucleus.","It has ribosomes."],"answer":2,"explanation":"Typical eukaryotes have a nucleus; prokaryotes do not.","id":"legacy-q019","source":"unit-02","difficulty":"cumulative"},{"unit":"Unit 02","domain":"Microscopy","prompt":"A specimen is 0.04 mm long and its image is 20 mm long. What is the magnification?","options":["50×.","800×.","0.002×.","500×."],"answer":3,"explanation":"Magnification = image size ÷ actual size = 20 ÷ 0.04 = 500.","id":"legacy-q020","source":"unit-02","difficulty":"cumulative"},{"unit":"Unit 02","domain":"Transport","prompt":"Osmosis is the net movement of:","options":["Water across a selectively permeable membrane from higher water potential toward lower water potential.","Solute from low concentration to high concentration without energy.","All particles through any membrane.","Water only from low solute concentration to low solute concentration."],"answer":0,"explanation":"Osmosis is a specific water-transport process across a selectively permeable membrane.","id":"legacy-q021","source":"unit-02","difficulty":"cumulative"},{"unit":"Unit 02","domain":"Surface area","prompt":"Why does a high surface-area-to-volume ratio support exchange?","options":["It prevents all water movement.","More membrane area is available relative to the material requiring exchange.","It eliminates diffusion distance.","It creates energy."],"answer":1,"explanation":"Greater relative surface area can increase exchange capacity.","id":"legacy-q022","source":"unit-02","difficulty":"cumulative"},{"unit":"Unit 02","domain":"Energy and matter","prompt":"Which statement correctly links photosynthesis and cellular respiration?","options":["Respiration occurs only in animals.","Photosynthesis destroys carbon atoms.","Photosynthesis stores energy in organic molecules, while respiration transfers usable energy from those molecules.","Both processes require sunlight at every step."],"answer":2,"explanation":"The processes connect matter cycling with energy transformation.","id":"legacy-q023","source":"unit-02","difficulty":"cumulative"},{"unit":"Unit 02","domain":"Organization","prompt":"Which sequence is ordered from smaller to larger biological organization?","options":["Organ → cell → tissue → organism.","Tissue → organ system → cell → organ.","Organ system → organ → tissue → cell.","Cell → tissue → organ → organ system."],"answer":3,"explanation":"Specialized cells form tissues, tissues form organs, and organs work in systems.","id":"legacy-q024","source":"unit-02","difficulty":"cumulative"},{"unit":"Unit 03","domain":"Homeostasis","prompt":"Homeostasis is best described as:","options":["Dynamic regulation of internal conditions within functional ranges.","Keeping every variable perfectly constant.","A process occurring only during illness.","The absence of environmental change."],"answer":0,"explanation":"Homeostatic systems continuously adjust rather than maintaining exact fixed values.","id":"legacy-q025","source":"unit-03","difficulty":"cumulative"},{"unit":"Unit 03","domain":"Feedback","prompt":"Which sequence represents a negative-feedback system?","options":["Stimulus → random action with no information pathway.","Change → receptor → coordinating centre → effector → response that reduces the change.","Change → amplifier → response that increases the change indefinitely.","Effector → receptor → no response."],"answer":1,"explanation":"Negative feedback opposes a deviation from a regulated range.","id":"legacy-q026","source":"unit-03","difficulty":"cumulative"},{"unit":"Unit 03","domain":"Circulation","prompt":"What is the primary role of red blood cells?","options":["Filter urine.","Transmit nerve impulses.","Transport oxygen using haemoglobin.","Produce digestive enzymes."],"answer":2,"explanation":"Haemoglobin in red blood cells binds and transports oxygen.","id":"legacy-q027","source":"unit-03","difficulty":"cumulative"},{"unit":"Unit 03","domain":"Gas exchange","prompt":"Which adaptation increases gas-exchange efficiency in alveoli?","options":["Thick dry walls.","Low blood supply.","A small number of sealed chambers.","Large surface area and a thin exchange barrier."],"answer":3,"explanation":"A large area, short diffusion path, and maintained gradients support diffusion.","id":"legacy-q028","source":"unit-03","difficulty":"cumulative"},{"unit":"Unit 03","domain":"Digestion","prompt":"Most absorption of digested nutrients occurs in the:","options":["Small intestine.","Stomach.","Large intestine.","Oesophagus."],"answer":0,"explanation":"The small intestine has a large absorptive surface and rich transport network.","id":"legacy-q029","source":"unit-03","difficulty":"cumulative"},{"unit":"Unit 03","domain":"Excretion","prompt":"The kidneys help regulate:","options":["Only food intake.","Water, ions, pH, and removal of nitrogenous wastes.","Only body temperature.","Only oxygen uptake."],"answer":1,"explanation":"Kidneys filter blood and adjust the composition of body fluids.","id":"legacy-q030","source":"unit-03","difficulty":"cumulative"},{"unit":"Unit 03","domain":"Coordination","prompt":"Compared with endocrine signalling, nervous signalling is generally:","options":["Carried only in blood.","Unable to affect muscles.","Faster and more targeted.","Always slower and more widespread."],"answer":2,"explanation":"Nervous impulses act rapidly through specific pathways; hormones often act more slowly.","id":"legacy-q031","source":"unit-03","difficulty":"cumulative"},{"unit":"Unit 03","domain":"Health data ethics","prompt":"A classroom heart-rate record should be used to:","options":["Diagnose heart disease.","Publish named student records.","Replace professional medical evaluation.","Explore physiological patterns without diagnosing a medical condition."],"answer":3,"explanation":"Educational measurements require privacy and cannot support diagnosis.","id":"legacy-q032","source":"unit-03","difficulty":"cumulative"},{"unit":"Unit 04","domain":"Genetic organization","prompt":"Which sequence is correct?","options":["DNA contains genes and is organized into chromosomes.","Chromosomes contain cells inside genes.","Genes contain organisms.","Alleles are made of tissues."],"answer":0,"explanation":"Genes are DNA sequences located on chromosomes.","id":"legacy-q033","source":"unit-04","difficulty":"cumulative"},{"unit":"Unit 04","domain":"Mitosis","prompt":"Mitosis usually produces:","options":["Gametes only.","Two genetically similar daughter cells with the same chromosome number as the parent cell.","Four genetically varied haploid cells.","One cell with twice the chromosome number."],"answer":1,"explanation":"Mitosis supports growth, repair, and many forms of asexual reproduction.","id":"legacy-q034","source":"unit-04","difficulty":"cumulative"},{"unit":"Unit 04","domain":"Meiosis","prompt":"Meiosis contributes to variation through:","options":["Preventing chromosome separation.","Eliminating all mutation.","Crossing over, independent assortment, and random fertilization.","Producing identical diploid cells."],"answer":2,"explanation":"Meiosis and fertilization reshuffle inherited information.","id":"legacy-q035","source":"unit-04","difficulty":"cumulative"},{"unit":"Unit 04","domain":"Probability","prompt":"For Aa × Aa, what is the expected probability of genotype aa?","options":["1/2.","3/4.","1.","1/4."],"answer":3,"explanation":"The genotype ratio is 1 AA : 2 Aa : 1 aa.","id":"legacy-q036","source":"unit-04","difficulty":"cumulative"},{"unit":"Unit 04","domain":"Phenotype","prompt":"Phenotype is influenced by:","options":["Genotype and environmental conditions.","Genotype only in every trait.","Environment only in every trait.","Neither inheritance nor environment."],"answer":0,"explanation":"Trait expression commonly reflects both inherited information and environment.","id":"legacy-q037","source":"unit-04","difficulty":"cumulative"},{"unit":"Unit 04","domain":"Mutation","prompt":"A mutation is:","options":["A change in exercise level.","A change in genetic material that may be neutral, harmful, or beneficial depending on context.","Always harmful.","Always inherited by offspring."],"answer":1,"explanation":"Mutation effects depend on location, cell type, environment, and biological context.","id":"legacy-q038","source":"unit-04","difficulty":"cumulative"},{"unit":"Unit 04","domain":"Cell cycle","prompt":"Why is cell-cycle regulation important?","options":["It stops all cell replacement.","It produces gametes by mitosis.","It coordinates division and helps limit uncontrolled proliferation.","It guarantees that cancer cannot occur."],"answer":2,"explanation":"Checkpoints and regulatory systems reduce inappropriate division but are not perfect.","id":"legacy-q039","source":"unit-04","difficulty":"cumulative"},{"unit":"Unit 04","domain":"Genetic ethics","prompt":"Which principle is essential when using identifiable genetic information?","options":["Public release without permission.","Treating probability as destiny.","Using ancestry claims to rank human worth.","Consent, privacy, limited access, and recognition of uncertainty."],"answer":3,"explanation":"Genetic data are sensitive and must not be used deterministically or discriminatorily.","id":"legacy-q040","source":"unit-04","difficulty":"cumulative"},{"unit":"Unit 05","domain":"Ecological organization","prompt":"Which term describes all populations of different species living and interacting in an area?","options":["Community.","Population.","Habitat.","Organism."],"answer":0,"explanation":"A community contains interacting populations of multiple species.","id":"legacy-q041","source":"unit-05","difficulty":"cumulative"},{"unit":"Unit 05","domain":"Energy flow","prompt":"Why is less energy available at higher trophic levels?","options":["Matter stops cycling.","Organisms use and dissipate much energy through metabolism and heat transfer.","Energy atoms are destroyed.","Predators cannot digest food."],"answer":1,"explanation":"Energy is transferred and dissipated, so only part enters the next trophic level.","id":"legacy-q042","source":"unit-05","difficulty":"cumulative"},{"unit":"Unit 05","domain":"Population ecology","prompt":"A population exceeds resource availability and then declines. Which factor most directly explains the decline?","options":["Creation of new energy.","Removal of all variation.","Density-dependent limitation such as competition for food.","Unlimited carrying capacity."],"answer":2,"explanation":"Competition, disease, and predation can intensify as density rises.","id":"legacy-q043","source":"unit-05","difficulty":"cumulative"},{"unit":"Unit 05","domain":"Biodiversity","prompt":"Species richness measures:","options":["The total biomass only.","The genetic sequence of one organism.","The age of an ecosystem.","The number of species present."],"answer":3,"explanation":"Richness counts species, while evenness describes relative abundances.","id":"legacy-q044","source":"unit-05","difficulty":"cumulative"},{"unit":"Unit 05","domain":"Natural selection","prompt":"Natural selection requires:","options":["Heritable variation and differences in reproductive success.","Individuals changing genes because they need to.","All organisms surviving equally.","No environmental influence."],"answer":0,"explanation":"Population traits change across generations when inherited variants affect reproductive success.","id":"legacy-q045","source":"unit-05","difficulty":"cumulative"},{"unit":"Unit 05","domain":"Evidence for evolution","prompt":"Which is direct empirical evidence used to reconstruct evolutionary relationships?","options":["The assumption that all similarities have one cause.","DNA sequence similarities and differences.","A philosophical preference.","A single unsupported story."],"answer":1,"explanation":"Genetic data are measured evidence; ancestry remains an inference supported by multiple evidence lines.","id":"legacy-q046","source":"unit-05","difficulty":"cumulative"},{"unit":"Unit 05","domain":"Ecosystem resilience","prompt":"An ecosystem is generally more resilient when it has:","options":["No disturbance history.","No nutrient cycling.","Functional diversity and multiple pathways that can maintain processes.","Only one species performing each function."],"answer":2,"explanation":"Redundancy and diversity can support recovery, though resilience remains context-dependent.","id":"legacy-q047","source":"unit-05","difficulty":"cumulative"},{"unit":"Unit 05","domain":"Conservation","prompt":"Which plan is strongest?","options":["Move organisms without permits.","Publish sensitive nest locations.","Choose an action without baseline data.","Protect habitat, involve affected communities, monitor outcomes, and revise using evidence."],"answer":3,"explanation":"Effective conservation combines ecological evidence, legal and cultural safeguards, monitoring, and adaptation.","id":"legacy-q048","source":"unit-05","difficulty":"cumulative"},{"unit":"Unit 06","domain":"Atomic identity","prompt":"The atomic number equals the number of:","options":["Protons.","Neutrons plus electrons.","Neutrons only.","Electron shells."],"answer":0,"explanation":"Element identity is determined by proton number.","id":"legacy-q049","source":"unit-06","difficulty":"cumulative"},{"unit":"Unit 06","domain":"Particle counts","prompt":"A neutral atom has atomic number 12. How many electrons does it have?","options":["10.","12.","6.","24."],"answer":1,"explanation":"A neutral atom has equal numbers of protons and electrons.","id":"legacy-q050","source":"unit-06","difficulty":"cumulative"},{"unit":"Unit 06","domain":"Isotopes","prompt":"Isotopes of the same element differ in their number of:","options":["Valence shells only.","Nuclei.","Neutrons.","Protons."],"answer":2,"explanation":"Isotopes share proton number but have different neutron counts.","id":"legacy-q051","source":"unit-06","difficulty":"cumulative"},{"unit":"Unit 06","domain":"Ions","prompt":"An atom with 17 protons and 18 electrons has charge:","options":["+1.","0.","−17.","−1."],"answer":3,"explanation":"One extra electron gives a net charge of −1.","id":"legacy-q052","source":"unit-06","difficulty":"cumulative"},{"unit":"Unit 06","domain":"Relative atomic mass","prompt":"Why is a periodic-table atomic mass often not a whole number?","options":["It is an abundance-weighted average of naturally occurring isotopes.","Atoms contain fractional protons.","Every isotope has the same abundance.","Electrons have no mass."],"answer":0,"explanation":"The reported value reflects isotope masses and their relative abundance.","id":"legacy-q053","source":"unit-06","difficulty":"cumulative"},{"unit":"Unit 06","domain":"Electron arrangement","prompt":"For elements 1–20, group patterns are strongly related to:","options":["The number of compounds already discovered.","Outer-electron arrangements.","Neutron color.","Nuclear size only."],"answer":1,"explanation":"Recurring valence-electron patterns help explain chemical trends.","id":"legacy-q054","source":"unit-06","difficulty":"cumulative"},{"unit":"Unit 06","domain":"Periodic trends","prompt":"Which broad statement is accurate?","options":["Halogens are metals.","All elements in a period have identical properties.","Group 1 metals generally become more reactive down the group.","Noble gases are highly reactive."],"answer":2,"explanation":"Outer electrons are farther from the nucleus and more shielded down Group 1.","id":"legacy-q055","source":"unit-06","difficulty":"cumulative"},{"unit":"Unit 06","domain":"Atomic models","prompt":"Why have atomic models changed over time?","options":["Atoms changed their laws.","Scientists preferred more complex drawings.","No experiments were involved.","New evidence required revision of earlier explanations."],"answer":3,"explanation":"Scientific models are revised when new observations are not adequately explained.","id":"legacy-q056","source":"unit-06","difficulty":"cumulative"},{"unit":"Unit 07","domain":"Ionic bonding","prompt":"Ionic bonding is the electrostatic attraction between:","options":["Oppositely charged ions.","Neutral molecules only.","Two nuclei with no electrons.","Identical atoms sharing no particles."],"answer":0,"explanation":"Electron transfer can form cations and anions that attract in a lattice.","id":"legacy-q057","source":"unit-07","difficulty":"cumulative"},{"unit":"Unit 07","domain":"Covalent bonding","prompt":"A covalent bond involves:","options":["Destruction of valence electrons.","A shared pair of electrons between atoms.","A neutron transfer.","Only attraction between separate ions."],"answer":1,"explanation":"Shared electron density attracts both nuclei.","id":"legacy-q058","source":"unit-07","difficulty":"cumulative"},{"unit":"Unit 07","domain":"Formulae","prompt":"What is the neutral formula formed from Mg²⁺ and Cl⁻?","options":["MgCl.","Mg₂Cl₂.","MgCl₂.","Mg₂Cl."],"answer":2,"explanation":"Two chloride ions are needed to balance one magnesium ion.","id":"legacy-q059","source":"unit-07","difficulty":"cumulative"},{"unit":"Unit 07","domain":"Conservation","prompt":"Why must a chemical equation be balanced?","options":["Molecules must have equal masses individually.","Energy is never transferred.","Coefficients change element identities.","Atoms are rearranged but conserved in a closed chemical reaction."],"answer":3,"explanation":"Equal atom counts represent conservation of matter.","id":"legacy-q060","source":"unit-07","difficulty":"cumulative"},{"unit":"Unit 07","domain":"Reaction energy","prompt":"In an exothermic reaction:","options":["The system transfers net energy to the surroundings.","The surroundings transfer net energy into the system.","No bonds change.","Temperature must always remain constant."],"answer":0,"explanation":"Exothermic reactions have lower-energy products relative to reactants under the stated conditions.","id":"legacy-q061","source":"unit-07","difficulty":"cumulative"},{"unit":"Unit 07","domain":"Reaction rate","prompt":"Why does increasing temperature often increase reaction rate?","options":["Products disappear.","Particles collide more frequently and a larger fraction have sufficient energy.","Atoms become larger.","Catalysts are automatically created."],"answer":1,"explanation":"Higher temperature changes collision frequency and energy distribution.","id":"legacy-q062","source":"unit-07","difficulty":"cumulative"},{"unit":"Unit 07","domain":"Catalysts","prompt":"A catalyst increases reaction rate by:","options":["Being consumed as the main reactant.","Raising atomic number.","Providing an alternative pathway with lower activation energy.","Increasing the equilibrium amount of every product."],"answer":2,"explanation":"A catalyst changes the reaction pathway and is regenerated overall.","id":"legacy-q063","source":"unit-07","difficulty":"cumulative"},{"unit":"Unit 07","domain":"Equilibrium","prompt":"Dynamic equilibrium in a closed system means:","options":["All reactions stop.","Reactant and product concentrations must be equal.","The container contains only products.","Forward and reverse reactions continue at equal rates."],"answer":3,"explanation":"Macroscopic concentrations remain constant while microscopic reactions continue.","id":"legacy-q064","source":"unit-07","difficulty":"cumulative"},{"unit":"Unit 08","domain":"Motion","prompt":"A runner moves 100 m east in 20 s. Average velocity is:","options":["5.0 m/s east.","5.0 m/s west.","2000 m/s.","0 m/s."],"answer":0,"explanation":"Average velocity is displacement divided by elapsed time with direction.","id":"legacy-q065","source":"unit-08","difficulty":"cumulative"},{"unit":"Unit 08","domain":"Acceleration","prompt":"Velocity changes from 4 m/s to 10 m/s in 3 s. Average acceleration is:","options":["30 m/s².","2 m/s².","6 m/s².","14 m/s²."],"answer":1,"explanation":"Acceleration = (10−4)/3 = 2 m/s².","id":"legacy-q066","source":"unit-08","difficulty":"cumulative"},{"unit":"Unit 08","domain":"Graphs","prompt":"The slope of a position–time graph represents:","options":["Force.","Momentum.","Velocity.","Acceleration directly."],"answer":2,"explanation":"Position change per unit time is velocity.","id":"legacy-q067","source":"unit-08","difficulty":"cumulative"},{"unit":"Unit 08","domain":"Net force","prompt":"A 20 N force acts right and an 8 N force acts left. Net force is:","options":["28 N right.","12 N left.","160 N right.","12 N right."],"answer":3,"explanation":"Opposing forces subtract, and the larger direction is right.","id":"legacy-q068","source":"unit-08","difficulty":"cumulative"},{"unit":"Unit 08","domain":"Newton’s second law","prompt":"A 4 kg object experiences a 12 N net force. Its acceleration is:","options":["3 m/s².","48 m/s².","0.33 m/s².","16 m/s²."],"answer":0,"explanation":"a = Fnet/m = 12/4 = 3 m/s².","id":"legacy-q069","source":"unit-08","difficulty":"cumulative"},{"unit":"Unit 08","domain":"Momentum","prompt":"A 2 kg cart moves at 5 m/s. Momentum is:","options":["25 kg·m/s.","10 kg·m/s.","2.5 kg·m/s.","7 kg·m/s."],"answer":1,"explanation":"Momentum p = mv = 2×5 = 10 kg·m/s.","id":"legacy-q070","source":"unit-08","difficulty":"cumulative"},{"unit":"Unit 08","domain":"Energy","prompt":"A 3 kg object moves at 4 m/s. Kinetic energy is:","options":["12 J.","48 J.","24 J.","6 J."],"answer":2,"explanation":"KE = ½mv² = 0.5×3×16 = 24 J.","id":"legacy-q071","source":"unit-08","difficulty":"cumulative"},{"unit":"Unit 08","domain":"Power and efficiency","prompt":"A device transfers 600 J in 20 s. Its average power is:","options":["12 W.","120 W.","12,000 W.","30 W."],"answer":3,"explanation":"Power = energy/time = 600/20 = 30 W.","id":"legacy-q072","source":"unit-08","difficulty":"cumulative"},{"unit":"Unit 09","domain":"Electricity","prompt":"Current is defined as:","options":["Charge transferred per unit time.","Energy per unit charge.","Resistance multiplied by time.","Power divided by voltage only."],"answer":0,"explanation":"Electric current I = Q/t.","id":"legacy-q073","source":"unit-09","difficulty":"cumulative"},{"unit":"Unit 09","domain":"Ohm’s law","prompt":"A 12 V potential difference is across a 6 Ω resistor. Current is:","options":["72 A.","2 A.","0.5 A.","6 A."],"answer":1,"explanation":"I = V/R = 12/6 = 2 A.","id":"legacy-q074","source":"unit-09","difficulty":"cumulative"},{"unit":"Unit 09","domain":"Parallel circuits","prompt":"In a parallel circuit, each branch has:","options":["Zero resistance.","No energy transfer.","The same potential difference as the source, under the ideal model.","The same current in every branch regardless of resistance."],"answer":2,"explanation":"Parallel branches share the same pair of connection points.","id":"legacy-q075","source":"unit-09","difficulty":"cumulative"},{"unit":"Unit 09","domain":"Power","prompt":"A device operates at 9 V and 0.50 A. Electrical power is:","options":["18 W.","0.056 W.","9.5 W.","4.5 W."],"answer":3,"explanation":"P = VI = 9×0.50 = 4.5 W.","id":"legacy-q076","source":"unit-09","difficulty":"cumulative"},{"unit":"Unit 09","domain":"Magnetism","prompt":"Electromagnetic induction requires:","options":["A change in magnetic flux through a circuit.","A constant unchanging magnetic field only.","No conductor.","Chemical combustion."],"answer":0,"explanation":"Changing magnetic flux induces a potential difference.","id":"legacy-q077","source":"unit-09","difficulty":"cumulative"},{"unit":"Unit 09","domain":"Waves","prompt":"A wave has frequency 5 Hz and wavelength 3 m. Wave speed is:","options":["0.6 m/s.","15 m/s.","1.67 m/s.","8 m/s."],"answer":1,"explanation":"v = fλ = 5×3 = 15 m/s.","id":"legacy-q078","source":"unit-09","difficulty":"cumulative"},{"unit":"Unit 09","domain":"Refraction","prompt":"When a wave enters a slower medium, its frequency generally:","options":["Always doubles.","Changes independently of the source.","Remains set by the source while speed and wavelength change.","Becomes zero."],"answer":2,"explanation":"Frequency is continuous across the boundary in the standard model.","id":"legacy-q079","source":"unit-09","difficulty":"cumulative"},{"unit":"Unit 09","domain":"Digital information","prompt":"Why can digital systems often regenerate a noisy signal?","options":["Digital data contain no noise.","Every error is automatically corrected.","Sampling has no limits.","Receivers can classify values into discrete states and reconstruct them within tolerance."],"answer":3,"explanation":"Discrete levels can improve regeneration, but noise, sampling, and error-control limits remain.","id":"legacy-q080","source":"unit-09","difficulty":"cumulative"},{"unit":"Unit 10","domain":"Earth systems","prompt":"A flux is:","options":["A rate of transfer between reservoirs.","A stored amount only.","A rock type.","A fixed system boundary."],"answer":0,"explanation":"Fluxes describe movement per unit time.","id":"legacy-q081","source":"unit-10","difficulty":"cumulative"},{"unit":"Unit 10","domain":"Earth interior","prompt":"Which evidence supports a liquid outer core?","options":["Cloud formation.","S waves do not propagate through part of Earth’s interior.","Ocean tides.","Surface soil colour."],"answer":1,"explanation":"The S-wave shadow zone is evidence that the outer core lacks shear rigidity.","id":"legacy-q082","source":"unit-10","difficulty":"cumulative"},{"unit":"Unit 10","domain":"Plate tectonics","prompt":"A mid-ocean ridge is associated with:","options":["Continental collision.","No plate motion.","A divergent plate boundary.","A transform boundary only."],"answer":2,"explanation":"Divergence forms new oceanic crust at ridges.","id":"legacy-q083","source":"unit-10","difficulty":"cumulative"},{"unit":"Unit 10","domain":"Surface processes","prompt":"Weathering differs from erosion because weathering:","options":["Always transports sediment.","Occurs only in rivers.","Requires melting.","Breaks material down in place."],"answer":3,"explanation":"Erosion removes and transports material.","id":"legacy-q084","source":"unit-10","difficulty":"cumulative"},{"unit":"Unit 10","domain":"Water budget","prompt":"Precipitation is 100 mm, evapotranspiration 35 mm, and runoff 45 mm. Storage change is:","options":["20 mm.","10 mm.","80 mm.","180 mm."],"answer":0,"explanation":"ΔS = P−ET−R = 100−35−45 = 20 mm.","id":"legacy-q085","source":"unit-10","difficulty":"cumulative"},{"unit":"Unit 10","domain":"Carbon cycle","prompt":"A reservoir receives 60 units/year and loses 45 units/year. Net change is:","options":["105 units/year.","+15 units/year.","−15 units/year.","0 units/year."],"answer":1,"explanation":"Net change = inputs−outputs = 15 units/year.","id":"legacy-q086","source":"unit-10","difficulty":"cumulative"},{"unit":"Unit 10","domain":"Nutrient cycles","prompt":"Why can excess nutrient input lower dissolved oxygen in water?","options":["Water stops moving permanently.","Nitrogen becomes radioactive.","Increased production and decomposition can increase oxygen consumption.","Nutrients destroy oxygen atoms."],"answer":2,"explanation":"Eutrophication can increase decomposition and oxygen demand.","id":"legacy-q087","source":"unit-10","difficulty":"cumulative"},{"unit":"Unit 10","domain":"Climate energy","prompt":"Incoming solar energy is 340 W/m² and albedo is 0.30. Absorbed solar energy is:","options":["102 W/m².","340 W/m².","442 W/m².","238 W/m²."],"answer":3,"explanation":"Absorbed = (1−0.30)×340 = 238 W/m².","id":"legacy-q088","source":"unit-10","difficulty":"cumulative"},{"unit":"Unit 11","domain":"Seasons","prompt":"Earth’s seasons are caused primarily by:","options":["Axial tilt changing solar angle and day length.","Large changes in Earth–Sun distance.","The Moon’s shadow.","Changes in the Sun’s mass."],"answer":0,"explanation":"Axial tilt changes illumination geometry through the year.","id":"legacy-q089","source":"unit-11","difficulty":"cumulative"},{"unit":"Unit 11","domain":"Lunar phases","prompt":"Ordinary lunar phases result from:","options":["Clouds in Earth’s atmosphere.","Changing viewing geometry of the Moon’s sunlit half.","Earth’s shadow covering the Moon every month.","The Moon changing its own light output."],"answer":1,"explanation":"The Moon is always half illuminated by the Sun except during eclipses.","id":"legacy-q090","source":"unit-11","difficulty":"cumulative"},{"unit":"Unit 11","domain":"Light-time","prompt":"Light travels 3.0×10⁸ m/s. Time to travel 1.5×10¹¹ m is:","options":["5000 s.","4.5×10¹⁹ s.","500 s.","50 s."],"answer":2,"explanation":"t = d/c = 1.5×10¹¹ ÷ 3.0×10⁸ = 500 s.","id":"legacy-q091","source":"unit-11","difficulty":"cumulative"},{"unit":"Unit 11","domain":"Orbits","prompt":"In a circular orbit, velocity is approximately tangent to the path while acceleration points:","options":["Along the velocity.","Away from the central body.","Nowhere.","Toward the central body."],"answer":3,"explanation":"Gravity supplies centripetal acceleration.","id":"legacy-q092","source":"unit-11","difficulty":"cumulative"},{"unit":"Unit 11","domain":"Spectra","prompt":"A spectral line shifts from 600 nm to 603 nm. Redshift z is:","options":["0.005.","0.0005.","0.05.","1.005."],"answer":0,"explanation":"z = (603−600)/600 = 0.005.","id":"legacy-q093","source":"unit-11","difficulty":"cumulative"},{"unit":"Unit 11","domain":"Stellar evolution","prompt":"Compared with low-mass stars, high-mass stars generally:","options":["Remain protostars.","Use fuel faster and have shorter lifetimes.","Live longer because they contain more fuel.","Never undergo fusion."],"answer":1,"explanation":"Higher core temperature and luminosity consume fuel rapidly.","id":"legacy-q094","source":"unit-11","difficulty":"cumulative"},{"unit":"Unit 11","domain":"Exoplanets","prompt":"A transit depth of 1% gives an approximate planet-to-star radius ratio of:","options":["0.50.","1.00.","0.10.","0.01."],"answer":2,"explanation":"Rp/Rs ≈ √0.01 = 0.10.","id":"legacy-q095","source":"unit-11","difficulty":"cumulative"},{"unit":"Unit 11","domain":"Cosmology","prompt":"Which combination supports an evolving hot early universe?","options":["Seasons, tides, and weather.","Only one galaxy image.","A single solar flare.","Galaxy redshift trends, cosmic microwave background radiation, and primordial light-element abundances."],"answer":3,"explanation":"Independent evidence lines support the Big Bang model.","id":"legacy-q096","source":"unit-11","difficulty":"cumulative"},{"unit":"Unit 12","domain":"Problem definition","prompt":"A strong engineering need statement should identify:","options":["The affected users, context, measurable need, and important boundaries.","A preferred solution before research.","Only the designer’s opinion.","No stakeholders."],"answer":0,"explanation":"Problem definition should precede solution selection.","id":"legacy-q097","source":"unit-12","difficulty":"cumulative"},{"unit":"Unit 12","domain":"Criteria and constraints","prompt":"Which is a constraint?","options":["The team likes recycled material.","The design must not exceed the approved cost and safety limits.","The design should be visually attractive.","The design should maximize user preference."],"answer":1,"explanation":"Constraints are non-negotiable limits; criteria are optimized.","id":"legacy-q098","source":"unit-12","difficulty":"cumulative"},{"unit":"Unit 12","domain":"Decision matrices","prompt":"Why should criterion weights be established before scoring concepts?","options":["To remove the need for evidence.","To make all criteria equal.","To reduce manipulation of priorities after seeing preferred results.","To guarantee the highest score is safe."],"answer":2,"explanation":"Predefined weights improve transparency and reduce bias.","id":"legacy-q099","source":"unit-12","difficulty":"cumulative"},{"unit":"Unit 12","domain":"Testing","prompt":"Why are repeated prototype trials important?","options":["They guarantee the design is optimal.","They eliminate measurement uncertainty.","They replace a baseline.","They reveal variability and support estimates of reliability."],"answer":3,"explanation":"Repeats show spread and consistency.","id":"legacy-q100","source":"unit-12","difficulty":"cumulative"},{"unit":"Unit 12","domain":"Life cycle","prompt":"A life-cycle comparison should use:","options":["The same functional unit and system boundary for all options.","Different service levels for each concept.","Only manufacturing impacts.","Only end-of-life impacts."],"answer":0,"explanation":"Consistent function and boundaries are essential for fair comparison.","id":"legacy-q101","source":"unit-12","difficulty":"cumulative"},{"unit":"Unit 12","domain":"Risk","prompt":"A high weighted score cannot justify a concept that:","options":["Requires one additional calculation.","Fails a hard safety or legal constraint.","Has a lower aesthetic score.","Uses a different colour."],"answer":1,"explanation":"Non-negotiable constraints override preference scores.","id":"legacy-q102","source":"unit-12","difficulty":"cumulative"},{"unit":"Unit 12","domain":"Reliability","prompt":"For required independent components in series, overall reliability is:","options":["Always equal to the most reliable component.","Unrelated to component performance.","The product of the component reliabilities.","The sum of the reliabilities."],"answer":2,"explanation":"All required series components must succeed.","id":"legacy-q103","source":"unit-12","difficulty":"cumulative"},{"unit":"Unit 12","domain":"Iteration","prompt":"Evidence-based iteration means:","options":["Changing success criteria to make the design pass.","Hiding unsuccessful trials.","Selecting the first concept permanently.","Revising the design in response to test evidence while documenting changes and tradeoffs."],"answer":3,"explanation":"Iteration uses transparent evidence to improve performance and understanding.","id":"legacy-q104","source":"unit-12","difficulty":"cumulative"},{"id":"u01-q-q01","domain":"Questions","prompt":"Which question is directly investigable with measurements and a defined comparison?","options":["How does wing length in centimeters affect flight distance in meters for airplanes made from the same paper and design?","Should everyone enjoy building paper airplanes?","Is flight interesting?","Which paper airplane looks best?"],"answer":0,"explanation":"The question identifies a measurable changed variable, measurable outcome, and a comparison that can be investigated.","source":"unit-01","difficulty":"core","unit":"Unit 01","originalSource":"quiz"},{"id":"u01-q-q02","domain":"Variables","prompt":"A student deliberately changes ramp height and measures how far the same toy car travels. Which statement is correct?","options":["Ramp height is the dependent variable.","Distance traveled is the dependent variable.","The toy car is the independent variable.","Distance traveled should be controlled."],"answer":1,"explanation":"Distance traveled is the measured response; ramp height is deliberately changed.","source":"unit-01","difficulty":"core","unit":"Unit 01","originalSource":"quiz"},{"id":"u01-q-q03","domain":"Definitions","prompt":"Which is the strongest operational definition of plant growth for a two-week investigation?","options":["Growth is whatever difference the observer notices.","Growth means the plant looks healthier.","Growth is the change in stem height, measured in centimeters from the same reference point on Day 1 and Day 14.","Growth means doing well."],"answer":2,"explanation":"An operational definition states exactly how the variable is measured so another investigator can reproduce it.","source":"unit-01","difficulty":"core","unit":"Unit 01","originalSource":"quiz"},{"id":"u01-q-q04","domain":"Design","prompt":"Why are repeated trials useful in a fair test?","options":["They remove systematic bias automatically.","They make controlled variables unnecessary.","They guarantee the prediction is correct.","They characterize variation and provide more evidence about the typical result."],"answer":3,"explanation":"Replication helps reveal random variation and estimate a typical result, but it does not automatically correct systematic bias.","source":"unit-01","difficulty":"core","unit":"Unit 01","originalSource":"quiz"},{"id":"u01-q-q05","domain":"Measurement","prompt":"A ruler has millimeter markings. Which report best respects the instrument rather than inventing unsupported precision?","options":["A length reported at a precision defensible from the ruler and measurement procedure.","Only the word 'long.'","Any number without a unit.","A length with many extra decimal places because a calculator can display them."],"answer":0,"explanation":"Reported precision should be supported by the measuring instrument and procedure, not by calculator display digits.","source":"unit-01","difficulty":"core","unit":"Unit 01","originalSource":"quiz"},{"id":"u01-q-q06","domain":"Measurement","prompt":"Four measurements are 9.8 cm, 9.8 cm, 9.9 cm, and 9.8 cm. What can be concluded from these values alone?","options":["They establish causation.","They are highly precise, but accuracy cannot be established without an appropriate reference.","They are definitely accurate.","They prove the instrument has no systematic bias."],"answer":1,"explanation":"The values cluster closely, indicating precision. Accuracy and systematic bias require additional evidence or reference checks.","source":"unit-01","difficulty":"core","unit":"Unit 01","originalSource":"quiz"},{"id":"u01-q-q07","domain":"Data integrity","prompt":"One recorded trial is far from the others. What is the strongest first response?","options":["Delete it because it weakens the pattern.","Replace it with the mean.","Preserve it, inspect the procedure and notes for a documented cause, and repeat only according to a defensible rule.","Use it as the only result because unusual data are always most important."],"answer":2,"explanation":"An unusual observation remains part of the audit trail unless a scientifically justified, documented analysis rule supports different treatment.","source":"unit-01","difficulty":"core","unit":"Unit 01","originalSource":"quiz"},{"id":"u01-q-q08","domain":"Graphing","prompt":"Paper type is categorical and mean water absorbed is numerical. Which display is generally appropriate for comparing the paper categories?","options":["A line graph that implies paper types occur in a continuous sequence.","A pie chart of unrelated totals.","An unlabeled graph with no units.","A bar chart with paper type on the x-axis and clearly identified mean water absorbed on the y-axis."],"answer":3,"explanation":"A bar chart can compare a numerical summary across discrete categories; raw trials should remain available to show the basis of the summary.","source":"unit-01","difficulty":"core","unit":"Unit 01","originalSource":"quiz"},{"id":"u01-q-q09","domain":"Graph integrity","prompt":"Two graphs use the same data but different y-axis ranges. Which statement is most scientifically defensible?","options":["Axis range can change visual impression without changing the underlying numbers, so scale and labels must be inspected.","All graphs must begin every numerical axis at zero regardless of purpose.","Axis choices do not affect interpretation.","The graph with the steepest-looking pattern is automatically more truthful."],"answer":0,"explanation":"Scale changes visual emphasis. Readers need the axis values and context to judge magnitude honestly.","source":"unit-01","difficulty":"core","unit":"Unit 01","originalSource":"quiz"},{"id":"u01-q-q10","domain":"Study types","prompt":"Researchers record students' existing sleep duration and test scores without assigning sleep schedules. What does the design directly establish?","options":["A controlled causal effect of sleep duration.","An observational relationship that may be associated but can contain confounding or reverse-causation explanations.","That test scores cause sleep duration.","That no scientific conclusion is possible."],"answer":1,"explanation":"Because sleep was observed rather than assigned, the study can examine association but does not by itself isolate a causal effect.","source":"unit-01","difficulty":"core","unit":"Unit 01","originalSource":"quiz"},{"id":"u01-q-q11","domain":"Causal reasoning","prompt":"Ice-cream sales and sunburn cases both rise during hot summer periods. Which is a plausible confounding explanation?","options":["Ice cream must cause sunburn.","Sunburn must cause ice-cream purchases.","Hot sunny weather can increase both ice-cream purchases and sun exposure.","Any correlation proves both variables are inaccurate."],"answer":2,"explanation":"A third variable—hot sunny weather—can plausibly influence both observed variables.","source":"unit-01","difficulty":"core","unit":"Unit 01","originalSource":"quiz"},{"id":"u01-q-q12","domain":"CER","prompt":"Which statement best describes scientific reasoning in a CER?","options":["It is a personal opinion about whether the result is interesting.","It lists sources without connecting them to the claim.","It repeats the evidence using different words.","It explains why the evidence bears on the claim using relevant scientific ideas, study design, and appropriate limitations."],"answer":3,"explanation":"Reasoning supplies the logical and scientific connection between evidence and claim and should respect design limitations.","source":"unit-01","difficulty":"core","unit":"Unit 01","originalSource":"quiz"},{"id":"u01-q-q13","domain":"Sources","prompt":"A news headline makes a strong scientific claim. What is the strongest source-literacy response?","options":["Trace the claim toward the original study, dataset, or agency report and compare the original evidence and limitations with the headline wording.","Reject every news report automatically.","Count how many times the claim was reposted.","Trust the headline if it sounds scientific."],"answer":0,"explanation":"Tracing toward original evidence allows the reader to inspect method, scope, limitations, and whether the public wording preserves them.","source":"unit-01","difficulty":"core","unit":"Unit 01","originalSource":"quiz"},{"id":"u01-q-q14","domain":"Uncertainty","prompt":"Which statement correctly distinguishes random variation from systematic bias?","options":["Repeating measurements always eliminates both.","Random variation can cause unpredictable trial-to-trial differences, while systematic bias can shift measurements consistently and may persist across repetitions.","Systematic bias is simply any unusual data point.","Random variation means the experiment was conducted incorrectly."],"answer":1,"explanation":"Replication can help characterize some random variation, while systematic bias often requires calibration, reference checks, sampling changes, or redesign.","source":"unit-01","difficulty":"core","unit":"Unit 01","originalSource":"quiz"},{"id":"u01-q-q15","domain":"Safety and design","prompt":"A planned investigation has a hazard that cannot be reasonably controlled with the available equipment and supervision. What should happen before data collection?","options":["Continue because completing the dataset is more important.","Hide the hazard from the record.","Revise, replace, or postpone the method until the risk can be acceptably controlled.","Collect fewer trials so exposure is shorter."],"answer":2,"explanation":"Scientific work does not justify an uncontrolled hazard. The design must be changed or postponed before beginning.","source":"unit-01","difficulty":"core","unit":"Unit 01","originalSource":"quiz"},{"id":"u01-a-a01","domain":"Questions & hypotheses","prompt":"Which question identifies a deliberately changed variable, a measurable response, and conditions that can be compared?","options":["How does salt concentration affect the melting time of equal-mass ice cubes under the same room conditions?","Which ice cube looks nicest?","Should salt be used?","Are plants good?"],"answer":0,"explanation":"A strong investigable question identifies measurable variables and a defined comparison rather than asking for preference or judgment.","source":"unit-01","difficulty":"transfer","unit":"Unit 01","originalSource":"assessment"},{"id":"u01-a-a02","domain":"Questions & hypotheses","prompt":"Which prediction is testable, directional, and appropriately scoped?","options":["Light is important.","If daily light duration increases, then mean seedling height after 14 days will increase within the tested light-duration range, assuming the other stated growth conditions are controlled.","Plants are interesting.","The result will prove the hypothesis."],"answer":1,"explanation":"The prediction gives a measurable direction and limits the claim to the tested conditions.","source":"unit-01","difficulty":"transfer","unit":"Unit 01","originalSource":"assessment"},{"id":"u01-a-a03","domain":"Questions & hypotheses","prompt":"A preregistered prediction is not supported by the results. What is the strongest scientific response?","options":["Rewrite the prediction and pretend the new version came first.","Delete results that disagree.","Report that the results did not support the prediction, evaluate the method and evidence, and revise the explanation if warranted.","Declare the investigation a failure with no useful information."],"answer":2,"explanation":"Unsupported predictions should be reported honestly. Scientific value comes from evaluating evidence, not forcing results to match expectations.","source":"unit-01","difficulty":"transfer","unit":"Unit 01","originalSource":"assessment"},{"id":"u01-a-a04","domain":"Variables & controls","prompt":"A student investigates how pendulum length affects period. Which is the independent variable?","options":["Period","Number of timing trials","Graph scale","Pendulum length"],"answer":3,"explanation":"Pendulum length is the factor deliberately changed.","source":"unit-01","difficulty":"transfer","unit":"Unit 01","originalSource":"assessment"},{"id":"u01-a-a05","domain":"Variables & controls","prompt":"In the pendulum investigation, why should release angle be controlled?","options":["Because changing it systematically with length could create an alternative explanation for period differences.","Because every controlled variable must equal zero.","Because it determines the graph title.","Because it is the measured outcome."],"answer":0,"explanation":"A control limits plausible alternative explanations by preventing another factor from changing systematically with the independent variable.","source":"unit-01","difficulty":"transfer","unit":"Unit 01","originalSource":"assessment"},{"id":"u01-a-a06","domain":"Variables & controls","prompt":"Which statement best describes a confounder?","options":["Any variable written in the notebook.","A variable related to the explanatory condition and the outcome that can create or distort an apparent relationship.","Only an obviously incorrect measurement.","The dependent variable in every experiment."],"answer":1,"explanation":"A confounder can provide an alternative explanation because it varies with both the explanatory condition and the response.","source":"unit-01","difficulty":"transfer","unit":"Unit 01","originalSource":"assessment"},{"id":"u01-a-a07","domain":"Measurement","prompt":"Which tool is most appropriate for timing a paper-helicopter fall lasting about 1.5 seconds?","options":["A meter stick only","A thermometer","A stopwatch/timer with sub-second resolution","A kilogram scale"],"answer":2,"explanation":"The instrument must measure the correct quantity and have resolution appropriate to the event duration.","source":"unit-01","difficulty":"transfer","unit":"Unit 01","originalSource":"assessment"},{"id":"u01-a-a08","domain":"Measurement","prompt":"Which statement correctly distinguishes accuracy from precision?","options":["Accuracy and precision always mean the same thing.","Precision proves there is no systematic bias.","Accuracy describes graph scale.","Accuracy is closeness to an appropriate reference; precision is closeness among repeated measurements."],"answer":3,"explanation":"Repeated measurements can be precise yet systematically shifted from an appropriate reference.","source":"unit-01","difficulty":"transfer","unit":"Unit 01","originalSource":"assessment"},{"id":"u01-a-a09","domain":"Measurement","prompt":"A digital balance displays mass to the nearest 0.1 g. Which reporting choice is most defensible?","options":["18.4 g when that is the displayed measurement","18.43726 g because a calculator can show extra digits","18 g exactly with no stated limitation","18.4 mL"],"answer":0,"explanation":"Reported digits should be supported by the instrument and method; calculator digits do not create measurement information.","source":"unit-01","difficulty":"transfer","unit":"Unit 01","originalSource":"assessment"},{"id":"u01-a-a10","domain":"Measurement","prompt":"Five repeated measurements are tightly clustered, but a calibration check shows the instrument reads 0.5 units high. What does this show?","options":["The range must be zero.","High precision can coexist with systematic bias.","The measurements must be accurate because they agree.","Repeated trials automatically removed the bias."],"answer":1,"explanation":"Consistency among repeated measurements does not guarantee accuracy when a systematic offset is present.","source":"unit-01","difficulty":"transfer","unit":"Unit 01","originalSource":"assessment"},{"id":"u01-a-a11","domain":"Data integrity","prompt":"Which procedure best protects the integrity of repeated-trial data?","options":["Delete unusual values before recording them.","Replace raw observations with the mean.","Record every planned trial and document any protocol deviation before deciding how it affects analysis.","Repeat only results that disagree with the prediction."],"answer":2,"explanation":"Raw observations and deviations should remain auditable; analysis decisions should not be based on whether a result is convenient.","source":"unit-01","difficulty":"transfer","unit":"Unit 01","originalSource":"assessment"},{"id":"u01-a-a12","domain":"Data integrity","prompt":"A trial is far from the others but no procedural failure was observed. What should the investigator do first?","options":["Change it to the nearest expected value.","Use only that trial.","Delete it as an error.","Preserve and flag it, investigate possible explanations, and evaluate its influence transparently."],"answer":3,"explanation":"An unusual observation is a question for investigation, not an automatic deletion rule.","source":"unit-01","difficulty":"transfer","unit":"Unit 01","originalSource":"assessment"},{"id":"u01-a-a13","domain":"Tables & graphs","prompt":"Which table heading is scientifically complete?","options":["Fall time (s)","Results","Numbers","Time"],"answer":0,"explanation":"A complete quantitative heading identifies both the variable and its unit.","source":"unit-01","difficulty":"transfer","unit":"Unit 01","originalSource":"assessment"},{"id":"u01-a-a14","domain":"Tables & graphs","prompt":"Paper type is categorical and water absorbed is numerical. Which graph is generally appropriate for comparing mean water absorbed among paper types?","options":["A pie chart of unrelated totals","A bar chart with paper type on the x-axis and mean water absorbed (g) on the y-axis","A line graph implying paper types form a continuous sequence","An unlabeled sketch"],"answer":1,"explanation":"A bar chart can compare a numerical summary across discrete categories; raw trial data should remain available behind the summary.","source":"unit-01","difficulty":"transfer","unit":"Unit 01","originalSource":"assessment"},{"id":"u01-a-a15","domain":"Tables & graphs","prompt":"Which graph is generally appropriate for examining the association between estimated shade percentage and surface temperature?","options":["Decorative icon chart","Unscaled diagram","Scatter plot","Pie chart"],"answer":2,"explanation":"A scatter plot displays paired values for two numerical variables.","source":"unit-01","difficulty":"transfer","unit":"Unit 01","originalSource":"assessment"},{"id":"u01-a-a16","domain":"Tables & graphs","prompt":"Two graphs show the same data but use different y-axis ranges. What is the most defensible conclusion?","options":["Every numerical axis must always begin at zero.","Axis choices never affect interpretation.","The steeper-looking graph is automatically more accurate.","Scale can change visual impression without changing the data, so readers should inspect ranges, intervals, labels, and context."],"answer":3,"explanation":"Scale is part of data communication. A truncated axis can be useful, but it can also visually magnify small differences if context is ignored.","source":"unit-01","difficulty":"transfer","unit":"Unit 01","originalSource":"assessment"},{"id":"u01-a-a17","domain":"Data analysis","prompt":"The fall times 1.4 s, 1.5 s, 1.5 s, 1.6 s, and 1.5 s have a mean of:","options":["1.5 s","1.6 s","7.5 s","1.0 s"],"answer":0,"explanation":"The total is 7.5 s; 7.5 ÷ 5 = 1.5 s.","source":"unit-01","difficulty":"transfer","unit":"Unit 01","originalSource":"assessment"},{"id":"u01-a-a18","domain":"Data analysis","prompt":"For the same values, what does the 0.2 s range describe?","options":["The number of trials.","The observed spread from the minimum to maximum trial.","The accuracy of the timer.","The causal effect of the independent variable."],"answer":1,"explanation":"Range equals maximum minus minimum and summarizes observed spread; it does not establish accuracy or causation.","source":"unit-01","difficulty":"transfer","unit":"Unit 01","originalSource":"assessment"},{"id":"u01-a-a19","domain":"Inference","prompt":"A pattern appears in one limited study. Which conclusion is best calibrated to the evidence?","options":["There are no remaining alternative explanations.","One variable definitely caused the other regardless of design.","The pattern was observed under these study conditions and should be evaluated with limitations and additional evidence.","The pattern is universally true."],"answer":2,"explanation":"Scientific claims should match the scope, design, uncertainty, and limitations of the evidence.","source":"unit-01","difficulty":"transfer","unit":"Unit 01","originalSource":"assessment"},{"id":"u01-a-a20","domain":"Inference","prompt":"A study observes that students who sleep longer tend to have higher test scores but does not assign sleep schedules. Which claim is justified directly by that design?","options":["Higher scores caused longer sleep.","No third variable could matter.","Longer sleep caused every higher score.","Sleep duration and test score were associated in the observed sample."],"answer":3,"explanation":"The observational design supports an association; confounding and direction-of-causation alternatives remain possible.","source":"unit-01","difficulty":"transfer","unit":"Unit 01","originalSource":"assessment"},{"id":"u01-a-a21","domain":"Causal reasoning","prompt":"Which design change most strengthens causal inference when it is safe and ethical?","options":["Deliberately manipulate one factor while controlling or randomizing plausible alternatives where feasible.","Remove the comparison condition.","Select only observations that fit the prediction.","Change several factors together."],"answer":0,"explanation":"Controlled manipulation and design features that reduce alternative explanations strengthen causal inference.","source":"unit-01","difficulty":"transfer","unit":"Unit 01","originalSource":"assessment"},{"id":"u01-a-a22","domain":"CER","prompt":"Which statement is reasoning rather than merely evidence or claim?","options":["Longer rotors had longer mean fall times in this test.","Because rotor geometry can affect interaction with air, and rotor length was deliberately varied while stated conditions were controlled, the measured pattern supports an effect of rotor length under these tested conditions, subject to the listed limitations.","Five trials were recorded.","The mean fall time was 1.8 s."],"answer":1,"explanation":"Reasoning connects the evidence to the claim using scientific ideas and the design while respecting limitations.","source":"unit-01","difficulty":"transfer","unit":"Unit 01","originalSource":"assessment"},{"id":"u01-a-a23","domain":"Sources","prompt":"A dramatic news headline makes a scientific claim. Which action provides the strongest source check?","options":["Reject it automatically because it is news.","Count how many times it was reposted.","Trace the claim toward the original study, dataset, or agency report and compare its method, scope, and limitations with the headline.","Trust it because it names a scientist."],"answer":2,"explanation":"Evidence proximity and method transparency allow the public claim to be compared with the original evidence.","source":"unit-01","difficulty":"transfer","unit":"Unit 01","originalSource":"assessment"},{"id":"u01-a-a24","domain":"Safety & design","prompt":"During planning, an investigator discovers a hazard that cannot be reasonably controlled with available equipment or supervision. What should happen?","options":["Use fewer trials and proceed anyway.","Continue because data are important.","Remove the hazard from the written record.","Revise, replace, or postpone the method before collecting data."],"answer":3,"explanation":"Scientific value does not justify an uncontrolled hazard; the method must be made acceptably safe before data collection.","source":"unit-01","difficulty":"transfer","unit":"Unit 01","originalSource":"assessment"},{"id":"u02-q-q02","domain":"Cell theory","prompt":"Which observation most directly supports the conclusion that a specimen is cellular?","options":["It is green.","Repeated microscope views show membrane-bounded units with internal contents.","It moves when pushed.","It has a measurable mass."],"answer":1,"explanation":"Repeated observation of membrane-bounded units is direct evidence of cellular organization.","source":"unit-02","difficulty":"core","unit":"Unit 02","originalSource":"quiz"},{"id":"u02-q-q03","domain":"Cell types","prompt":"Which structure is present in both prokaryotic and eukaryotic cells?","options":["Mitochondrion","Golgi apparatus","Ribosome","Membrane-bound nucleus"],"answer":2,"explanation":"All cells use ribosomes to build proteins.","source":"unit-02","difficulty":"core","unit":"Unit 02","originalSource":"quiz"},{"id":"u02-q-q04","domain":"Cell types","prompt":"Which feature distinguishes a eukaryotic cell from a prokaryotic cell?","options":["Ribosomes","A plasma membrane","Cytoplasm","DNA enclosed within a membrane-bound nucleus"],"answer":3,"explanation":"Eukaryotic DNA is enclosed within a membrane-bound nucleus.","source":"unit-02","difficulty":"core","unit":"Unit 02","originalSource":"quiz"},{"id":"u02-q-q05","domain":"Organelles","prompt":"Which organelle is the main site of aerobic cellular respiration in eukaryotic cells?","options":["Mitochondrion","Ribosome","Cell wall","Vacuole"],"answer":0,"explanation":"Most stages of aerobic cellular respiration occur in mitochondria.","source":"unit-02","difficulty":"core","unit":"Unit 02","originalSource":"quiz"},{"id":"u02-q-q06","domain":"Organelles","prompt":"What is the primary role of ribosomes?","options":["Production of cellulose cell walls","Protein synthesis","Storage of hereditary information","Control of water movement by osmosis"],"answer":1,"explanation":"Ribosomes assemble amino acids into proteins.","source":"unit-02","difficulty":"core","unit":"Unit 02","originalSource":"quiz"},{"id":"u02-q-q07","domain":"Plant cells","prompt":"Which statement about plant cells is correct?","options":["All plant cells contain chloroplasts.","Plant cells do not contain mitochondria.","Photosynthetic plant cells commonly contain chloroplasts and mitochondria.","Plant cells lack a plasma membrane."],"answer":2,"explanation":"Photosynthetic plant cells commonly contain both chloroplasts and mitochondria.","source":"unit-02","difficulty":"core","unit":"Unit 02","originalSource":"quiz"},{"id":"u02-q-q08","domain":"Microscopy","prompt":"An image is 30 mm long and the specimen is 0.06 mm long. What is the magnification?","options":["×5000","×5","×50","×500"],"answer":3,"explanation":"30 ÷ 0.06 = 500.","source":"unit-02","difficulty":"core","unit":"Unit 02","originalSource":"quiz"},{"id":"u02-q-q09","domain":"Microscopy","prompt":"Which conversion is correct?","options":["1 mm = 1000 µm","1 µm = 1000 mm","1 mm = 10 µm","1 mm = 100 µm"],"answer":0,"explanation":"One millimeter equals one thousand micrometers.","source":"unit-02","difficulty":"core","unit":"Unit 02","originalSource":"quiz"},{"id":"u02-q-q10","domain":"Membranes","prompt":"What does selectively permeable mean?","options":["No substances can cross the membrane.","The membrane allows some substances to cross more readily than others.","Every substance crosses at the same rate.","Only water can ever cross."],"answer":1,"explanation":"Passage depends on properties such as size, charge, concentration, and transport proteins.","source":"unit-02","difficulty":"core","unit":"Unit 02","originalSource":"quiz"},{"id":"u02-q-q11","domain":"Diffusion","prompt":"Diffusion is best described as:","options":["Movement against a concentration gradient using cellular energy","The production of glucose using light","Net movement of particles from higher concentration to lower concentration due to random motion","Movement of water only through a membrane"],"answer":2,"explanation":"Diffusion is net movement down a concentration gradient arising from random particle motion.","source":"unit-02","difficulty":"core","unit":"Unit 02","originalSource":"quiz"},{"id":"u02-q-q12","domain":"Osmosis","prompt":"Osmosis specifically refers to the net movement of:","options":["Proteins from low concentration to high concentration","Oxygen using ATP","Any solute through any barrier","Water through a selectively permeable membrane"],"answer":3,"explanation":"Osmosis is net water movement through a selectively permeable membrane.","source":"unit-02","difficulty":"core","unit":"Unit 02","originalSource":"quiz"},{"id":"u02-q-q13","domain":"Transport","prompt":"Which process can move a substance against its concentration gradient?","options":["Active transport","Random mixing only","Simple diffusion","Osmosis"],"answer":0,"explanation":"Active transport uses cellular energy and transport proteins.","source":"unit-02","difficulty":"core","unit":"Unit 02","originalSource":"quiz"},{"id":"u02-q-q14","domain":"Cell size","prompt":"As a cube-shaped cell becomes larger, what generally happens to its surface-area-to-volume ratio?","options":["It increases","It decreases","It remains constant","It becomes zero immediately"],"answer":1,"explanation":"Volume increases faster than surface area.","source":"unit-02","difficulty":"core","unit":"Unit 02","originalSource":"quiz"},{"id":"u02-q-q15","domain":"Cell size","prompt":"Why is a higher surface-area-to-volume ratio often advantageous for a cell?","options":["It prevents all diffusion.","It guarantees the cell will be multicellular.","It increases exchange surface relative to the material that must be supplied.","It removes the need for a membrane."],"answer":2,"explanation":"More membrane surface relative to volume can support faster exchange per unit volume.","source":"unit-02","difficulty":"core","unit":"Unit 02","originalSource":"quiz"},{"id":"u02-q-q16","domain":"Specialization","prompt":"Which adaptation most directly helps a red blood cell carry oxygen?","options":["A cellulose wall","Chloroplasts","A large central vacuole","A biconcave shape and abundant hemoglobin"],"answer":3,"explanation":"The biconcave shape increases exchange area, and hemoglobin binds oxygen.","source":"unit-02","difficulty":"core","unit":"Unit 02","originalSource":"quiz"},{"id":"u02-q-q17","domain":"Organization","prompt":"Which sequence shows increasing biological organization in a multicellular organism?","options":["Cell → tissue → organ → organ system","Tissue → cell → organ system → organ","Cell → organ system → tissue → organ","Organ → tissue → cell → system"],"answer":0,"explanation":"Specialized cells form tissues; tissues form organs; organs cooperate in systems.","source":"unit-02","difficulty":"core","unit":"Unit 02","originalSource":"quiz"},{"id":"u02-q-q18","domain":"Energy","prompt":"Which statement correctly compares photosynthesis and cellular respiration?","options":["Only animals perform cellular respiration.","Photosynthesis stores energy in organic molecules; cellular respiration releases usable chemical energy from organic molecules.","Both processes occur only in chloroplasts.","Photosynthesis consumes oxygen and releases glucose."],"answer":1,"explanation":"Photosynthesis stores light energy; respiration transfers energy from organic molecules to usable cellular forms.","source":"unit-02","difficulty":"core","unit":"Unit 02","originalSource":"quiz"},{"id":"u02-q-q19","domain":"Models","prompt":"Which is a limitation of a typical textbook cell diagram?","options":["It proves every cell has the same shape.","It is always a direct photograph.","It may show structures at unrealistic relative sizes and fixed positions.","It contains no information at all."],"answer":2,"explanation":"Diagrams simplify and reorganize structures for clarity.","source":"unit-02","difficulty":"core","unit":"Unit 02","originalSource":"quiz"},{"id":"u02-q-q20","domain":"Evidence","prompt":"A microscope image shows a cell wall and chloroplasts. Which conclusion is best supported?","options":["The cell must be a bacterium.","The cell cannot perform respiration.","Every cell in the organism has chloroplasts.","The cell is a photosynthetic eukaryotic cell."],"answer":3,"explanation":"A cell wall plus chloroplasts supports classification as a photosynthetic eukaryotic cell.","source":"unit-02","difficulty":"core","unit":"Unit 02","originalSource":"quiz"},{"id":"u02-a-a01","domain":"Cell theory","prompt":"Which statement is NOT part of modern cell theory?","options":["Every cell contains a membrane-bound nucleus.","Cells are the basic unit of life.","Living organisms are made of one or more cells.","New cells arise from pre-existing cells."],"answer":0,"explanation":"Prokaryotic cells do not contain a membrane-bound nucleus.","source":"unit-02","difficulty":"transfer","unit":"Unit 02","originalSource":"assessment"},{"id":"u02-a-a02","domain":"Cell theory","prompt":"Why did improved microscopes strengthen cell theory?","options":["They proved viruses are cells.","They allowed repeated observation of cells and cell division in many organisms.","They made living things larger.","They removed the need for evidence."],"answer":1,"explanation":"Improved microscopes provided repeatable observations of cellular structure and reproduction.","source":"unit-02","difficulty":"transfer","unit":"Unit 02","originalSource":"assessment"},{"id":"u02-a-a03","domain":"Cell theory","prompt":"Which entity is acellular rather than a complete cell?","options":["Bacterium","Yeast cell","Virus particle","Amoeba"],"answer":2,"explanation":"Viruses are acellular particles that depend on host cells for replication.","source":"unit-02","difficulty":"transfer","unit":"Unit 02","originalSource":"assessment"},{"id":"u02-a-a04","domain":"Cell types","prompt":"Which feature is found in a typical bacterial cell?","options":["A membrane-bound nucleus","Mitochondria","Chloroplasts","Circular DNA in a nucleoid region"],"answer":3,"explanation":"Typical bacteria have DNA in a nucleoid region.","source":"unit-02","difficulty":"transfer","unit":"Unit 02","originalSource":"assessment"},{"id":"u02-a-a05","domain":"Cell types","prompt":"Which pair is present in all known cells?","options":["Plasma membrane and ribosomes","Nucleus and mitochondria","Cell wall and chloroplasts","Golgi apparatus and lysosomes"],"answer":0,"explanation":"All cells have a plasma membrane and ribosomes.","source":"unit-02","difficulty":"transfer","unit":"Unit 02","originalSource":"assessment"},{"id":"u02-a-a06","domain":"Cell types","prompt":"Which statement avoids an inaccurate hierarchy between prokaryotes and eukaryotes?","options":["Prokaryotes are unfinished eukaryotic cells.","Prokaryotes and eukaryotes have different cellular organizations adapted to their ways of life.","Eukaryotes are always more successful.","Prokaryotes have no internal organization."],"answer":1,"explanation":"Both groups are highly evolved and differ in organization.","source":"unit-02","difficulty":"transfer","unit":"Unit 02","originalSource":"assessment"},{"id":"u02-a-a07","domain":"Organelles","prompt":"Which organelle modifies, sorts, and packages many proteins in eukaryotic cells?","options":["Nucleoid","Chloroplast","Golgi apparatus","Cell wall"],"answer":2,"explanation":"The Golgi apparatus modifies, sorts, and packages many proteins and lipids.","source":"unit-02","difficulty":"transfer","unit":"Unit 02","originalSource":"assessment"},{"id":"u02-a-a08","domain":"Organelles","prompt":"Which structure contains most of a eukaryotic cell's DNA?","options":["Ribosome","Cell wall","Cytosol","Nucleus"],"answer":3,"explanation":"Most eukaryotic DNA is enclosed in the nucleus.","source":"unit-02","difficulty":"transfer","unit":"Unit 02","originalSource":"assessment"},{"id":"u02-a-a09","domain":"Organelles","prompt":"Which structure provides rigid support outside the plasma membrane of plant cells?","options":["Cellulose cell wall","Mitochondrion","Nucleus","Ribosome"],"answer":0,"explanation":"The cellulose cell wall supports and protects plant cells.","source":"unit-02","difficulty":"transfer","unit":"Unit 02","originalSource":"assessment"},{"id":"u02-a-a10","domain":"Organelles","prompt":"What is a central role of a large plant-cell vacuole?","options":["Carrying out all cellular respiration","Maintaining internal water storage and turgor pressure","Producing ribosomes","Enclosing the cell's chromosomes"],"answer":1,"explanation":"The central vacuole stores water and solutes and helps maintain turgor.","source":"unit-02","difficulty":"transfer","unit":"Unit 02","originalSource":"assessment"},{"id":"u02-a-a11","domain":"Microscopy","prompt":"A 24 mm image was produced at ×400 magnification. What is the actual specimen length?","options":["6 mm","9600 mm","0.06 mm","0.6 mm"],"answer":2,"explanation":"24 ÷ 400 = 0.06 mm.","source":"unit-02","difficulty":"transfer","unit":"Unit 02","originalSource":"assessment"},{"id":"u02-a-a12","domain":"Microscopy","prompt":"What is 0.06 mm expressed in micrometers?","options":["6000 µm","0.06 µm","6 µm","60 µm"],"answer":3,"explanation":"0.06 mm × 1000 = 60 µm.","source":"unit-02","difficulty":"transfer","unit":"Unit 02","originalSource":"assessment"},{"id":"u02-a-a13","domain":"Microscopy","prompt":"A ×10 eyepiece and ×40 objective produce what total magnification?","options":["×400","×4000","×4","×50"],"answer":0,"explanation":"10 × 40 = 400.","source":"unit-02","difficulty":"transfer","unit":"Unit 02","originalSource":"assessment"},{"id":"u02-a-a14","domain":"Microscopy","prompt":"Which observation method gives the strongest evidence about a cell's three-dimensional internal structure?","options":["A single simplified diagram","Multiple images or sections from different depths and orientations","A title without an image","One color label"],"answer":1,"explanation":"Multiple sections or orientations provide stronger three-dimensional evidence.","source":"unit-02","difficulty":"transfer","unit":"Unit 02","originalSource":"assessment"},{"id":"u02-a-a15","domain":"Membranes","prompt":"Which factor can directly influence whether an ion crosses a cell membrane?","options":["The diagram's background color","Whether the organism is visible without a microscope","Availability and state of a suitable membrane transport protein","The cell's name"],"answer":2,"explanation":"Charged ions generally require specific channels or carriers.","source":"unit-02","difficulty":"transfer","unit":"Unit 02","originalSource":"assessment"},{"id":"u02-a-a16","domain":"Diffusion","prompt":"At diffusion equilibrium, particles:","options":["All move in one direction.","Require ATP for every movement.","Stop moving completely.","Continue random motion, but there is no net concentration change."],"answer":3,"explanation":"Particles continue random motion while net movement is balanced.","source":"unit-02","difficulty":"transfer","unit":"Unit 02","originalSource":"assessment"},{"id":"u02-a-a17","domain":"Diffusion","prompt":"Which change would generally increase the diffusion rate of dye in water?","options":["Increasing temperature within the safe tested range","Eliminating the concentration gradient","Increasing diffusion distance","Turning the water into a solid"],"answer":0,"explanation":"Higher temperature generally increases particle motion.","source":"unit-02","difficulty":"transfer","unit":"Unit 02","originalSource":"assessment"},{"id":"u02-a-a18","domain":"Osmosis","prompt":"A plant cell is placed in a solution more dilute than its cell contents. What is the expected net water movement?","options":["Water changes into solute","Into the cell","Out of the cell","No water molecules move"],"answer":1,"explanation":"Water tends to move into the more concentrated cell contents.","source":"unit-02","difficulty":"transfer","unit":"Unit 02","originalSource":"assessment"},{"id":"u02-a-a19","domain":"Osmosis","prompt":"A potato sample changes from 5.0 g to 4.5 g. What is the percent mass change?","options":["−0.5%","+0.5%","−10%","+10%"],"answer":2,"explanation":"(4.5 − 5.0) ÷ 5.0 × 100 = −10%.","source":"unit-02","difficulty":"transfer","unit":"Unit 02","originalSource":"assessment"},{"id":"u02-a-a20","domain":"Transport","prompt":"Which condition is required for active transport?","options":["Movement only from high to low concentration","No membrane","A dead cell with no metabolism","A cellular energy supply and suitable transport proteins"],"answer":3,"explanation":"Active transport depends on energy and specific membrane proteins.","source":"unit-02","difficulty":"transfer","unit":"Unit 02","originalSource":"assessment"},{"id":"u02-a-a21","domain":"Transport","prompt":"Which example is best explained by active transport?","options":["Mineral ions accumulated by root cells against a concentration gradient","Perfume spreading across a room","Water entering a cell by osmosis","Food coloring dispersing in water"],"answer":0,"explanation":"Root cells can accumulate mineral ions against their gradient.","source":"unit-02","difficulty":"transfer","unit":"Unit 02","originalSource":"assessment"},{"id":"u02-a-a22","domain":"Cell size","prompt":"What is the surface-area-to-volume ratio of a cube with side length 2 cm?","options":["24:1","3:1","6:1","8:1"],"answer":1,"explanation":"Surface area 24 and volume 8 give 3:1.","source":"unit-02","difficulty":"transfer","unit":"Unit 02","originalSource":"assessment"},{"id":"u02-a-a23","domain":"Cell size","prompt":"Which adaptation increases exchange surface without greatly increasing cell volume?","options":["Making the cell a solid block","Eliminating concentration gradients","Folds or projections in the membrane","Removing the membrane"],"answer":2,"explanation":"Folds and projections increase membrane surface area.","source":"unit-02","difficulty":"transfer","unit":"Unit 02","originalSource":"assessment"},{"id":"u02-a-a24","domain":"Specialization","prompt":"Which structure-function relationship is correct?","options":["Neuron — cellulose wall speeds electrical signaling","Sperm cell — chloroplasts provide propulsion","Palisade cell — no chloroplasts","Root hair cell — long projection increases absorption surface"],"answer":3,"explanation":"A root hair cell's projection increases absorption surface.","source":"unit-02","difficulty":"transfer","unit":"Unit 02","originalSource":"assessment"},{"id":"u02-a-a25","domain":"Specialization","prompt":"Why can specialized cells in a multicellular organism depend on one another?","options":["They divide labor and exchange materials through tissues and systems.","Each performs every possible function independently.","Specialization removes the need for transport.","All specialized cells have identical structures."],"answer":0,"explanation":"Specialization divides functions and creates interdependence.","source":"unit-02","difficulty":"transfer","unit":"Unit 02","originalSource":"assessment"},{"id":"u02-a-a26","domain":"Organization","prompt":"Which example is an organ?","options":["Circulatory system","Heart","Cardiac muscle tissue","Cardiac muscle cell"],"answer":1,"explanation":"The heart is an organ composed of multiple tissues.","source":"unit-02","difficulty":"transfer","unit":"Unit 02","originalSource":"assessment"},{"id":"u02-a-a27","domain":"Energy","prompt":"Which substances are reactants in photosynthesis?","options":["Protein and ATP","Oxygen and water only","Carbon dioxide and water","Glucose and oxygen"],"answer":2,"explanation":"Photosynthesis uses carbon dioxide and water with light energy.","source":"unit-02","difficulty":"transfer","unit":"Unit 02","originalSource":"assessment"},{"id":"u02-a-a28","domain":"Energy","prompt":"Which statement about plant cellular respiration is correct?","options":["Plant cells perform respiration only at night.","Only chloroplasts perform respiration.","Respiration creates energy from nothing.","Plant cells perform cellular respiration as well as photosynthesis."],"answer":3,"explanation":"Plant cells respire continuously; photosynthetic cells also photosynthesize in suitable light.","source":"unit-02","difficulty":"transfer","unit":"Unit 02","originalSource":"assessment"},{"id":"u02-a-a29","domain":"Models","prompt":"Why should a model include a stated limitation?","options":["Every model emphasizes some features and omits or simplifies others.","Models contain no evidence.","A limitation makes every conclusion false.","Scientific models never change."],"answer":0,"explanation":"Models are selective representations.","source":"unit-02","difficulty":"transfer","unit":"Unit 02","originalSource":"assessment"},{"id":"u02-a-a30","domain":"Evidence","prompt":"A student claims every plant cell contains chloroplasts after viewing one leaf cell. What is the best evaluation?","options":["The claim shows chloroplasts occur in animal cells.","The claim is too broad because one leaf cell does not represent all plant cell types.","The claim is proven for every plant cell.","The claim proves roots photosynthesize."],"answer":1,"explanation":"One leaf cell cannot justify a universal claim about every plant cell type.","source":"unit-02","difficulty":"transfer","unit":"Unit 02","originalSource":"assessment"},{"id":"u03-q-x02","domain":"Systems and homeostasis","prompt":"In negative feedback, the response generally:","options":["Stops communication","Opposes the initial change","Amplifies change without limit","Removes the receptor"],"answer":1,"explanation":"Negative feedback counteracts deviation.","source":"unit-03","difficulty":"core","unit":"Unit 03","originalSource":"quiz"},{"id":"u03-q-x04","domain":"Systems and homeostasis","prompt":"Which is commonly modeled as positive feedback?","options":["Sweating","Insulin after a meal","Water conservation","Blood clotting at a damaged vessel"],"answer":3,"explanation":"Clotting amplifies locally until the break is sealed.","source":"unit-03","difficulty":"core","unit":"Unit 03","originalSource":"quiz"},{"id":"u03-q-x05","domain":"Systems and homeostasis","prompt":"Right ventricle to left atrium route:","options":["Pulmonary artery → lung capillaries → pulmonary veins","Aorta → body → vena cava","Pulmonary vein → body → aorta","Vena cava → kidney → pulmonary artery"],"answer":0,"explanation":"This is pulmonary circulation.","source":"unit-03","difficulty":"core","unit":"Unit 03","originalSource":"quiz"},{"id":"u03-q-x06","domain":"Systems and homeostasis","prompt":"Which statement is correct?","options":["Only veins have walls","Arteries carry blood away; veins carry blood toward the heart","Arteries always carry oxygen-rich blood","Veins always carry oxygen-poor blood"],"answer":1,"explanation":"Direction defines the vessel type.","source":"unit-03","difficulty":"core","unit":"Unit 03","originalSource":"quiz"},{"id":"u03-q-x07","domain":"Systems and homeostasis","prompt":"Which alveolar feature supports rapid exchange?","options":["No blood supply","Cellulose walls","Large surface area and thin surfaces","Thick dry walls"],"answer":2,"explanation":"Large area and short distance support diffusion.","source":"unit-03","difficulty":"core","unit":"Unit 03","originalSource":"quiz"},{"id":"u03-q-x08","domain":"Systems and homeostasis","prompt":"Breathing and cellular respiration differ because:","options":["Breathing produces glucose","Respiration occurs only in lungs","They are identical","Breathing moves air; respiration transfers chemical energy in cells"],"answer":3,"explanation":"They are distinct processes.","source":"unit-03","difficulty":"core","unit":"Unit 03","originalSource":"quiz"},{"id":"u03-q-x09","domain":"Systems and homeostasis","prompt":"Why does heart rate often rise during activity?","options":["To increase transport and heat/waste removal","To stop blood flow","To thicken alveoli","To eliminate all temperature variation"],"answer":0,"explanation":"Transport demand increases.","source":"unit-03","difficulty":"core","unit":"Unit 03","originalSource":"quiz"},{"id":"u03-q-x10","domain":"Systems and homeostasis","prompt":"Chemical digestion mainly:","options":["Converts nutrients to heat before absorption","Breaks large insoluble molecules into small soluble molecules","Moves only undigested food","Produces oxygen"],"answer":1,"explanation":"Small soluble molecules can be absorbed.","source":"unit-03","difficulty":"core","unit":"Unit 03","originalSource":"quiz"},{"id":"u03-q-x11","domain":"Systems and homeostasis","prompt":"Which increases small-intestine absorption area?","options":["One large chamber","Cartilage rings","Villi and microvilli","Keratin"],"answer":2,"explanation":"Villi and microvilli increase surface area.","source":"unit-03","difficulty":"core","unit":"Unit 03","originalSource":"quiz"},{"id":"u03-q-x12","domain":"Systems and homeostasis","prompt":"Kidneys mainly excrete:","options":["Undigested food","Oxygen and glucose","Antibodies and red cells","Urea, excess water, and excess ions"],"answer":3,"explanation":"These are major urine components.","source":"unit-03","difficulty":"core","unit":"Unit 03","originalSource":"quiz"},{"id":"u03-q-x13","domain":"Systems and homeostasis","prompt":"During dehydration, increased ADH causes:","options":["More water reabsorption and lower urine volume","Excretion of all water","Permanent stop of filtration","Glucose release into urine"],"answer":0,"explanation":"ADH helps conserve water.","source":"unit-03","difficulty":"core","unit":"Unit 03","originalSource":"quiz"},{"id":"u03-q-x14","domain":"Systems and homeostasis","prompt":"Which helps increase heat loss?","options":["Stopping circulation","Sweating and increased skin blood flow","Shivering and reduced skin flow","Reducing evaporation"],"answer":1,"explanation":"These support cooling.","source":"unit-03","difficulty":"core","unit":"Unit 03","originalSource":"quiz"},{"id":"u03-q-x15","domain":"Systems and homeostasis","prompt":"After blood glucose rises, insulin promotes:","options":["Shutdown of respiration","Conversion of all proteins to glucose","Uptake and storage","Release of stored glucose"],"answer":2,"explanation":"Insulin lowers elevated glucose.","source":"unit-03","difficulty":"core","unit":"Unit 03","originalSource":"quiz"},{"id":"u03-q-x16","domain":"Systems and homeostasis","prompt":"A simple reflex arc is:","options":["Effector → motor → receptor","Hormone → artery → kidney","Muscle → bone → blood","Receptor → sensory → relay → motor → effector"],"answer":3,"explanation":"This is the correct pathway.","source":"unit-03","difficulty":"core","unit":"Unit 03","originalSource":"quiz"},{"id":"u03-q-x17","domain":"Systems and homeostasis","prompt":"At a chemical synapse, neurotransmitters:","options":["Cross the gap and bind receptors","Become red cells","Move through bone","Replace DNA"],"answer":0,"explanation":"They bind receptors on the next cell.","source":"unit-03","difficulty":"core","unit":"Unit 03","originalSource":"quiz"},{"id":"u03-q-x18","domain":"Systems and homeostasis","prompt":"Endocrine signals are often:","options":["Unable to affect cells","Slower to begin and longer lasting","Always faster and shorter","Carried only through neurones"],"answer":1,"explanation":"Hormonal signals often have slower onset and longer duration.","source":"unit-03","difficulty":"core","unit":"Unit 03","originalSource":"quiz"},{"id":"u03-q-x19","domain":"Systems and homeostasis","prompt":"A first-line defense includes:","options":["Antibody production only","Fever only","Skin and mucus","Memory cells only"],"answer":2,"explanation":"Skin and mucus reduce entry.","source":"unit-03","difficulty":"core","unit":"Unit 03","originalSource":"quiz"},{"id":"u03-q-x20","domain":"Systems and homeostasis","prompt":"Body systems are best described as:","options":["Independent systems","Only nervous regulation","Replacements for cells","Interdependent networks exchanging matter, energy, and information"],"answer":3,"explanation":"Systems interact continuously.","source":"unit-03","difficulty":"core","unit":"Unit 03","originalSource":"quiz"},{"id":"u03-a-x01","domain":"Systems and homeostasis","prompt":"A regulated set range is:","options":["A functional interval around a target","A number that never changes","External temperature only","Unrelated to feedback"],"answer":0,"explanation":"Regulation usually maintains a range.","source":"unit-03","difficulty":"transfer","unit":"Unit 03","originalSource":"assessment"},{"id":"u03-a-x02","domain":"Systems and homeostasis","prompt":"Body temperature rises. First event in a feedback model:","options":["Response ends","Receptors detect the change","Sweat evaporates","Temperature falls"],"answer":1,"explanation":"Detection comes first.","source":"unit-03","difficulty":"transfer","unit":"Unit 03","originalSource":"assessment"},{"id":"u03-a-x03","domain":"Systems and homeostasis","prompt":"Negative feedback is stabilizing because:","options":["It destroys the receptor","It ignores change","It reduces the triggering deviation","It increases every deviation"],"answer":2,"explanation":"It opposes deviation.","source":"unit-03","difficulty":"transfer","unit":"Unit 03","originalSource":"assessment"},{"id":"u03-a-x04","domain":"Systems and homeostasis","prompt":"Positive feedback is not usually long-term regulation because:","options":["It always lowers variables","It has no effectors","It prevents communication","It amplifies change until an endpoint"],"answer":3,"explanation":"It reinforces change.","source":"unit-03","difficulty":"transfer","unit":"Unit 03","originalSource":"assessment"},{"id":"u03-a-x05","domain":"Systems and homeostasis","prompt":"Which chamber pumps systemic circulation?","options":["Left ventricle","Right atrium","Left atrium","Right ventricle"],"answer":0,"explanation":"The left ventricle pumps through the aorta.","source":"unit-03","difficulty":"transfer","unit":"Unit 03","originalSource":"assessment"},{"id":"u03-a-x06","domain":"Systems and homeostasis","prompt":"Which vessel carries blood to lungs?","options":["Vena cava","Pulmonary artery","Pulmonary vein","Aorta"],"answer":1,"explanation":"The pulmonary artery carries blood to lungs.","source":"unit-03","difficulty":"transfer","unit":"Unit 03","originalSource":"assessment"},{"id":"u03-a-x07","domain":"Systems and homeostasis","prompt":"Major capillary function:","options":["Produce enzymes","Store urine","Thin exchange surface","Generate brain impulses"],"answer":2,"explanation":"Capillaries support exchange.","source":"unit-03","difficulty":"transfer","unit":"Unit 03","originalSource":"assessment"},{"id":"u03-a-x08","domain":"Systems and homeostasis","prompt":"Primary oxygen-transport component:","options":["Platelets","Plasma proteins only","White cells","Red cells with hemoglobin"],"answer":3,"explanation":"Hemoglobin carries oxygen.","source":"unit-03","difficulty":"transfer","unit":"Unit 03","originalSource":"assessment"},{"id":"u03-a-x09","domain":"Systems and homeostasis","prompt":"Oxygen moves from alveoli to blood mainly because:","options":["A concentration gradient exists","Active transport pumps it","It becomes glucose","Walls are impermeable"],"answer":0,"explanation":"Diffusion follows the gradient.","source":"unit-03","difficulty":"transfer","unit":"Unit 03","originalSource":"assessment"},{"id":"u03-a-x10","domain":"Systems and homeostasis","prompt":"Which reduces gas exchange efficiency?","options":["Continuous blood flow","Increased diffusion distance","Maintaining a gradient","Large surface area"],"answer":1,"explanation":"Longer distance slows diffusion.","source":"unit-03","difficulty":"transfer","unit":"Unit 03","originalSource":"assessment"},{"id":"u03-a-x11","domain":"Systems and homeostasis","prompt":"Pulse rises from 72 to 108. Percent increase:","options":["72%","150%","50%","36%"],"answer":2,"explanation":"36/72 × 100 = 50%.","source":"unit-03","difficulty":"transfer","unit":"Unit 03","originalSource":"assessment"},{"id":"u03-a-x12","domain":"Systems and homeostasis","prompt":"Why not diagnose from one classroom pulse response?","options":["Heart rate never changes","Pulse has no information","Only exercise affects pulse","It has many sources of variation and is not a clinical evaluation"],"answer":3,"explanation":"One short observation is insufficient.","source":"unit-03","difficulty":"transfer","unit":"Unit 03","originalSource":"assessment"},{"id":"u03-a-x13","domain":"Systems and homeostasis","prompt":"Which organ produces bile?","options":["Liver","Stomach","Pancreas","Small intestine"],"answer":0,"explanation":"The liver produces bile.","source":"unit-03","difficulty":"transfer","unit":"Unit 03","originalSource":"assessment"},{"id":"u03-a-x14","domain":"Systems and homeostasis","prompt":"Bile helps fat digestion by:","options":["Producing insulin","Emulsifying fat to increase surface area","Converting fat to amino acids","Absorbing glucose"],"answer":1,"explanation":"Emulsification supports lipase action.","source":"unit-03","difficulty":"transfer","unit":"Unit 03","originalSource":"assessment"},{"id":"u03-a-x15","domain":"Systems and homeostasis","prompt":"Absorbed glucose and amino acids leave villi mainly in:","options":["Ureters","Motor neurones","Blood capillaries","Alveoli"],"answer":2,"explanation":"Capillaries transport them.","source":"unit-03","difficulty":"transfer","unit":"Unit 03","originalSource":"assessment"},{"id":"u03-a-x16","domain":"Systems and homeostasis","prompt":"Excretion differs from egestion because:","options":["Both mean urination","Egestion removes carbon dioxide","Excretion removes only feces","Excretion removes metabolic wastes; egestion removes undigested material"],"answer":3,"explanation":"The processes remove different materials.","source":"unit-03","difficulty":"transfer","unit":"Unit 03","originalSource":"assessment"},{"id":"u03-a-x17","domain":"Systems and homeostasis","prompt":"Normally reabsorbed completely from filtrate:","options":["Glucose","Urea","All water","All sodium"],"answer":0,"explanation":"Glucose is normally reabsorbed.","source":"unit-03","difficulty":"transfer","unit":"Unit 03","originalSource":"assessment"},{"id":"u03-a-x18","domain":"Systems and homeostasis","prompt":"Higher ADH causes:","options":["No filtration","More water reabsorption","Less water reabsorption","More glucose excretion"],"answer":1,"explanation":"ADH promotes water recovery.","source":"unit-03","difficulty":"transfer","unit":"Unit 03","originalSource":"assessment"},{"id":"u03-a-x19","domain":"Systems and homeostasis","prompt":"Which conserves heat?","options":["Increased evaporation","Stopping muscle activity","Reduced skin blood flow and shivering","Sweating and increased skin flow"],"answer":2,"explanation":"These conserve and produce heat.","source":"unit-03","difficulty":"transfer","unit":"Unit 03","originalSource":"assessment"},{"id":"u03-a-x20","domain":"Systems and homeostasis","prompt":"Sweating cools because:","options":["Sweat freezes blood","Sweat stops metabolism","Evaporation creates energy","Evaporation transfers thermal energy from skin"],"answer":3,"explanation":"Evaporation requires energy.","source":"unit-03","difficulty":"transfer","unit":"Unit 03","originalSource":"assessment"},{"id":"u03-a-x21","domain":"Systems and homeostasis","prompt":"Which hormone raises low blood glucose?","options":["Glucagon","Insulin","ADH","Thyroxine"],"answer":0,"explanation":"Glucagon promotes glucose release.","source":"unit-03","difficulty":"transfer","unit":"Unit 03","originalSource":"assessment"},{"id":"u03-a-x22","domain":"Systems and homeostasis","prompt":"Insulin and glucagon:","options":["Do not affect liver","Have opposing regulatory effects","Both always lower glucose","Are digestive enzymes"],"answer":1,"explanation":"They act antagonistically.","source":"unit-03","difficulty":"transfer","unit":"Unit 03","originalSource":"assessment"},{"id":"u03-a-x23","domain":"Systems and homeostasis","prompt":"Brain and spinal cord form the:","options":["Endocrine system","Circulatory system","Central nervous system","Peripheral nervous system"],"answer":2,"explanation":"They form the CNS.","source":"unit-03","difficulty":"transfer","unit":"Unit 03","originalSource":"assessment"},{"id":"u03-a-x24","domain":"Systems and homeostasis","prompt":"A receptor in a reflex pathway:","options":["Contracts as final effector","Produces urine","Transports oxygen","Detects stimulus and initiates signal"],"answer":3,"explanation":"Receptors detect change.","source":"unit-03","difficulty":"transfer","unit":"Unit 03","originalSource":"assessment"},{"id":"u03-a-x25","domain":"Systems and homeostasis","prompt":"Only some cells respond to a hormone because:","options":["Only target cells have the receptor","Hormones cannot travel in blood","Every hormone enters every nucleus","Hormones are antibodies"],"answer":0,"explanation":"Receptors determine response.","source":"unit-03","difficulty":"transfer","unit":"Unit 03","originalSource":"assessment"},{"id":"u03-a-x26","domain":"Systems and homeostasis","prompt":"Accurate comparison:","options":["Both are identical","Nervous signals are often rapid/targeted; endocrine signals slower/distributed","Endocrine signals travel through bone","Nervous signals never use chemicals"],"answer":1,"explanation":"The systems differ in route and timing.","source":"unit-03","difficulty":"transfer","unit":"Unit 03","originalSource":"assessment"},{"id":"u03-a-x27","domain":"Systems and homeostasis","prompt":"Cells that can produce antibodies after activation:","options":["Platelets","Neurones","B lymphocytes and plasma-cell descendants","Red cells"],"answer":2,"explanation":"Activated B cells produce plasma cells.","source":"unit-03","difficulty":"transfer","unit":"Unit 03","originalSource":"assessment"},{"id":"u03-a-x28","domain":"Systems and homeostasis","prompt":"Immune memory cells support:","options":["Oxygen transport","Starch digestion","Urine regulation","Faster later response to the same antigen"],"answer":3,"explanation":"Memory supports secondary responses.","source":"unit-03","difficulty":"transfer","unit":"Unit 03","originalSource":"assessment"},{"id":"u03-a-x29","domain":"Systems and homeostasis","prompt":"Strong health evidence includes:","options":["Transparent methods, comparisons, and limitations","Dramatic headline","Testimonial only","Universal claim from one result"],"answer":0,"explanation":"Transparent methods support evaluation.","source":"unit-03","difficulty":"transfer","unit":"Unit 03","originalSource":"assessment"},{"id":"u03-a-x30","domain":"Systems and homeostasis","prompt":"During exercise, oxygen delivery and carbon-dioxide removal directly require:","options":["Skin alone","Respiratory and circulatory systems","Digestive and skeletal only","Urinary and reproductive only"],"answer":1,"explanation":"These systems cooperate directly.","source":"unit-03","difficulty":"transfer","unit":"Unit 03","originalSource":"assessment"},{"id":"u04-q-q01","domain":"Genetic information","prompt":"Which statement correctly relates a gene to DNA?","options":["A gene is a segment of DNA involved in a functional product or regulation.","A gene is a protein surrounding every chromosome.","A gene is the complete genome.","A gene is a whole cell."],"answer":0,"explanation":"A gene is a functional or regulatory DNA region.","source":"unit-04","difficulty":"core","unit":"Unit 04","originalSource":"quiz"},{"id":"u04-q-q02","domain":"Genetic information","prompt":"An allele is:","options":["A complete chromosome set","A variant form of a gene","Any environmental influence","A type of cell division"],"answer":1,"explanation":"Alleles are variant forms of a gene.","source":"unit-04","difficulty":"core","unit":"Unit 04","originalSource":"quiz"},{"id":"u04-q-q03","domain":"Cell cycle","prompt":"During which part of the cell cycle is DNA copied?","options":["G1 only","Mitosis after separation","S phase of interphase","Cytokinesis"],"answer":2,"explanation":"DNA replication occurs during S phase.","source":"unit-04","difficulty":"core","unit":"Unit 04","originalSource":"quiz"},{"id":"u04-q-q04","domain":"Mitosis","prompt":"Mitosis followed by cytokinesis in a typical diploid body cell usually produces:","options":["One tetraploid cell","Two gametes","Four haploid cells","Two cells with the same chromosome number as the parent"],"answer":3,"explanation":"Chromosome number is maintained.","source":"unit-04","difficulty":"core","unit":"Unit 04","originalSource":"quiz"},{"id":"u04-q-q05","domain":"Differentiation","prompt":"Cells with similar DNA can have different functions mainly because:","options":["Different genes are expressed","DNA becomes a different chemical","Only nerve cells have genes","They lose all unused chromosomes"],"answer":0,"explanation":"Differential gene expression supports specialization.","source":"unit-04","difficulty":"core","unit":"Unit 04","originalSource":"quiz"},{"id":"u04-q-q06","domain":"Cell-cycle control","prompt":"A checkpoint can:","options":["Prevent every mutation","Delay division when problems are detected","Convert mitosis to meiosis","Repair every damaged cell"],"answer":1,"explanation":"Checkpoints monitor conditions but are imperfect.","source":"unit-04","difficulty":"core","unit":"Unit 04","originalSource":"quiz"},{"id":"u04-q-q07","domain":"Reproduction","prompt":"Asexual offspring are generally:","options":["Unable to survive change","Produced from two parents","Very similar to one parent except for mutation and other changes","Always polyploid"],"answer":2,"explanation":"Asexual reproduction copies one parent's genetic information.","source":"unit-04","difficulty":"core","unit":"Unit 04","originalSource":"quiz"},{"id":"u04-q-q08","domain":"Meiosis","prompt":"Meiosis is a reduction division because:","options":["It removes all mutations","It shortens chromosomes","It blocks replication","It halves chromosome number"],"answer":3,"explanation":"Meiosis produces haploid cells.","source":"unit-04","difficulty":"core","unit":"Unit 04","originalSource":"quiz"},{"id":"u04-q-q09","domain":"Meiosis","prompt":"Homologous chromosomes are:","options":["A pair carrying corresponding genes, one from each parent","Two unrelated chromosomes","Bacterial plasmids","Identical sister chromatids"],"answer":0,"explanation":"Homologues carry corresponding loci and may have different alleles.","source":"unit-04","difficulty":"core","unit":"Unit 04","originalSource":"quiz"},{"id":"u04-q-q10","domain":"Variation","prompt":"Which process creates new allele combinations during meiosis?","options":["Translation","Crossing over","Cytokinesis only","Binary fission"],"answer":1,"explanation":"Crossing over recombines chromosome segments.","source":"unit-04","difficulty":"core","unit":"Unit 04","originalSource":"quiz"},{"id":"u04-q-q11","domain":"Variation","prompt":"Independent assortment refers to:","options":["Every gene moving independently even when linked","Asexual reproduction","Random orientation and separation of homologous pairs","DNA replication"],"answer":2,"explanation":"Pair orientation creates chromosome combinations.","source":"unit-04","difficulty":"core","unit":"Unit 04","originalSource":"quiz"},{"id":"u04-q-q12","domain":"Fertilization","prompt":"Fertilization restores:","options":["Four nuclei","A chromosome-free cell","The haploid number","The diploid number"],"answer":3,"explanation":"Gamete fusion restores diploidy.","source":"unit-04","difficulty":"core","unit":"Unit 04","originalSource":"quiz"},{"id":"u04-q-q13","domain":"Inheritance language","prompt":"A dominant allele is one that:","options":["Is expressed in a heterozygote under the model","Is healthier","Prevents mutation","Is most common"],"answer":0,"explanation":"Dominance describes heterozygous expression, not value.","source":"unit-04","difficulty":"core","unit":"Unit 04","originalSource":"quiz"},{"id":"u04-q-q14","domain":"Inheritance language","prompt":"Genotype refers to:","options":["Environment","The allele combination considered","The species","Observable trait only"],"answer":1,"explanation":"Genotype is the allele combination.","source":"unit-04","difficulty":"core","unit":"Unit 04","originalSource":"quiz"},{"id":"u04-q-q15","domain":"Probability","prompt":"For Aa × Aa, the probability of aa is:","options":["75%","0%","25%","50%"],"answer":2,"explanation":"One of four combinations is aa.","source":"unit-04","difficulty":"core","unit":"Unit 04","originalSource":"quiz"},{"id":"u04-q-q16","domain":"Probability","prompt":"After three dominant-phenotype offspring in Aa × Aa, the next offspring's probability of aa is:","options":["50%","100%","0%","25%"],"answer":3,"explanation":"Each event remains independent.","source":"unit-04","difficulty":"core","unit":"Unit 04","originalSource":"quiz"},{"id":"u04-q-q17","domain":"Non-simple inheritance","prompt":"Incomplete dominance commonly gives a heterozygote:","options":["An intermediate phenotype","No phenotype","Both alleles hidden","Double chromosome number"],"answer":0,"explanation":"The heterozygote is intermediate.","source":"unit-04","difficulty":"core","unit":"Unit 04","originalSource":"quiz"},{"id":"u04-q-q18","domain":"Non-simple inheritance","prompt":"Codominance means a heterozygote:","options":["Has one allele","Expresses both allele products","Expresses neither","Is always intermediate"],"answer":1,"explanation":"Both products are detectably expressed.","source":"unit-04","difficulty":"core","unit":"Unit 04","originalSource":"quiz"},{"id":"u04-q-q19","domain":"Mutation","prompt":"Which statement about mutation is correct?","options":["Replication errors never occur","Every mutation is harmful","Effects can be harmful, beneficial, or neutral","Only environment causes mutation"],"answer":2,"explanation":"Effects depend on context.","source":"unit-04","difficulty":"core","unit":"Unit 04","originalSource":"quiz"},{"id":"u04-q-q20","domain":"Trait expression","prompt":"Phenotype can reflect:","options":["No change through life","Identical outcomes in all clones","Genes alone","Genotype, environment, development, and chance"],"answer":3,"explanation":"Phenotype often reflects multiple influences.","source":"unit-04","difficulty":"core","unit":"Unit 04","originalSource":"quiz"},{"id":"u04-a-a01","domain":"Genetic information","prompt":"Which sequence is ordered largest to smaller?","options":["Genome → chromosome → gene → nucleotide","Chromosome → genome → nucleotide → gene","Nucleotide → genome → chromosome → gene","Gene → chromosome → genome → nucleotide"],"answer":0,"explanation":"A genome contains chromosomes, which contain genes built from nucleotides.","source":"unit-04","difficulty":"transfer","unit":"Unit 04","originalSource":"assessment"},{"id":"u04-a-a02","domain":"Genetic information","prompt":"A chromosome is:","options":["An amino acid","A long DNA molecule associated with proteins","A complete organism","An ATP-making organelle"],"answer":1,"explanation":"Chromosomes package DNA.","source":"unit-04","difficulty":"transfer","unit":"Unit 04","originalSource":"assessment"},{"id":"u04-a-a03","domain":"Genetic information","prompt":"Sister chromatids are:","options":["Gametes","Homologues from two parents","Replicated copies of one chromosome joined before separation","Unrelated genes"],"answer":2,"explanation":"They are replicated copies.","source":"unit-04","difficulty":"transfer","unit":"Unit 04","originalSource":"assessment"},{"id":"u04-a-a04","domain":"Cell cycle","prompt":"Which occurs before mitosis?","options":["Gamete fusion","Homologue separation","Protein digestion","DNA replication and preparation"],"answer":3,"explanation":"Interphase prepares the cell.","source":"unit-04","difficulty":"transfer","unit":"Unit 04","originalSource":"assessment"},{"id":"u04-a-a05","domain":"Cell cycle","prompt":"Cytokinesis is:","options":["Division of cytoplasm","DNA copying","Homologue pairing","Translation"],"answer":0,"explanation":"Cytokinesis separates cytoplasm.","source":"unit-04","difficulty":"transfer","unit":"Unit 04","originalSource":"assessment"},{"id":"u04-a-a06","domain":"Mitosis","prompt":"Which process produces additional body cells for wound repair?","options":["Crossing over","Mitosis","Meiosis only","Fertilization"],"answer":1,"explanation":"Mitosis supports repair.","source":"unit-04","difficulty":"transfer","unit":"Unit 04","originalSource":"assessment"},{"id":"u04-a-a07","domain":"Mitosis","prompt":"Why are mitotic daughter cells not guaranteed identical in every respect?","options":["They receive different homologues","DNA is never copied","Mutation, cytoplasmic differences, and later expression","Mitosis halves chromosomes"],"answer":2,"explanation":"Real cells can differ despite high genetic similarity.","source":"unit-04","difficulty":"transfer","unit":"Unit 04","originalSource":"assessment"},{"id":"u04-a-a08","domain":"Differentiation","prompt":"Differentiation is:","options":["Loss of all shared DNA","Gamete fusion","Chromosome doubling every generation","Development of specialized structures and functions"],"answer":3,"explanation":"Differentiation creates specialized cell types.","source":"unit-04","difficulty":"transfer","unit":"Unit 04","originalSource":"assessment"},{"id":"u04-a-a09","domain":"Cell-cycle control","prompt":"Which statement about cancer is accurate?","options":["A broad group involving abnormal growth and multiple possible regulatory changes","Every fast-dividing cell is cancerous","Checkpoints always prevent it","One disease from one mutation"],"answer":0,"explanation":"Cancer is heterogeneous.","source":"unit-04","difficulty":"transfer","unit":"Unit 04","originalSource":"assessment"},{"id":"u04-a-a10","domain":"Reproduction","prompt":"An advantage of asexual reproduction can be:","options":["Adaptation to every change","Rapid reproduction without finding a mate","Guaranteed high variation","Four gametes"],"answer":1,"explanation":"It can be rapid and one-parent.","source":"unit-04","difficulty":"transfer","unit":"Unit 04","originalSource":"assessment"},{"id":"u04-a-a11","domain":"Reproduction","prompt":"A potential advantage of sexual reproduction is:","options":["Removal of harmful alleles","Identical offspring","New genetic combinations","Always more offspring"],"answer":2,"explanation":"Sexual reproduction reshuffles alleles.","source":"unit-04","difficulty":"transfer","unit":"Unit 04","originalSource":"assessment"},{"id":"u04-a-a12","domain":"Meiosis","prompt":"What separates in meiosis I?","options":["Sister chromatids only","Genes from DNA","Ribosomes","Homologous chromosomes"],"answer":3,"explanation":"Homologues separate.","source":"unit-04","difficulty":"transfer","unit":"Unit 04","originalSource":"assessment"},{"id":"u04-a-a13","domain":"Meiosis","prompt":"What separates in meiosis II?","options":["Sister chromatids","Alleles","Gametes","Homologues"],"answer":0,"explanation":"Sister chromatids separate.","source":"unit-04","difficulty":"transfer","unit":"Unit 04","originalSource":"assessment"},{"id":"u04-a-a14","domain":"Meiosis","prompt":"A diploid organism has 8 chromosomes. A gamete has:","options":["2","4","8","16"],"answer":1,"explanation":"The haploid number is 4.","source":"unit-04","difficulty":"transfer","unit":"Unit 04","originalSource":"assessment"},{"id":"u04-a-a15","domain":"Variation","prompt":"Which creates variation without creating a new allele?","options":["A deletion","A replication error","Independent assortment","A substitution mutation"],"answer":2,"explanation":"It reshuffles existing alleles.","source":"unit-04","difficulty":"transfer","unit":"Unit 04","originalSource":"assessment"},{"id":"u04-a-a16","domain":"Variation","prompt":"Crossing over normally occurs between:","options":["Unrelated chromosomes only","Ribosomes","Gametes after fertilization","Non-sister chromatids of homologues"],"answer":3,"explanation":"Corresponding segments exchange.","source":"unit-04","difficulty":"transfer","unit":"Unit 04","originalSource":"assessment"},{"id":"u04-a-a17","domain":"Fertilization","prompt":"A zygote forms by:","options":["Fusion of haploid gametes","Body-cell replication","Chromatid separation","Budding"],"answer":0,"explanation":"Fertilization forms a zygote.","source":"unit-04","difficulty":"transfer","unit":"Unit 04","originalSource":"assessment"},{"id":"u04-a-a18","domain":"Inheritance language","prompt":"Which genotype is heterozygous?","options":["RR","Rr","rr","R"],"answer":1,"explanation":"Rr has two different alleles.","source":"unit-04","difficulty":"transfer","unit":"Unit 04","originalSource":"assessment"},{"id":"u04-a-a19","domain":"Inheritance language","prompt":"If R is dominant, which genotype has the recessive phenotype?","options":["RR only","Rr only","rr only","RR and Rr"],"answer":2,"explanation":"Only rr is recessive in this model.","source":"unit-04","difficulty":"transfer","unit":"Unit 04","originalSource":"assessment"},{"id":"u04-a-a20","domain":"Probability","prompt":"For Aa × aa, the expected heterozygous proportion is:","options":["3/4","0","1/4","1/2"],"answer":3,"explanation":"Half are Aa.","source":"unit-04","difficulty":"transfer","unit":"Unit 04","originalSource":"assessment"},{"id":"u04-a-a21","domain":"Probability","prompt":"For AA × aa, expected offspring are:","options":["All Aa","Half AA and half aa","One quarter aa","All AA"],"answer":0,"explanation":"Every offspring is Aa.","source":"unit-04","difficulty":"transfer","unit":"Unit 04","originalSource":"assessment"},{"id":"u04-a-a22","domain":"Probability","prompt":"In 200 expected offspring from Aa × Aa, expected aa count is:","options":["25","50","100","150"],"answer":1,"explanation":"One quarter of 200 is 50.","source":"unit-04","difficulty":"transfer","unit":"Unit 04","originalSource":"assessment"},{"id":"u04-a-a23","domain":"Probability","prompt":"Observed ratios often differ from expected ratios because:","options":["Alleles remember prior births","Ratios apply only to first offspring","Probability predicts long-run patterns, not exact small samples","Punnett squares stop meiosis"],"answer":2,"explanation":"Sampling variation occurs.","source":"unit-04","difficulty":"transfer","unit":"Unit 04","originalSource":"assessment"},{"id":"u04-a-a24","domain":"Non-simple inheritance","prompt":"RR red × WW white gives RW pink. This is:","options":["Codominance","Sex linkage","Complete dominance","Incomplete dominance"],"answer":3,"explanation":"The heterozygote is intermediate.","source":"unit-04","difficulty":"transfer","unit":"Unit 04","originalSource":"assessment"},{"id":"u04-a-a25","domain":"Non-simple inheritance","prompt":"Visible expression of both allele products is:","options":["Codominance","Incomplete dominance","Recessiveness","Independent assortment"],"answer":0,"explanation":"Both products are expressed.","source":"unit-04","difficulty":"transfer","unit":"Unit 04","originalSource":"assessment"},{"id":"u04-a-a26","domain":"Trait expression","prompt":"Genetically similar plants differ in height under different water levels. Best conclusion:","options":["They are different species","Environment influenced height","Their DNA must differ completely","Height has no genetic component"],"answer":1,"explanation":"Environment affected phenotype.","source":"unit-04","difficulty":"transfer","unit":"Unit 04","originalSource":"assessment"},{"id":"u04-a-a27","domain":"Mutation","prompt":"A skin-cell mutation is usually not inherited because:","options":["All somatic mutations are repaired","Only beneficial mutations inherit","It is outside the gamete-producing lineage","Skin cells lack DNA"],"answer":2,"explanation":"Germline location matters.","source":"unit-04","difficulty":"transfer","unit":"Unit 04","originalSource":"assessment"},{"id":"u04-a-a28","domain":"Mutation","prompt":"Which can create a new allele?","options":["Independent assortment alone","Fertilization alone","Cytokinesis alone","Mutation"],"answer":3,"explanation":"Mutation changes DNA sequence.","source":"unit-04","difficulty":"transfer","unit":"Unit 04","originalSource":"assessment"},{"id":"u04-a-a29","domain":"Evidence and ethics","prompt":"Appropriate school genetics practice is:","options":["Use fictional organisms and protect personal data","Infer paternity","Publish identifiable results","Require family medical histories"],"answer":0,"explanation":"Privacy is essential.","source":"unit-04","difficulty":"transfer","unit":"Unit 04","originalSource":"assessment"},{"id":"u04-a-a30","domain":"Evidence and ethics","prompt":"Why is 'genetically superior' inaccurate for people?","options":["Only recessive alleles exist","Traits are complex and human value is not a biological ranking","All people have identical DNA","Genes never affect traits"],"answer":1,"explanation":"Genetics does not rank human worth.","source":"unit-04","difficulty":"transfer","unit":"Unit 04","originalSource":"assessment"},{"id":"u05-q-q01","domain":"Ecological organization","prompt":"Which level includes interacting populations and abiotic conditions?","options":["Ecosystem","Species","Organism","Population"],"answer":0,"explanation":"An ecosystem includes a community and its abiotic environment.","source":"unit-05","difficulty":"core","unit":"Unit 05","originalSource":"quiz"},{"id":"u05-q-q02","domain":"Niche","prompt":"A niche is best described as:","options":["Only the geographic location of an organism","The organism’s role, resource use, tolerances, timing, and interactions","A permanent population size","A fossil classification"],"answer":1,"explanation":"A niche is broader than habitat and includes ecological function and requirements.","source":"unit-05","difficulty":"core","unit":"Unit 05","originalSource":"quiz"},{"id":"u05-q-q03","domain":"Food webs","prompt":"What does an arrow from seed to mouse indicate?","options":["Both have identical roles","The seed hunts the mouse","Transfer of matter and energy from seed to mouse","The mouse produces the seed"],"answer":2,"explanation":"The consumer receives matter and chemical energy from the resource.","source":"unit-05","difficulty":"core","unit":"Unit 05","originalSource":"quiz"},{"id":"u05-q-q04","domain":"Energy transfer","prompt":"If 5,000 kJ is available to one trophic level and 600 kJ to the next, efficiency is:","options":["83.3%","120%","8.3%","12%"],"answer":3,"explanation":"600 ÷ 5,000 × 100 = 12%.","source":"unit-05","difficulty":"core","unit":"Unit 05","originalSource":"quiz"},{"id":"u05-q-q05","domain":"Matter cycles","prompt":"Which process moves carbon from organisms to atmospheric carbon dioxide?","options":["Cellular respiration","Sedimentation only","Photosynthesis only","Nitrogen fixation"],"answer":0,"explanation":"Cellular respiration releases carbon dioxide.","source":"unit-05","difficulty":"core","unit":"Unit 05","originalSource":"quiz"},{"id":"u05-q-q06","domain":"Biodiversity","prompt":"Two sites have the same species richness. Which additional information is needed to compare evenness?","options":["The age of the observer","Relative abundance of each species","Only the site names","Only total land area"],"answer":1,"explanation":"Evenness depends on how balanced species abundances are.","source":"unit-05","difficulty":"core","unit":"Unit 05","originalSource":"quiz"},{"id":"u05-q-q07","domain":"Sampling","prompt":"Why must sampling effort be recorded in a biodiversity survey?","options":["It eliminates seasonal change","It replaces species identification","More effort can detect more organisms and affect comparisons","It proves every species was found"],"answer":2,"explanation":"Different effort can create apparent differences unrelated to actual diversity.","source":"unit-05","difficulty":"core","unit":"Unit 05","originalSource":"quiz"},{"id":"u05-q-q08","domain":"Population density","prompt":"A count of 900 organisms across 60 hectares equals:","options":["54 per hectare","960 per hectare","10 per hectare","15 per hectare"],"answer":3,"explanation":"900 ÷ 60 = 15 per hectare.","source":"unit-05","difficulty":"core","unit":"Unit 05","originalSource":"quiz"},{"id":"u05-q-q09","domain":"Population models","prompt":"Why is carrying capacity not necessarily constant?","options":["It changes with environmental resources and pressures","It is set only by body size","It cannot be estimated","It equals zero for all predators"],"answer":0,"explanation":"Resources, habitat, climate, disease, interactions, and human actions change capacity.","source":"unit-05","difficulty":"core","unit":"Unit 05","originalSource":"quiz"},{"id":"u05-q-q10","domain":"Interactions","prompt":"Which interaction is commonly represented +/+?","options":["Parasitism","Mutualism","Competition","Predation"],"answer":1,"explanation":"Mutualism describes an average benefit to both partners under stated conditions.","source":"unit-05","difficulty":"core","unit":"Unit 05","originalSource":"quiz"},{"id":"u05-q-q11","domain":"Succession","prompt":"Secondary succession differs from primary succession because secondary succession usually begins with:","options":["Only volcanic rock and no soil","No matter present","Existing soil or biological legacies","No organisms ever returning"],"answer":2,"explanation":"Soil, seeds, roots, microbes, or survivors often persist after secondary disturbance.","source":"unit-05","difficulty":"core","unit":"Unit 05","originalSource":"quiz"},{"id":"u05-q-q12","domain":"Conservation","prompt":"Which conservation plan is strongest?","options":["One that hides uncertainty","One with no measurable target","One based only on popularity","One with a baseline, causal pressure, indicator, community rights, and revision rule"],"answer":3,"explanation":"Transparent goals, indicators, causes, rights, and adaptive revision support evaluation.","source":"unit-05","difficulty":"core","unit":"Unit 05","originalSource":"quiz"},{"id":"u05-q-q14","domain":"Resistance","prompt":"Which statement about antimicrobial resistance is correct?","options":["A person’s body evolves resistance to the drug","Microbial populations can change in the frequency of resistant variants","Antibiotics intentionally teach bacteria","Resistance proves every historical ancestry claim"],"answer":1,"explanation":"Selection can increase resistant microbial variants; one example does not settle every origins claim.","source":"unit-05","difficulty":"core","unit":"Unit 05","originalSource":"quiz"},{"id":"u05-q-q15","domain":"Terminology","prompt":"In standard biology, macroevolution includes:","options":["Any personal worldview conclusion","Only changes within one lifetime","Speciation, extinction, and diversification at or above species level","An individual suddenly producing an unrelated organism"],"answer":2,"explanation":"Macroevolution is defined as patterns at or above the species level.","source":"unit-05","difficulty":"core","unit":"Unit 05","originalSource":"quiz"},{"id":"u05-q-q16","domain":"Species concepts","prompt":"Why can fossil species boundaries be uncertain?","options":["All fossils are identical","Geological context is irrelevant","Fossils never contain anatomy","Reproductive compatibility cannot usually be tested and variation may overlap"],"answer":3,"explanation":"Fossil classification relies on preserved anatomy and context rather than direct breeding tests.","source":"unit-05","difficulty":"core","unit":"Unit 05","originalSource":"quiz"},{"id":"u05-q-q17","domain":"Equid record","prompt":"Modern scientific diagrams of equid history are usually branching because:","options":["Multiple equid forms coexisted and many branches became extinct","Every fossil forms one direct ladder","Only one horse species ever existed","Branching eliminates uncertainty"],"answer":0,"explanation":"The evidence is interpreted as diversification with contemporaneous and extinct branches.","source":"unit-05","difficulty":"core","unit":"Unit 05","originalSource":"quiz"},{"id":"u05-q-q18","domain":"Evidence classification","prompt":"A fossil’s geological location is an observation; calling it a direct ancestor is:","options":["Another measurement","A historical inference","A unit conversion","A trophic role"],"answer":1,"explanation":"Ancestry is inferred from multiple lines of evidence.","source":"unit-05","difficulty":"core","unit":"Unit 05","originalSource":"quiz"},{"id":"u05-q-q19","domain":"Worldviews","prompt":"How should student worldview positions be graded in this unit?","options":["By whether they adopt one required belief","By family religion","By accuracy, evidence classification, reasoning, source fairness, and respect","By majority vote"],"answer":2,"explanation":"The curriculum evaluates literacy and reasoning, not compelled belief.","source":"unit-05","difficulty":"core","unit":"Unit 05","originalSource":"quiz"},{"id":"u05-q-q20","domain":"Stewardship","prompt":"Which statement identifies possible common ground across origins views?","options":["Evidence should be hidden","Conservation requires agreement on every origins question","No responsibility for ecosystems","Protection of biodiversity and responsible stewardship can be supported from different worldviews"],"answer":3,"explanation":"People with different origins views can support evidence-based stewardship.","source":"unit-05","difficulty":"core","unit":"Unit 05","originalSource":"quiz"},{"id":"u05-a-a01","domain":"Organization","prompt":"Which sequence increases in ecological scale?","options":["Organism → population → community → ecosystem","Population → organism → ecosystem → community","Community → organism → population → ecosystem","Ecosystem → community → population → organism"],"answer":0,"explanation":"Individuals form populations; interacting populations form communities; communities plus abiotic environment form ecosystems.","source":"unit-05","difficulty":"transfer","unit":"Unit 05","originalSource":"assessment"},{"id":"u05-a-a02","domain":"Observation and inference","prompt":"Which statement is a direct observation?","options":["The ecosystem will collapse","Twelve individuals were counted in a 10 m transect","The organism evolved this trait because it needed it","Shade caused the species decline"],"answer":1,"explanation":"A documented count is an observation; causal and historical statements are inferences.","source":"unit-05","difficulty":"transfer","unit":"Unit 05","originalSource":"assessment"},{"id":"u05-a-a03","domain":"Habitat and niche","prompt":"Which statement correctly distinguishes habitat and niche?","options":["Niche is only body size","Habitat is a genome","Habitat is location; niche includes role and resource use","They are always identical"],"answer":2,"explanation":"Habitat describes where an organism lives; niche includes its ecological role and requirements.","source":"unit-05","difficulty":"transfer","unit":"Unit 05","originalSource":"assessment"},{"id":"u05-a-a04","domain":"Trophic roles","prompt":"Which is a detritivore?","options":["Oak tree","Green algae","Hawk","Earthworm ingesting leaf fragments"],"answer":3,"explanation":"A detritivore ingests detrital particles.","source":"unit-05","difficulty":"transfer","unit":"Unit 05","originalSource":"assessment"},{"id":"u05-a-a05","domain":"Food-web effects","prompt":"Why can removal of one species affect several others?","options":["Food webs contain direct and indirect interactions","Every species eats every other species","Energy cycles forever","Abiotic conditions never matter"],"answer":0,"explanation":"Networked interactions can transmit effects through several pathways.","source":"unit-05","difficulty":"transfer","unit":"Unit 05","originalSource":"assessment"},{"id":"u05-a-a06","domain":"Energy calculation","prompt":"A trophic level receives 320 kJ from a preceding level with 4,000 kJ. Efficiency is:","options":["6%","8%","12.5%","80%"],"answer":1,"explanation":"320 ÷ 4,000 × 100 = 8%.","source":"unit-05","difficulty":"transfer","unit":"Unit 05","originalSource":"assessment"},{"id":"u05-a-a08","domain":"Matter cycles","prompt":"Which process converts atmospheric nitrogen into biologically available forms?","options":["Respiration","Evaporation","Combustion","Nitrogen fixation"],"answer":3,"explanation":"Nitrogen fixation converts N₂ into compounds that enter biological cycles.","source":"unit-05","difficulty":"transfer","unit":"Unit 05","originalSource":"assessment"},{"id":"u05-a-a09","domain":"Matter and energy","prompt":"Which statement is accurate?","options":["Matter cycles while energy flows through and dissipates","Neither crosses ecosystem boundaries","Energy cycles and matter flows one way","Both disappear"],"answer":0,"explanation":"Matter is conserved and recycled, while usable energy is dissipated.","source":"unit-05","difficulty":"transfer","unit":"Unit 05","originalSource":"assessment"},{"id":"u05-a-a10","domain":"Diversity calculation","prompt":"A sample contains counts 4, 4, 4, and 4 for four species. Compared with counts 13, 1, 1, and 1, the first sample has:","options":["Lower richness","The same richness and greater evenness","No biodiversity","Fewer total organisms"],"answer":1,"explanation":"Both contain four species and 16 organisms, but the first is more even.","source":"unit-05","difficulty":"transfer","unit":"Unit 05","originalSource":"assessment"},{"id":"u05-a-a11","domain":"Survey design","prompt":"Which practice best protects threatened species?","options":["Publish exact nest coordinates","Handle every organism for identification","Avoid revealing precise sensitive locations and use non-contact records","Collect specimens without permits"],"answer":2,"explanation":"Location privacy and non-disturbance reduce risk.","source":"unit-05","difficulty":"transfer","unit":"Unit 05","originalSource":"assessment"},{"id":"u05-a-a12","domain":"Population change","prompt":"A population changes from 800 to 680. What is the percentage change?","options":["−12%","15%","85%","−15%"],"answer":3,"explanation":"(680−800) ÷ 800 × 100 = −15%.","source":"unit-05","difficulty":"transfer","unit":"Unit 05","originalSource":"assessment"},{"id":"u05-a-a13","domain":"Mark–recapture","prompt":"Which condition violates a simple mark–recapture assumption?","options":["Marked animals become much easier to capture than unmarked animals","The study interval is short","Marks remain identifiable","Marked individuals mix into the population"],"answer":0,"explanation":"Different capture probability biases the ratio.","source":"unit-05","difficulty":"transfer","unit":"Unit 05","originalSource":"assessment"},{"id":"u05-a-a14","domain":"Population growth","prompt":"Exponential growth assumes approximately:","options":["Only emigration","Constant proportional growth with no immediate resource limit","A fixed carrying capacity already reached","No births"],"answer":1,"explanation":"Exponential models approximate unrestricted proportional growth.","source":"unit-05","difficulty":"transfer","unit":"Unit 05","originalSource":"assessment"},{"id":"u05-a-a15","domain":"Predator–prey evidence","prompt":"A predator and prey time series shows opposite trends. What additional evidence strengthens a causal explanation?","options":["A personal preference","Removal of inconvenient years","Feeding records, prey survival, vegetation, disease, weather, and alternative-factor analysis","A single graph title"],"answer":2,"explanation":"Mechanistic and comparative evidence helps test causation.","source":"unit-05","difficulty":"transfer","unit":"Unit 05","originalSource":"assessment"},{"id":"u05-a-a16","domain":"Interactions","prompt":"Which interaction is +/−?","options":["Competition","Commensalism","Mutualism","Predation"],"answer":3,"explanation":"A predator benefits while prey is harmed.","source":"unit-05","difficulty":"transfer","unit":"Unit 05","originalSource":"assessment"},{"id":"u05-a-a17","domain":"Resilience","prompt":"Ecosystem resilience refers most closely to:","options":["Capacity to absorb disturbance while retaining or reorganizing key functions","Having the most species in every sample","Eliminating all fire","Never changing"],"answer":0,"explanation":"Resilience concerns persistence or recovery of functions despite change.","source":"unit-05","difficulty":"transfer","unit":"Unit 05","originalSource":"assessment"},{"id":"u05-a-a18","domain":"Conservation evidence","prompt":"Which result is an outcome rather than a projection?","options":["A proposal promises recovery","A monitored population increased from 200 to 260 after intervention, with stated method","A slogan says the plan will work","A model predicts a 20% increase"],"answer":1,"explanation":"A measured post-intervention record is an observed outcome, though causal evaluation still needs design and comparison.","source":"unit-05","difficulty":"transfer","unit":"Unit 05","originalSource":"assessment"},{"id":"u05-a-a19","domain":"Selection","prompt":"Which statement avoids teleological language?","options":["The drug created only useful mutations","Bacteria became resistant because they wanted to survive","Antibiotic exposure favored resistant variants that left more descendants","Every bacterium intentionally changed its DNA"],"answer":2,"explanation":"Selection changes variant frequencies; it does not require purposeful mutation.","source":"unit-05","difficulty":"transfer","unit":"Unit 05","originalSource":"assessment"},{"id":"u05-a-a20","domain":"Variation","prompt":"Which process creates new alleles?","options":["Selection alone","Independent assortment alone","Migration alone","Mutation"],"answer":3,"explanation":"Mutation changes DNA sequence and can create a new allele.","source":"unit-05","difficulty":"transfer","unit":"Unit 05","originalSource":"assessment"},{"id":"u05-a-a21","domain":"Microevolution","prompt":"A measured allele-frequency shift across generations is commonly classified as:","options":["Microevolution","A theological proof","A fossil ancestor","No biological change"],"answer":0,"explanation":"Microevolution includes measurable inherited-frequency changes in populations.","source":"unit-05","difficulty":"transfer","unit":"Unit 05","originalSource":"assessment"},{"id":"u05-a-a22","domain":"Speciation","prompt":"Which provides direct evidence relevant to speciation in living populations?","options":["One individual changing species during life","Reduced interbreeding or reproductive compatibility between diverging populations","A drawing without data","A claim that no boundaries exist"],"answer":1,"explanation":"Reproductive isolation is central to many species concepts.","source":"unit-05","difficulty":"transfer","unit":"Unit 05","originalSource":"assessment"},{"id":"u05-a-a23","domain":"Macroevolution definition","prompt":"Which statement is consistent with the standard biological use of macroevolution?","options":["It is identical to abiogenesis","It requires a sudden jump by one individual","It includes speciation and diversification across lineages","It means acquired traits during one lifetime"],"answer":2,"explanation":"Macroevolution refers to patterns at or above the species level and is not the origin of life.","source":"unit-05","difficulty":"transfer","unit":"Unit 05","originalSource":"assessment"},{"id":"u05-a-a24","domain":"Fossils","prompt":"Which statement about fossil evidence is accurate?","options":["Every fossil includes its family tree","Fossils cannot be measured","Fossil classifications never change","Fossils can preserve anatomy and context but rarely identify a direct parent–descendant pair"],"answer":3,"explanation":"Anatomy and context are observed; ancestry is reconstructed and classifications may be revised.","source":"unit-05","difficulty":"transfer","unit":"Unit 05","originalSource":"assessment"},{"id":"u05-a-a25","domain":"Equids","prompt":"Why is a ladder model of horse evolution misleading?","options":["The record is interpreted as branching, with coexisting forms and extinct side branches","Modern horses have many functional toes","DNA proves every fossil is a parent","No equids existed"],"answer":0,"explanation":"Equid diversity is not a single uninterrupted march.","source":"unit-05","difficulty":"transfer","unit":"Unit 05","originalSource":"assessment"},{"id":"u05-a-a26","domain":"Evidence levels","prompt":"Which sequence moves from most direct to most interpretive?","options":["Worldview conclusion → measurement → specimen","Specimen → measurement → classification → ancestry inference → worldview conclusion","Ancestry inference → specimen → measurement","Classification → specimen → observation"],"answer":1,"explanation":"Evidence should be separated from progressively broader interpretation.","source":"unit-05","difficulty":"transfer","unit":"Unit 05","originalSource":"assessment"},{"id":"u05-a-a28","domain":"Source evaluation","prompt":"How should an advocacy source be used?","options":["As proof that opposing evidence does not exist","Without identifying its perspective","As direct fossil evidence","As a primary source for what that organization argues, checked against underlying data"],"answer":3,"explanation":"Advocacy sources accurately document viewpoints, but scientific claims must be traced to data and methods.","source":"unit-05","difficulty":"transfer","unit":"Unit 05","originalSource":"assessment"},{"id":"u05-a-a29","domain":"Fair assessment","prompt":"Which student response should receive the stronger score?","options":["One that accurately classifies evidence, fairly represents alternatives, and supports a reasoned conclusion","One that attacks another student’s faith","One that refuses to cite sources","One that repeats a preferred conclusion but misstates evidence"],"answer":0,"explanation":"Assessment is based on literacy, evidence, reasoning, and respectful representation.","source":"unit-05","difficulty":"transfer","unit":"Unit 05","originalSource":"assessment"},{"id":"u05-a-a30","domain":"Stewardship","prompt":"A strong stewardship proposal includes:","options":["A hidden decision process","Target, baseline, action, indicator, community consideration, uncertainty, and revision rule","Only a moral slogan","No monitoring"],"answer":1,"explanation":"A testable and accountable plan defines evidence, action, rights, and adaptation.","source":"unit-05","difficulty":"transfer","unit":"Unit 05","originalSource":"assessment"},{"id":"u06-q-q01","domain":"Matter","prompt":"Which statement distinguishes an element from a compound?","options":["An element contains one type of atom; a compound contains elements chemically combined in fixed proportions","Compounds cannot be pure","Elements always separate physically","An element contains one proton only"],"answer":0,"explanation":"Elements have one atomic number; compounds have bonded elements in fixed ratios.","source":"unit-06","difficulty":"core","unit":"Unit 06","originalSource":"quiz"},{"id":"u06-q-q02","domain":"Atomic model","prompt":"Rutherford’s scattering evidence most directly supported:","options":["Atoms are indivisible spheres","Positive charge and most mass are concentrated in a small nucleus","Electrons are positive","Atoms contain no empty space"],"answer":1,"explanation":"Rare strong deflections supported a small dense positive nucleus.","source":"unit-06","difficulty":"core","unit":"Unit 06","originalSource":"quiz"},{"id":"u06-q-q03","domain":"Particles","prompt":"Which particle has relative charge 0 and relative mass about 1?","options":["Ion","Electron","Neutron","Proton"],"answer":2,"explanation":"A neutron is neutral and has mass close to one atomic mass unit.","source":"unit-06","difficulty":"core","unit":"Unit 06","originalSource":"quiz"},{"id":"u06-q-q04","domain":"Atomic number","prompt":"An atom with 15 protons is always:","options":["Sulfur","Silicon","Carbon","Phosphorus"],"answer":3,"explanation":"Atomic number 15 identifies phosphorus.","source":"unit-06","difficulty":"core","unit":"Unit 06","originalSource":"quiz"},{"id":"u06-q-q05","domain":"Mass number","prompt":"An isotope has 17 protons and 20 neutrons. Its mass number is:","options":["37","3","17","20"],"answer":0,"explanation":"Mass number = 17 + 20 = 37.","source":"unit-06","difficulty":"core","unit":"Unit 06","originalSource":"quiz"},{"id":"u06-q-q06","domain":"Charge","prompt":"A calcium atom loses two electrons. The ion has charge:","options":["1+","2+","2−","1−"],"answer":1,"explanation":"Losing two electrons gives 2+.","source":"unit-06","difficulty":"core","unit":"Unit 06","originalSource":"quiz"},{"id":"u06-q-q07","domain":"Isotopes","prompt":"Which pair represents isotopes of the same element?","options":["³⁵Cl and ⁴⁰Ar","¹H and ⁴He","¹²C and ¹⁴C","²³Na and ²⁴Mg"],"answer":2,"explanation":"Both carbon atoms have six protons.","source":"unit-06","difficulty":"core","unit":"Unit 06","originalSource":"quiz"},{"id":"u06-q-q08","domain":"Atomic weight","prompt":"A weighted atomic mass must use:","options":["Atomic number divided by neutrons","Electron number plus charge","Only the largest mass number","Isotope mass multiplied by fractional abundance, summed"],"answer":3,"explanation":"Relative atomic mass is an abundance-weighted mean.","source":"unit-06","difficulty":"core","unit":"Unit 06","originalSource":"quiz"},{"id":"u06-q-q09","domain":"Shells","prompt":"Which is the shell configuration of calcium?","options":["2,8,8,2","2,8,10","2,8,7,3","20"],"answer":0,"explanation":"Twenty electrons distribute as 2,8,8,2.","source":"unit-06","difficulty":"core","unit":"Unit 06","originalSource":"quiz"},{"id":"u06-q-q10","domain":"Valence","prompt":"Which element has seven outer-shell electrons?","options":["Magnesium","Chlorine","Argon","Sodium"],"answer":1,"explanation":"Chlorine is Group 17.","source":"unit-06","difficulty":"core","unit":"Unit 06","originalSource":"quiz"},{"id":"u06-q-q11","domain":"Period","prompt":"An element with configuration 2,8,3 is in which period?","options":["1","2","3","13"],"answer":2,"explanation":"Three occupied shells place it in Period 3.","source":"unit-06","difficulty":"core","unit":"Unit 06","originalSource":"quiz"},{"id":"u06-q-q12","domain":"Group","prompt":"Which pair belongs to Group 2?","options":["F and Cl","Ne and Ar","Li and Na","Be and Mg"],"answer":3,"explanation":"Beryllium and magnesium have two outer electrons.","source":"unit-06","difficulty":"core","unit":"Unit 06","originalSource":"quiz"},{"id":"u06-q-q13","domain":"Periodic order","prompt":"What uniquely fixes an element’s position in atomic-number order?","options":["Proton count","Average neutron count","Physical state","Discovery date"],"answer":0,"explanation":"Proton count is atomic number.","source":"unit-06","difficulty":"core","unit":"Unit 06","originalSource":"quiz"},{"id":"u06-q-q14","domain":"Group 1","prompt":"Which is the safest way to study alkali-metal reactivity?","options":["Put potassium in water at home","Use verified datasets or a qualified recorded demonstration","Touch sodium","Mix unknown metals with acid"],"answer":1,"explanation":"Reactive alkali metals require specialist controls.","source":"unit-06","difficulty":"core","unit":"Unit 06","originalSource":"quiz"},{"id":"u06-q-q15","domain":"Group 17","prompt":"Which statement is accurate for halogens down Group 17?","options":["They form 2+ ions","Outer-electron number increases","Reactivity generally decreases","All are gases"],"answer":2,"explanation":"Reactivity generally decreases down the group.","source":"unit-06","difficulty":"core","unit":"Unit 06","originalSource":"quiz"},{"id":"u06-q-q16","domain":"Noble gases","prompt":"Which element has a filled second shell?","options":["Sodium","Oxygen","Fluorine","Neon"],"answer":3,"explanation":"Neon has 2,8.","source":"unit-06","difficulty":"core","unit":"Unit 06","originalSource":"quiz"},{"id":"u06-q-q17","domain":"Spectra","prompt":"Why can line spectra help identify elements?","options":["Each element has characteristic allowed energy differences","All emit the same wavelengths","Spectra show neutron positions","Only compounds emit light"],"answer":0,"explanation":"Characteristic energy differences produce characteristic lines.","source":"unit-06","difficulty":"core","unit":"Unit 06","originalSource":"quiz"},{"id":"u06-q-q18","domain":"Model limits","prompt":"Which statement is most responsible?","options":["The Bohr picture is exact","Models should be used within evidence and scale limitations","Diagrams are photographs","Electron paths are always exact"],"answer":1,"explanation":"Scientific models are useful representations with limits.","source":"unit-06","difficulty":"core","unit":"Unit 06","originalSource":"quiz"},{"id":"u06-q-q19","domain":"Data","prompt":"An atomic-weight interval for an element indicates:","options":["The table is unordered","Proton count varies","Normal materials can have isotope-composition variation","The element has no isotopes"],"answer":2,"explanation":"Natural isotope ratios can vary.","source":"unit-06","difficulty":"core","unit":"Unit 06","originalSource":"quiz"},{"id":"u06-q-q20","domain":"Prediction","prompt":"An element has two occupied shells and one outer electron. Which fits?","options":["Sodium","Magnesium","Fluorine","Lithium"],"answer":3,"explanation":"Lithium has configuration 2,1.","source":"unit-06","difficulty":"core","unit":"Unit 06","originalSource":"quiz"},{"id":"u06-a-a01","domain":"Classification","prompt":"Which sample is a compound?","options":["Pure sodium chloride","Air","Copper metal","Oxygen gas"],"answer":0,"explanation":"Sodium chloride contains elements chemically combined in a fixed ratio.","source":"unit-06","difficulty":"transfer","unit":"Unit 06","originalSource":"assessment"},{"id":"u06-a-a02","domain":"Atomic evidence","prompt":"Which observation led Thomson to infer negatively charged particles within atoms?","options":["Atoms were visible in a microscope","Cathode rays were deflected by electric and magnetic fields","Gold foil produced alpha particles","All gases had identical spectra"],"answer":1,"explanation":"Cathode-ray deflection supported negatively charged subatomic particles.","source":"unit-06","difficulty":"transfer","unit":"Unit 06","originalSource":"assessment"},{"id":"u06-a-a03","domain":"Atomic evidence","prompt":"In Rutherford scattering, most alpha particles passed through foil. This supports the inference that atoms are:","options":["Made only of electrons","Without nuclei","Mostly empty space at that scale","Uniform solid spheres"],"answer":2,"explanation":"Most particles encountered no concentrated mass or charge.","source":"unit-06","difficulty":"transfer","unit":"Unit 06","originalSource":"assessment"},{"id":"u06-a-a04","domain":"Model revision","prompt":"Why did atomic models change over time?","options":["Scientists agreed never to test them","The proton count changed historically","Models are personal opinions only","New evidence exposed limitations and supported revised models"],"answer":3,"explanation":"Scientific models are revised when new evidence requires better explanations.","source":"unit-06","difficulty":"transfer","unit":"Unit 06","originalSource":"assessment"},{"id":"u06-a-a05","domain":"Particle charge","prompt":"Which set of relative charges is correct for proton, neutron, electron?","options":["+1, 0, −1","−1, 0, +1","+1, −1, 0","0, +1, −1"],"answer":0,"explanation":"Proton +1, neutron 0, electron −1.","source":"unit-06","difficulty":"transfer","unit":"Unit 06","originalSource":"assessment"},{"id":"u06-a-a06","domain":"Particle mass","prompt":"Which contributes least to an atom’s mass?","options":["Neutron","Electron","Nucleus","Proton"],"answer":1,"explanation":"Electron mass is much smaller than proton or neutron mass.","source":"unit-06","difficulty":"transfer","unit":"Unit 06","originalSource":"assessment"},{"id":"u06-a-a07","domain":"Composition","prompt":"A neutral atom contains 8 protons and 10 neutrons. Which statement is correct?","options":["It is oxygen-10 with 18 electrons","It is neon-18 with 10 electrons","It is oxygen-18 with 8 electrons","It is fluorine-18 with 8 electrons"],"answer":2,"explanation":"Atomic number 8 is oxygen; mass number 18; neutrality gives 8 electrons.","source":"unit-06","difficulty":"transfer","unit":"Unit 06","originalSource":"assessment"},{"id":"u06-a-a08","domain":"Ion charge","prompt":"A particle has 13 protons and 10 electrons. It is:","options":["Al³⁻","Ne³⁺","Mg²⁺","Al³⁺"],"answer":3,"explanation":"Atomic number 13 is aluminium; three fewer electrons gives 3+.","source":"unit-06","difficulty":"transfer","unit":"Unit 06","originalSource":"assessment"},{"id":"u06-a-a09","domain":"Nuclear notation","prompt":"In the notation ³⁹₁₉K, the lower number represents:","options":["Atomic number","Mass number","Neutron number","Electron charge"],"answer":0,"explanation":"The subscript is atomic number.","source":"unit-06","difficulty":"transfer","unit":"Unit 06","originalSource":"assessment"},{"id":"u06-a-a10","domain":"Isotopes","prompt":"Which property differs between neutral chlorine-35 and chlorine-37 atoms?","options":["Electron arrangement","Neutron number","Element identity","Proton number"],"answer":1,"explanation":"They differ in neutron number.","source":"unit-06","difficulty":"transfer","unit":"Unit 06","originalSource":"assessment"},{"id":"u06-a-a11","domain":"Weighted average","prompt":"An element has isotope masses 10 and 11 with abundances 20% and 80%. Its weighted mass is:","options":["10.2","10.5","10.8","21"],"answer":2,"explanation":"10(0.20)+11(0.80)=10.8.","source":"unit-06","difficulty":"transfer","unit":"Unit 06","originalSource":"assessment"},{"id":"u06-a-a12","domain":"Abundance","prompt":"Three isotope fractions are 0.79, 0.10, and 0.11. Their total is:","options":["1.10","79","0.90","1.00"],"answer":3,"explanation":"The fractions sum to 1.00.","source":"unit-06","difficulty":"transfer","unit":"Unit 06","originalSource":"assessment"},{"id":"u06-a-a13","domain":"Atomic weight","prompt":"Which statement about standard atomic weight is most accurate?","options":["It may be a weighted value or interval reflecting natural isotope composition","It equals the proton number","It is identical for every isotope","It is always a whole-number mass number"],"answer":0,"explanation":"Standard atomic weights summarize representative isotope masses and abundances.","source":"unit-06","difficulty":"transfer","unit":"Unit 06","originalSource":"assessment"},{"id":"u06-a-a14","domain":"Electron configuration","prompt":"Which configuration belongs to aluminium?","options":["2,7","2,8,3","2,8,2","2,8,4"],"answer":1,"explanation":"Aluminium has atomic number 13.","source":"unit-06","difficulty":"transfer","unit":"Unit 06","originalSource":"assessment"},{"id":"u06-a-a15","domain":"Ion configuration","prompt":"Which species has configuration 2,8?","options":["Cl⁻","K⁺","Na⁺","Na atom"],"answer":2,"explanation":"Na⁺ has 10 electrons; Cl⁻ and K⁺ have 18.","source":"unit-06","difficulty":"transfer","unit":"Unit 06","originalSource":"assessment"},{"id":"u06-a-a16","domain":"Period","prompt":"Which element is in Period 4 among the first 20?","options":["Sodium","Argon","Chlorine","Potassium"],"answer":3,"explanation":"Potassium has four occupied shells.","source":"unit-06","difficulty":"transfer","unit":"Unit 06","originalSource":"assessment"},{"id":"u06-a-a17","domain":"Group","prompt":"Which pair has related chemical properties because both have one outer electron?","options":["Li and K","O and Ne","Mg and Cl","C and Ar"],"answer":0,"explanation":"Lithium and potassium are Group 1.","source":"unit-06","difficulty":"transfer","unit":"Unit 06","originalSource":"assessment"},{"id":"u06-a-a18","domain":"Periodic history","prompt":"Mendeleev’s table was historically powerful partly because it:","options":["Rejected repeating properties","Left gaps and predicted properties of undiscovered elements","Was ordered by exact neutron count","Contained all 118 modern elements"],"answer":1,"explanation":"Its gaps enabled testable predictions.","source":"unit-06","difficulty":"transfer","unit":"Unit 06","originalSource":"assessment"},{"id":"u06-a-a19","domain":"Modern order","prompt":"Why is atomic number superior to relative atomic mass as the defining order?","options":["Neutrons determine chemistry alone","Atomic number is always larger","It uniquely identifies nuclear charge and resolves mass-order anomalies","Atomic mass is never measured"],"answer":2,"explanation":"Proton number fixes identity and corrects mass-order anomalies.","source":"unit-06","difficulty":"transfer","unit":"Unit 06","originalSource":"assessment"},{"id":"u06-a-a20","domain":"Across-period trend","prompt":"Across Period 3, which general change occurs?","options":["Atomic number decreases","Occupied shells increase from three to eight","All elements form +1 ions","Metallic character decreases toward nonmetals"],"answer":3,"explanation":"Metallic character generally declines across the period.","source":"unit-06","difficulty":"transfer","unit":"Unit 06","originalSource":"assessment"},{"id":"u06-a-a21","domain":"Group 1","prompt":"Which property generally increases from lithium to potassium?","options":["Reactivity with water","Melting point","Outer-electron count","Ion charge magnitude"],"answer":0,"explanation":"Group 1 reactivity generally increases down the group.","source":"unit-06","difficulty":"transfer","unit":"Unit 06","originalSource":"assessment"},{"id":"u06-a-a22","domain":"Group 17","prompt":"Which property generally decreases from fluorine to iodine?","options":["Density","Reactivity","Number of occupied shells","Atomic number"],"answer":1,"explanation":"Halogen reactivity generally decreases down the group.","source":"unit-06","difficulty":"transfer","unit":"Unit 06","originalSource":"assessment"},{"id":"u06-a-a23","domain":"Group 18","prompt":"Which is a noble gas?","options":["Potassium","Calcium","Argon","Chlorine"],"answer":2,"explanation":"Argon is Group 18.","source":"unit-06","difficulty":"transfer","unit":"Unit 06","originalSource":"assessment"},{"id":"u06-a-a24","domain":"Prediction","prompt":"An element in Group 2, Period 3 is:","options":["Calcium","Sodium","Aluminium","Magnesium"],"answer":3,"explanation":"Magnesium is in Period 3 and Group 2.","source":"unit-06","difficulty":"transfer","unit":"Unit 06","originalSource":"assessment"},{"id":"u06-a-a25","domain":"Prediction","prompt":"Which common ion is predicted for configuration 2,8,7?","options":["1− after gaining one electron","1+ after losing one proton","2− after losing two electrons","No possible ion"],"answer":0,"explanation":"The simple model predicts gain of one electron.","source":"unit-06","difficulty":"transfer","unit":"Unit 06","originalSource":"assessment"},{"id":"u06-a-a26","domain":"Spectra","prompt":"A line spectrum contains discrete wavelengths because:","options":["Visible light has no energy","Electron energies occur in allowed states and transitions have specific energy differences","The nucleus emits every wavelength","All atoms have one electron"],"answer":1,"explanation":"Specific transitions produce photons with specific energies.","source":"unit-06","difficulty":"transfer","unit":"Unit 06","originalSource":"assessment"},{"id":"u06-a-a27","domain":"Safety","prompt":"Which investigation is appropriate without a specialist laboratory?","options":["React potassium with water","Open a radioactive device","Analyze published emission spectra","Burn unknown salts indoors"],"answer":2,"explanation":"Published spectra can be analyzed safely.","source":"unit-06","difficulty":"transfer","unit":"Unit 06","originalSource":"assessment"},{"id":"u06-a-a28","domain":"Source quality","prompt":"Which source is strongest for a chlorine isotope calculation?","options":["An anonymous post","A movie prop","A product advertisement","A NIST isotope table with definitions and provenance"],"answer":3,"explanation":"A traceable reference database supplies definitions and provenance.","source":"unit-06","difficulty":"transfer","unit":"Unit 06","originalSource":"assessment"},{"id":"u06-a-a29","domain":"Model limits","prompt":"Which statement avoids overstating a model?","options":["The shell model predicts useful outer-electron patterns but does not depict literal fixed paths","Electrons are colored balls exactly as shown","The nucleus is the same size as the diagram","A model cannot be revised"],"answer":0,"explanation":"The shell model is useful but not literal.","source":"unit-06","difficulty":"transfer","unit":"Unit 06","originalSource":"assessment"},{"id":"u06-a-a30","domain":"Evidence reasoning","prompt":"A responsible periodic-trend conclusion should:","options":["Treat every group as identical","Use measured data, state the range, identify exceptions, and avoid claiming an absolute law","Discard values that do not fit","Use only one element"],"answer":1,"explanation":"Trend claims require defined scope and limitations.","source":"unit-06","difficulty":"transfer","unit":"Unit 06","originalSource":"assessment"},{"id":"u07-q-q01","domain":"Bonding","prompt":"Which description best fits ionic bonding in NaCl?","options":["Attraction among Na⁺ and Cl⁻ ions in a lattice","One isolated NaCl molecule only","Shared protons","No electrostatic forces"],"answer":0,"explanation":"NaCl forms an extended ionic lattice.","source":"unit-07","difficulty":"core","unit":"Unit 07","originalSource":"quiz"},{"id":"u07-q-q02","domain":"Formula","prompt":"What is the correct formula for calcium oxide?","options":["Ca₂O₂","CaO","Ca₂O","CaO₂"],"answer":1,"explanation":"Ca²⁺ and O²⁻ combine in a 1:1 ratio.","source":"unit-07","difficulty":"core","unit":"Unit 07","originalSource":"quiz"},{"id":"u07-q-q03","domain":"Formula","prompt":"What is the correct formula for aluminium chloride?","options":["AlCl","AlCl₂","AlCl₃","Al₃Cl"],"answer":2,"explanation":"Three Cl⁻ ions balance Al³⁺.","source":"unit-07","difficulty":"core","unit":"Unit 07","originalSource":"quiz"},{"id":"u07-q-q04","domain":"Covalent","prompt":"Which substance consists of simple covalent molecules?","options":["Sodium chloride","Copper","Diamond","Carbon dioxide"],"answer":3,"explanation":"CO₂ contains discrete molecules.","source":"unit-07","difficulty":"core","unit":"Unit 07","originalSource":"quiz"},{"id":"u07-q-q05","domain":"Structure","prompt":"Which substance contains a giant metallic lattice?","options":["Copper","Methane","Water","Sodium chloride"],"answer":0,"explanation":"Copper is metallic.","source":"unit-07","difficulty":"core","unit":"Unit 07","originalSource":"quiz"},{"id":"u07-q-q06","domain":"Graphite","prompt":"Which feature supports graphite’s conductivity?","options":["No bonding","Delocalised electrons","Mobile chloride ions","Water molecules"],"answer":1,"explanation":"Electrons can move within the layers.","source":"unit-07","difficulty":"core","unit":"Unit 07","originalSource":"quiz"},{"id":"u07-q-q07","domain":"Polarity","prompt":"Which bond is expected to be most polar among these?","options":["C–C","Cl–Cl","H–F","H–H"],"answer":2,"explanation":"H–F has the largest electronegativity difference of the options.","source":"unit-07","difficulty":"core","unit":"Unit 07","originalSource":"quiz"},{"id":"u07-q-q08","domain":"Formula mass","prompt":"Using Ar values Na=23 and Cl=35.5, Mr of NaCl is:","options":["81.5","23","35.5","58.5"],"answer":3,"explanation":"23 + 35.5 = 58.5.","source":"unit-07","difficulty":"core","unit":"Unit 07","originalSource":"quiz"},{"id":"u07-q-q09","domain":"Equation","prompt":"Which equation is balanced?","options":["N₂ + 3H₂ → 2NH₃","2N₂ + H₂ → 2NH₃","N₂ + H₂ → NH₃","N₂ + 2H₂ → 2NH₃"],"answer":0,"explanation":"Both sides contain two N and six H atoms.","source":"unit-07","difficulty":"core","unit":"Unit 07","originalSource":"quiz"},{"id":"u07-q-q10","domain":"Subscripts","prompt":"Why must subscripts not be changed to balance an equation?","options":["It changes temperature","Changing a subscript changes the substance","Subscripts have no meaning","Only gases use subscripts"],"answer":1,"explanation":"A different subscript represents a different composition.","source":"unit-07","difficulty":"core","unit":"Unit 07","originalSource":"quiz"},{"id":"u07-q-q11","domain":"State symbols","prompt":"Which symbol identifies a solid?","options":["(g)","(aq)","(s)","(l)"],"answer":2,"explanation":"(s) denotes solid.","source":"unit-07","difficulty":"core","unit":"Unit 07","originalSource":"quiz"},{"id":"u07-q-q12","domain":"Conservation","prompt":"A balanced equation demonstrates conservation of:","options":["Temperature","Color","Volume in every reaction","Each type of atom"],"answer":3,"explanation":"Atom counts match across the reaction.","source":"unit-07","difficulty":"core","unit":"Unit 07","originalSource":"quiz"},{"id":"u07-q-q13","domain":"Evidence","prompt":"Which observation is strongest evidence for a precipitate reaction?","options":["A new insoluble solid appears","The container remains clear","A liquid changes shape","A solid is crushed"],"answer":0,"explanation":"A precipitate is an insoluble solid product.","source":"unit-07","difficulty":"core","unit":"Unit 07","originalSource":"quiz"},{"id":"u07-q-q14","domain":"Energy","prompt":"Which reaction from the supplied table is endothermic?","options":["Formation of ammonia","CaCO₃ → CaO + CO₂","CH₄ combustion","Formation of water"],"answer":1,"explanation":"The listed calcium-carbonate decomposition has positive ΔH.","source":"unit-07","difficulty":"core","unit":"Unit 07","originalSource":"quiz"},{"id":"u07-q-q15","domain":"Pathway","prompt":"On an energy diagram, activation energy is measured from:","options":["Reactants to products only","Temperature to pressure","Reactant energy to the pathway peak","Products to zero"],"answer":2,"explanation":"The barrier is the difference between reactants and the transition-state peak.","source":"unit-07","difficulty":"core","unit":"Unit 07","originalSource":"quiz"},{"id":"u07-q-q16","domain":"Catalyst","prompt":"What remains unchanged when a catalyst is added?","options":["Activation energy","Reaction pathway","Rate","Overall ΔH"],"answer":3,"explanation":"A catalyst lowers the barrier but does not change reactant/product energy difference.","source":"unit-07","difficulty":"core","unit":"Unit 07","originalSource":"quiz"},{"id":"u07-q-q17","domain":"Rate","prompt":"Which change generally increases reaction rate for a solid reactant?","options":["Increasing surface area","Lowering concentration","Cooling the system","Removing a catalyst"],"answer":0,"explanation":"Greater surface area increases accessible collision sites.","source":"unit-07","difficulty":"core","unit":"Unit 07","originalSource":"quiz"},{"id":"u07-q-q18","domain":"Rate data","prompt":"A shorter completion time for the same amount of reaction usually indicates:","options":["More atoms created","A faster average rate","A slower rate","No reaction"],"answer":1,"explanation":"The same change occurring in less time is faster.","source":"unit-07","difficulty":"core","unit":"Unit 07","originalSource":"quiz"},{"id":"u07-q-q19","domain":"Equilibrium","prompt":"Which statement is true at equilibrium?","options":["Reactant concentration is always zero","A catalyst shifts the position","Concentrations are constant but not necessarily equal","The forward reaction stops"],"answer":2,"explanation":"Equal forward and reverse rates keep concentrations constant.","source":"unit-07","difficulty":"core","unit":"Unit 07","originalSource":"quiz"},{"id":"u07-q-q20","domain":"Safety","prompt":"Which activity is appropriate for home or ordinary classroom use with adult approval and goggles?","options":["Burning magnesium without a lab","Mixing household cleaners","Heating a sealed gas-producing reaction","Timing an effervescent tablet in water"],"answer":3,"explanation":"The other activities present serious hazards.","source":"unit-07","difficulty":"core","unit":"Unit 07","originalSource":"quiz"},{"id":"u07-a-a01","domain":"Bonding","prompt":"Which force is central to ionic bonding?","options":["Electrostatic attraction between opposite charges","Gravity between molecules","Magnetic attraction between neutrons","Friction"],"answer":0,"explanation":"Ionic bonding is electrostatic attraction.","source":"unit-07","difficulty":"transfer","unit":"Unit 07","originalSource":"assessment"},{"id":"u07-a-a02","domain":"Bonding","prompt":"Which statement best describes a covalent bond?","options":["A physical mixture","A shared electron pair between atoms","A transferred neutron","A moving cation"],"answer":1,"explanation":"The introductory covalent model uses shared electron pairs.","source":"unit-07","difficulty":"transfer","unit":"Unit 07","originalSource":"assessment"},{"id":"u07-a-a03","domain":"Formula","prompt":"What formula results from K⁺ and O²⁻?","options":["K₂O₂","KO","K₂O","KO₂"],"answer":2,"explanation":"Two K⁺ ions balance one O²⁻ ion.","source":"unit-07","difficulty":"transfer","unit":"Unit 07","originalSource":"assessment"},{"id":"u07-a-a04","domain":"Formula","prompt":"What formula results from Al³⁺ and SO₄²⁻?","options":["Al₃(SO₄)₂","AlSO₄","Al₂SO₄","Al₂(SO₄)₃"],"answer":3,"explanation":"Two Al³⁺ give +6 and three sulfate ions give −6.","source":"unit-07","difficulty":"transfer","unit":"Unit 07","originalSource":"assessment"},{"id":"u07-a-a05","domain":"Formula","prompt":"Why are parentheses used in Ca(OH)₂?","options":["Two hydroxide ions are present","Calcium is repeated","The compound is molecular","The charge is zero before bonding"],"answer":0,"explanation":"The parentheses group the repeated polyatomic ion.","source":"unit-07","difficulty":"transfer","unit":"Unit 07","originalSource":"assessment"},{"id":"u07-a-a06","domain":"Structure","prompt":"Which substance is expected to conduct when molten but not when solid?","options":["Carbon dioxide","Sodium chloride","Methane","Diamond"],"answer":1,"explanation":"Molten ionic compounds have mobile ions.","source":"unit-07","difficulty":"transfer","unit":"Unit 07","originalSource":"assessment"},{"id":"u07-a-a07","domain":"Structure","prompt":"Which property is characteristic of many simple molecular substances?","options":["Malleability","Giant lattices in every case","Low melting and boiling points","Conductivity from mobile ions in the solid"],"answer":2,"explanation":"Weak intermolecular attractions often give low phase-change temperatures.","source":"unit-07","difficulty":"transfer","unit":"Unit 07","originalSource":"assessment"},{"id":"u07-a-a08","domain":"Structure","prompt":"Why is diamond hard?","options":["It contains mobile ions","Its molecules slide easily","It is metallic","Its atoms form a three-dimensional covalent network"],"answer":3,"explanation":"Many strong bonds extend through the network.","source":"unit-07","difficulty":"transfer","unit":"Unit 07","originalSource":"assessment"},{"id":"u07-a-a09","domain":"Structure","prompt":"Why is copper conductive?","options":["Delocalised electrons can move through the metallic structure","Copper dissolves into ions in air","It contains water","Its bonds are absent"],"answer":0,"explanation":"Mobile delocalised electrons carry charge.","source":"unit-07","difficulty":"transfer","unit":"Unit 07","originalSource":"assessment"},{"id":"u07-a-a10","domain":"Polarity","prompt":"Which statement distinguishes bond polarity from molecular polarity?","options":["Molecules have no geometry","A molecule’s shape can cause bond dipoles to cancel or reinforce","They are always identical","Only ions have polarity"],"answer":1,"explanation":"Whole-molecule polarity depends on both bond dipoles and arrangement.","source":"unit-07","difficulty":"transfer","unit":"Unit 07","originalSource":"assessment"},{"id":"u07-a-a11","domain":"Formula mass","prompt":"Using C=12 and O=16, Mr of CO₂ is:","options":["28","32","44","56"],"answer":2,"explanation":"12 + 2(16) = 44.","source":"unit-07","difficulty":"transfer","unit":"Unit 07","originalSource":"assessment"},{"id":"u07-a-a12","domain":"Notation","prompt":"In 2H₂O, the coefficient 2 indicates:","options":["Two oxygen atoms per molecule","A new substance H₄O₂","A charge","Two water molecules or formula units in the represented ratio"],"answer":3,"explanation":"The coefficient multiplies the entire formula.","source":"unit-07","difficulty":"transfer","unit":"Unit 07","originalSource":"assessment"},{"id":"u07-a-a13","domain":"Equation","prompt":"Which equation balances aluminium oxide formation?","options":["4Al + 3O₂ → 2Al₂O₃","Al₂ + O₃ → Al₂O₃","Al + O₂ → Al₂O₃","2Al + O₂ → Al₂O₃"],"answer":0,"explanation":"Four Al and six O atoms appear on both sides.","source":"unit-07","difficulty":"transfer","unit":"Unit 07","originalSource":"assessment"},{"id":"u07-a-a14","domain":"Equation","prompt":"Which equation balances iron(III) oxide formation?","options":["2Fe + O₂ → Fe₂O₃","4Fe + 3O₂ → 2Fe₂O₃","3Fe + 2O₂ → Fe₃O₄","Fe + O₂ → Fe₂O₃"],"answer":1,"explanation":"The coefficients 4:3:2 balance Fe₂O₃ formation.","source":"unit-07","difficulty":"transfer","unit":"Unit 07","originalSource":"assessment"},{"id":"u07-a-a15","domain":"Conservation","prompt":"Why is mass conserved in a closed ordinary chemical reaction?","options":["New nuclei are formed","Gas has no mass","The same atoms are rearranged into products","Energy becomes mass in large amounts"],"answer":2,"explanation":"Chemical reactions rearrange existing atoms.","source":"unit-07","difficulty":"transfer","unit":"Unit 07","originalSource":"assessment"},{"id":"u07-a-a16","domain":"Measurement","prompt":"A gas-producing reaction loses measured mass in an open beaker. The best explanation is:","options":["Atoms were destroyed","The law of conservation failed","The liquid lost all density","Gas left the balance system"],"answer":3,"explanation":"The escaped product is no longer included in the measured system.","source":"unit-07","difficulty":"transfer","unit":"Unit 07","originalSource":"assessment"},{"id":"u07-a-a17","domain":"Reaction evidence","prompt":"Which observation alone is least sufficient to prove a chemical reaction?","options":["A temperature change without a control","A new precipitate with confirmed composition","A new gas product collected and identified","New products detected analytically"],"answer":0,"explanation":"Physical processes can also change temperature.","source":"unit-07","difficulty":"transfer","unit":"Unit 07","originalSource":"assessment"},{"id":"u07-a-a18","domain":"Reaction type","prompt":"CH₄ + 2O₂ → CO₂ + 2H₂O is classified as:","options":["Freezing","Combustion","Precipitation","Electrolysis"],"answer":1,"explanation":"A hydrocarbon reacting with oxygen to form CO₂ and water is combustion.","source":"unit-07","difficulty":"transfer","unit":"Unit 07","originalSource":"assessment"},{"id":"u07-a-a19","domain":"Energy","prompt":"Which sign belongs to an exothermic ΔH?","options":["Always zero","Undefined","Negative","Positive"],"answer":2,"explanation":"Products are lower in enthalpy than reactants under this convention.","source":"unit-07","difficulty":"transfer","unit":"Unit 07","originalSource":"assessment"},{"id":"u07-a-a20","domain":"Energy","prompt":"Which process requires energy input?","options":["Making a chemical bond","Cooling surroundings during an exothermic reaction","Catalyst regeneration only","Breaking a chemical bond"],"answer":3,"explanation":"Bond breaking is endothermic.","source":"unit-07","difficulty":"transfer","unit":"Unit 07","originalSource":"assessment"},{"id":"u07-a-a21","domain":"Catalyst","prompt":"Which statement about a catalyst is accurate?","options":["It lowers activation energy but does not change ΔH","It increases product energy","It is always consumed","It changes atom conservation"],"answer":0,"explanation":"Catalysts alter the pathway, not overall energy difference.","source":"unit-07","difficulty":"transfer","unit":"Unit 07","originalSource":"assessment"},{"id":"u07-a-a22","domain":"Rate","prompt":"Increasing concentration usually increases rate because:","options":["The reaction becomes exothermic","More reactant particles occupy a given volume, increasing collision frequency","Particles become heavier","Activation energy disappears"],"answer":1,"explanation":"More particles per volume generally means more collisions.","source":"unit-07","difficulty":"transfer","unit":"Unit 07","originalSource":"assessment"},{"id":"u07-a-a23","domain":"Rate","prompt":"Why can higher temperature increase rate?","options":["All bonds disappear","Concentration becomes zero","More particles exceed activation energy","Subscripts change"],"answer":2,"explanation":"The energy distribution shifts so more collisions can succeed.","source":"unit-07","difficulty":"transfer","unit":"Unit 07","originalSource":"assessment"},{"id":"u07-a-a24","domain":"Rate","prompt":"Which design best isolates the effect of surface area?","options":["Use different masses and temperatures","Change three variables","Use one trial with no timing","Use equal tablet masses, equal water volume and temperature, changing only tablet size"],"answer":3,"explanation":"A fair comparison changes one factor while controlling others.","source":"unit-07","difficulty":"transfer","unit":"Unit 07","originalSource":"assessment"},{"id":"u07-a-a25","domain":"Rate data","prompt":"For equal reaction amounts, trial A finishes in 20 s and trial B in 50 s. Which is faster?","options":["Trial A","Trial B","They are equal","Cannot compare time"],"answer":0,"explanation":"The same extent of reaction occurs sooner in A.","source":"unit-07","difficulty":"transfer","unit":"Unit 07","originalSource":"assessment"},{"id":"u07-a-a26","domain":"Equilibrium","prompt":"At dynamic equilibrium:","options":["Only products remain","Forward and reverse rates are equal","Concentrations must be numerically equal","All molecules stop moving"],"answer":1,"explanation":"Equal rates maintain constant concentrations.","source":"unit-07","difficulty":"transfer","unit":"Unit 07","originalSource":"assessment"},{"id":"u07-a-a27","domain":"Equilibrium","prompt":"What does a catalyst do to an equilibrium system?","options":["It changes ΔH","It changes the equilibrium constant at fixed temperature","It helps both directions reach equilibrium faster without changing the equilibrium position","It forces only products"],"answer":2,"explanation":"The catalyst lowers barriers for both directions.","source":"unit-07","difficulty":"transfer","unit":"Unit 07","originalSource":"assessment"},{"id":"u07-a-a28","domain":"Industry","prompt":"Why is a compromise temperature used in the Haber process?","options":["Temperature has no effect","Only the catalyst matters","Ammonia forms instantly","It balances reaction rate, equilibrium yield, energy use, and safety/economics"],"answer":3,"explanation":"Industrial conditions balance multiple constraints.","source":"unit-07","difficulty":"transfer","unit":"Unit 07","originalSource":"assessment"},{"id":"u07-a-a29","domain":"Model limits","prompt":"Which statement is scientifically responsible?","options":["Ball-and-stick models show connectivity and shape but distort size and electron density","Models are exact photographs","Ionic solids are single molecules","The octet rule has no exceptions"],"answer":0,"explanation":"Models are useful but simplified.","source":"unit-07","difficulty":"transfer","unit":"Unit 07","originalSource":"assessment"},{"id":"u07-a-a30","domain":"Safety","prompt":"Which action is prohibited?","options":["Analyzing balanced equations","Mixing household cleaners to look for a reaction","Using published thermochemical data","Timing an approved effervescent tablet in water with goggles"],"answer":1,"explanation":"Household cleaners can generate toxic gases or corrosive mixtures.","source":"unit-07","difficulty":"transfer","unit":"Unit 07","originalSource":"assessment"},{"id":"u08-q-q01","domain":"Units","prompt":"Which is the SI unit of force?","options":["Newton","Watt","Kilogram metre per second","Joule"],"answer":0,"explanation":"Force is measured in newtons.","source":"unit-08","difficulty":"core","unit":"Unit 08","originalSource":"quiz"},{"id":"u08-q-q02","domain":"Scalars and vectors","prompt":"Which quantity is a vector?","options":["Energy","Velocity","Mass","Speed"],"answer":1,"explanation":"Velocity includes direction.","source":"unit-08","difficulty":"core","unit":"Unit 08","originalSource":"quiz"},{"id":"u08-q-q03","domain":"Speed","prompt":"A cyclist covers 45 m in 9 s. Speed is:","options":["405 m/s","4 m/s","5 m/s","9 m/s"],"answer":2,"explanation":"45/9=5 m/s.","source":"unit-08","difficulty":"core","unit":"Unit 08","originalSource":"quiz"},{"id":"u08-q-q04","domain":"Displacement","prompt":"A walk of 4 m north then 4 m south has:","options":["Distance 4 m, displacement 4 m","Distance 8 m, displacement 8 m","Distance 0, displacement 8 m","Distance 8 m, displacement 0"],"answer":3,"explanation":"Path length is 8 m and final position equals initial position.","source":"unit-08","difficulty":"core","unit":"Unit 08","originalSource":"quiz"},{"id":"u08-q-q05","domain":"Graphs","prompt":"A horizontal position–time line indicates:","options":["Rest","Constant nonzero velocity","Increasing speed","Constant acceleration"],"answer":0,"explanation":"Position is unchanged.","source":"unit-08","difficulty":"core","unit":"Unit 08","originalSource":"quiz"},{"id":"u08-q-q06","domain":"Acceleration","prompt":"Speed rises from 5 to 17 m/s in 6 s. Acceleration is:","options":["22 m/s²","2 m/s²","3 m/s²","12 m/s²"],"answer":1,"explanation":"(17−5)/6=2.","source":"unit-08","difficulty":"core","unit":"Unit 08","originalSource":"quiz"},{"id":"u08-q-q07","domain":"Net force","prompt":"Forces 20 N east and 8 N west give:","options":["28 N east","160 N east","12 N east","12 N west"],"answer":2,"explanation":"20−8=12 N east.","source":"unit-08","difficulty":"core","unit":"Unit 08","originalSource":"quiz"},{"id":"u08-q-q08","domain":"First law","prompt":"An object moving at constant velocity has:","options":["No forces at all","Increasing momentum","Zero mass","Zero net force"],"answer":3,"explanation":"Constant velocity means zero acceleration and therefore zero net force.","source":"unit-08","difficulty":"core","unit":"Unit 08","originalSource":"quiz"},{"id":"u08-q-q09","domain":"Second law","prompt":"A 10 kg object accelerates at 2 m/s². Net force is:","options":["20 N","5 N","8 N","12 N"],"answer":0,"explanation":"F=ma=10×2=20 N.","source":"unit-08","difficulty":"core","unit":"Unit 08","originalSource":"quiz"},{"id":"u08-q-q10","domain":"Weight","prompt":"Mass differs from weight because weight:","options":["Has no direction","Is gravitational force","Never changes","Is measured in kilograms"],"answer":1,"explanation":"Weight is force due to a gravitational field.","source":"unit-08","difficulty":"core","unit":"Unit 08","originalSource":"quiz"},{"id":"u08-q-q11","domain":"Third law","prompt":"A swimmer pushes water backward. The water:","options":["Pushes backward with smaller force","Changes the swimmer’s mass","Pushes the swimmer forward","Provides no force"],"answer":2,"explanation":"The interaction forces are equal and opposite.","source":"unit-08","difficulty":"core","unit":"Unit 08","originalSource":"quiz"},{"id":"u08-q-q12","domain":"Momentum","prompt":"A 3 kg object at −2 m/s has momentum:","options":["−1.5 kg·m/s","1 kg·m/s","6 J","−6 kg·m/s"],"answer":3,"explanation":"p=3×−2=−6.","source":"unit-08","difficulty":"core","unit":"Unit 08","originalSource":"quiz"},{"id":"u08-q-q13","domain":"Impulse","prompt":"Which change lowers average collision force for the same momentum change?","options":["Longer stopping time","Greater speed without changing time","Smaller contact area only","Shorter stopping time"],"answer":0,"explanation":"Favg=Δp/Δt.","source":"unit-08","difficulty":"core","unit":"Unit 08","originalSource":"quiz"},{"id":"u08-q-q14","domain":"Work","prompt":"No mechanical work is done by a force when:","options":["Time passes","There is no displacement in the force direction","The force is large","The object has mass"],"answer":1,"explanation":"Work requires displacement along the force component.","source":"unit-08","difficulty":"core","unit":"Unit 08","originalSource":"quiz"},{"id":"u08-q-q15","domain":"Kinetic energy","prompt":"A 1 kg object at 6 m/s has KE:","options":["3 J","6 J","18 J","36 J"],"answer":2,"explanation":"0.5×1×36=18 J.","source":"unit-08","difficulty":"core","unit":"Unit 08","originalSource":"quiz"},{"id":"u08-q-q16","domain":"Potential energy","prompt":"Which increases gravitational potential energy near Earth?","options":["Reducing time only","Changing color","Lowering height","Increasing height"],"answer":3,"explanation":"GPE increases with height.","source":"unit-08","difficulty":"core","unit":"Unit 08","originalSource":"quiz"},{"id":"u08-q-q17","domain":"Conservation","prompt":"Dissipated energy is:","options":["Transferred into less useful forms such as thermal energy","Converted into no energy","Always recoverable completely","Destroyed"],"answer":0,"explanation":"It remains energy but is more dispersed.","source":"unit-08","difficulty":"core","unit":"Unit 08","originalSource":"quiz"},{"id":"u08-q-q18","domain":"Power","prompt":"Power measures:","options":["Momentum change only","Energy transferred per unit time","Force per unit mass","Distance per unit time"],"answer":1,"explanation":"P=E/t.","source":"unit-08","difficulty":"core","unit":"Unit 08","originalSource":"quiz"},{"id":"u08-q-q19","domain":"Efficiency","prompt":"An efficiency greater than 100% would:","options":["Mean no input energy","Prove friction","Violate energy accounting for a passive device","Be ordinary"],"answer":2,"explanation":"Useful output cannot exceed total input in consistent accounting.","source":"unit-08","difficulty":"core","unit":"Unit 08","originalSource":"quiz"},{"id":"u08-q-q20","domain":"Safety","prompt":"Which investigation is appropriate?","options":["Testing stopping distance in traffic","Dropping heavy masses from a roof","Launching hard projectiles at people","Timing a slow rolling cart on a clear level floor with adult approval"],"answer":3,"explanation":"The low-speed controlled option is appropriate.","source":"unit-08","difficulty":"core","unit":"Unit 08","originalSource":"quiz"},{"id":"u08-a-a01","domain":"Measurement","prompt":"Which record is complete?","options":["5 metres east in 2.0 seconds","Fast motion","A long time","5"],"answer":0,"explanation":"It includes values, units, direction, and interval.","source":"unit-08","difficulty":"transfer","unit":"Unit 08","originalSource":"assessment"},{"id":"u08-a-a02","domain":"Vector","prompt":"Which is a vector?","options":["Time","Force","Energy","Distance"],"answer":1,"explanation":"Force includes magnitude and direction.","source":"unit-08","difficulty":"transfer","unit":"Unit 08","originalSource":"assessment"},{"id":"u08-a-a03","domain":"Speed","prompt":"150 m in 30 s equals:","options":["4500 m/s","3 m/s","5 m/s","30 m/s"],"answer":2,"explanation":"150/30=5.","source":"unit-08","difficulty":"transfer","unit":"Unit 08","originalSource":"assessment"},{"id":"u08-a-a04","domain":"Velocity","prompt":"A displacement of −24 m in 6 s gives average velocity:","options":["4 m/s","−18 m/s","144 m/s","−4 m/s"],"answer":3,"explanation":"−24/6=−4.","source":"unit-08","difficulty":"transfer","unit":"Unit 08","originalSource":"assessment"},{"id":"u08-a-a05","domain":"Graph","prompt":"The slope of a velocity–time graph gives:","options":["Acceleration","Power","Force","Displacement"],"answer":0,"explanation":"Acceleration is velocity change per time.","source":"unit-08","difficulty":"transfer","unit":"Unit 08","originalSource":"assessment"},{"id":"u08-a-a06","domain":"Graph area","prompt":"Velocity is 4 m/s for 5 s. Displacement is:","options":["9 m","20 m","0.8 m","4 m"],"answer":1,"explanation":"Area=4×5=20 m.","source":"unit-08","difficulty":"transfer","unit":"Unit 08","originalSource":"assessment"},{"id":"u08-a-a07","domain":"Acceleration","prompt":"Velocity changes from −3 to +5 m/s in 4 s. Acceleration is:","options":["0.5 m/s²","−2 m/s²","+2 m/s²","+8 m/s²"],"answer":2,"explanation":"(5−(−3))/4=2.","source":"unit-08","difficulty":"transfer","unit":"Unit 08","originalSource":"assessment"},{"id":"u08-a-a08","domain":"Free fall","prompt":"Ignoring air resistance near Earth, free-fall acceleration is approximately:","options":["98 m/s²","1 N","0.98 m/s²","9.8 m/s²"],"answer":3,"explanation":"g≈9.8 m/s².","source":"unit-08","difficulty":"transfer","unit":"Unit 08","originalSource":"assessment"},{"id":"u08-a-a09","domain":"Net force","prompt":"A 7 N left force and 13 N right force produce:","options":["6 N right","6 N left","20 N right","91 N right"],"answer":0,"explanation":"13−7=6 right.","source":"unit-08","difficulty":"transfer","unit":"Unit 08","originalSource":"assessment"},{"id":"u08-a-a10","domain":"Equilibrium","prompt":"An object is in translational equilibrium when:","options":["Mass is zero","Net force is zero","Velocity is zero only","No forces exist"],"answer":1,"explanation":"Zero resultant force gives no acceleration.","source":"unit-08","difficulty":"transfer","unit":"Unit 08","originalSource":"assessment"},{"id":"u08-a-a11","domain":"Second law","prompt":"A 2.5 kg object under 10 N net force accelerates at:","options":["25 m/s²","2.5 m/s²","4 m/s²","12.5 m/s²"],"answer":2,"explanation":"10/2.5=4.","source":"unit-08","difficulty":"transfer","unit":"Unit 08","originalSource":"assessment"},{"id":"u08-a-a12","domain":"Mass","prompt":"For fixed acceleration, tripling mass requires:","options":["Zero force","One-third the force","The same force","Three times the net force"],"answer":3,"explanation":"F=ma.","source":"unit-08","difficulty":"transfer","unit":"Unit 08","originalSource":"assessment"},{"id":"u08-a-a13","domain":"Weight","prompt":"A 12 kg mass near Earth weighs approximately:","options":["117.6 N","1200 N","1.22 N","12 N"],"answer":0,"explanation":"12×9.8=117.6 N.","source":"unit-08","difficulty":"transfer","unit":"Unit 08","originalSource":"assessment"},{"id":"u08-a-a14","domain":"First law","prompt":"A spacecraft coasts far from significant external forces. It:","options":["Loses mass","Continues at constant velocity","Stops because force ends","Accelerates automatically"],"answer":1,"explanation":"Newton’s first law predicts constant velocity.","source":"unit-08","difficulty":"transfer","unit":"Unit 08","originalSource":"assessment"},{"id":"u08-a-a15","domain":"Third law","prompt":"Third-law forces:","options":["Require contact only","Act on the same object and cancel","Act on different objects","Have unequal magnitudes"],"answer":2,"explanation":"The pair acts on two interacting objects.","source":"unit-08","difficulty":"transfer","unit":"Unit 08","originalSource":"assessment"},{"id":"u08-a-a17","domain":"Momentum","prompt":"A 0.5 kg ball moves at 8 m/s. Momentum is:","options":["4 kg·m/s","8 kg·m/s","16 kg·m/s","64 kg·m/s"],"answer":0,"explanation":"0.5×8=4.","source":"unit-08","difficulty":"transfer","unit":"Unit 08","originalSource":"assessment"},{"id":"u08-a-a18","domain":"Impulse","prompt":"A force of 25 N acts for 0.2 s. Impulse is:","options":["0.008 N·s","5 N·s","25.2 N·s","125 N·s"],"answer":1,"explanation":"25×0.2=5.","source":"unit-08","difficulty":"transfer","unit":"Unit 08","originalSource":"assessment"},{"id":"u08-a-a19","domain":"Conservation","prompt":"Two carts have total momentum 6 kg·m/s before an isolated collision. Afterward total is:","options":["0","3 kg·m/s","6 kg·m/s","Depends on kinetic energy only"],"answer":2,"explanation":"Total momentum is conserved.","source":"unit-08","difficulty":"transfer","unit":"Unit 08","originalSource":"assessment"},{"id":"u08-a-a20","domain":"Collision safety","prompt":"A crumple zone lowers average force mainly by:","options":["Increasing speed","Increasing mass","Eliminating momentum","Increasing stopping time for a given momentum change"],"answer":3,"explanation":"Longer stopping time reduces average force.","source":"unit-08","difficulty":"transfer","unit":"Unit 08","originalSource":"assessment"},{"id":"u08-a-a21","domain":"Work","prompt":"A 15 N force moves an object 4 m along the force. Work is:","options":["60 J","75 J","3.75 J","19 J"],"answer":0,"explanation":"15×4=60.","source":"unit-08","difficulty":"transfer","unit":"Unit 08","originalSource":"assessment"},{"id":"u08-a-a22","domain":"Kinetic energy","prompt":"A 4 kg object at 5 m/s has KE:","options":["20 J","50 J","100 J","10 J"],"answer":1,"explanation":"0.5×4×25=50.","source":"unit-08","difficulty":"transfer","unit":"Unit 08","originalSource":"assessment"},{"id":"u08-a-a23","domain":"GPE","prompt":"A 2 kg object rises 5 m at g=9.8 N/kg. GPE increase is:","options":["9.8 J","49 J","98 J","196 J"],"answer":2,"explanation":"2×9.8×5=98.","source":"unit-08","difficulty":"transfer","unit":"Unit 08","originalSource":"assessment"},{"id":"u08-a-a24","domain":"Energy system","prompt":"Gravitational potential energy near Earth belongs to:","options":["The object alone in all models","Time","The ruler","The object–Earth system"],"answer":3,"explanation":"It is interaction energy of the system.","source":"unit-08","difficulty":"transfer","unit":"Unit 08","originalSource":"assessment"},{"id":"u08-a-a25","domain":"Conservation","prompt":"A pendulum slows because of air resistance. Its initial mechanical energy is mainly transferred to:","options":["Thermal energy and sound in the system/surroundings","Nothing","New atoms","Extra mass"],"answer":0,"explanation":"Drag transfers energy.","source":"unit-08","difficulty":"transfer","unit":"Unit 08","originalSource":"assessment"},{"id":"u08-a-a26","domain":"Power","prompt":"A machine does 2400 J in 30 s. Power is:","options":["72,000 W","80 W","720 W","2370 W"],"answer":1,"explanation":"2400/30=80.","source":"unit-08","difficulty":"transfer","unit":"Unit 08","originalSource":"assessment"},{"id":"u08-a-a27","domain":"Efficiency","prompt":"Useful output 180 J from input 300 J gives:","options":["480%","40%","60%","120%"],"answer":2,"explanation":"180/300×100=60%.","source":"unit-08","difficulty":"transfer","unit":"Unit 08","originalSource":"assessment"},{"id":"u08-a-a28","domain":"Machine","prompt":"An ideal lever can reduce required force by:","options":["Creating energy","Reducing output work below zero","Ignoring conservation","Increasing effort distance"],"answer":3,"explanation":"Force-distance tradeoff preserves ideal work.","source":"unit-08","difficulty":"transfer","unit":"Unit 08","originalSource":"assessment"},{"id":"u08-a-a29","domain":"Model limits","prompt":"Which is responsible?","options":["A free-body diagram simplifies an object and external forces; it is not a photograph","Graph curves are literal hills","Vectors require no reference direction","Equations remove need for measurement"],"answer":0,"explanation":"Models are purposeful simplifications.","source":"unit-08","difficulty":"transfer","unit":"Unit 08","originalSource":"assessment"},{"id":"u09-q-q01","domain":"Current","prompt":"Current is charge transferred per:","options":["Unit time","Unit mass","Unit distance","Unit resistance"],"answer":0,"explanation":"I=Q/t.","source":"unit-09","difficulty":"core","unit":"Unit 09","originalSource":"quiz"},{"id":"u09-q-q02","domain":"Voltage","prompt":"Potential difference is energy transferred per:","options":["Kilogram","Coulomb","Second","Metre"],"answer":1,"explanation":"V=E/Q.","source":"unit-09","difficulty":"core","unit":"Unit 09","originalSource":"quiz"},{"id":"u09-q-q03","domain":"Ohm","prompt":"At constant temperature, an ohmic resistor has:","options":["Constant power only","Zero resistance","V proportional to I","V proportional to 1/I"],"answer":2,"explanation":"The I–V graph is linear through the origin.","source":"unit-09","difficulty":"core","unit":"Unit 09","originalSource":"quiz"},{"id":"u09-q-q04","domain":"Series","prompt":"In a simple series circuit, current is:","options":["Zero everywhere","Largest after the source only","Different at every point","The same through each component"],"answer":3,"explanation":"One path gives the same steady current.","source":"unit-09","difficulty":"core","unit":"Unit 09","originalSource":"quiz"},{"id":"u09-q-q05","domain":"Parallel","prompt":"In an ideal parallel circuit, each branch has:","options":["The same potential difference","The same resistance","Zero current","The same power always"],"answer":0,"explanation":"Branch voltage equals source voltage.","source":"unit-09","difficulty":"core","unit":"Unit 09","originalSource":"quiz"},{"id":"u09-q-q06","domain":"Power","prompt":"A 5 V device drawing 2 A uses:","options":["7 W","10 W","25 W","2.5 W"],"answer":1,"explanation":"P=VI=10 W.","source":"unit-09","difficulty":"core","unit":"Unit 09","originalSource":"quiz"},{"id":"u09-q-q07","domain":"Energy","prompt":"A 20 W device runs for 30 s. Energy transferred is:","options":["0.67 J","50 J","600 J","1200 J"],"answer":2,"explanation":"E=Pt=600 J.","source":"unit-09","difficulty":"core","unit":"Unit 09","originalSource":"quiz"},{"id":"u09-q-q08","domain":"Electromagnet","prompt":"Which increases field strength?","options":["Less current","No circuit","Removing all magnetic material","More coil turns"],"answer":3,"explanation":"More turns generally strengthen the field.","source":"unit-09","difficulty":"core","unit":"Unit 09","originalSource":"quiz"},{"id":"u09-q-q09","domain":"Induction","prompt":"A changing magnetic field can induce:","options":["Potential difference","Mass","Gravity","Chemical identity"],"answer":0,"explanation":"Induction produces emf/potential difference.","source":"unit-09","difficulty":"core","unit":"Unit 09","originalSource":"quiz"},{"id":"u09-q-q10","domain":"Wave speed","prompt":"For fixed wave speed, increasing frequency makes wavelength:","options":["Longer","Shorter","Unchanged","Zero"],"answer":1,"explanation":"λ=v/f.","source":"unit-09","difficulty":"core","unit":"Unit 09","originalSource":"quiz"},{"id":"u09-q-q11","domain":"Amplitude","prompt":"Amplitude most directly describes:","options":["Distance between crests","Wave speed","Maximum displacement from equilibrium","Cycles per second"],"answer":2,"explanation":"Amplitude is maximum displacement in the model.","source":"unit-09","difficulty":"core","unit":"Unit 09","originalSource":"quiz"},{"id":"u09-q-q12","domain":"Reflection","prompt":"A ray strikes at 30° to the normal. Reflection angle is:","options":["60°","90°","120°","30°"],"answer":3,"explanation":"The angles are equal.","source":"unit-09","difficulty":"core","unit":"Unit 09","originalSource":"quiz"},{"id":"u09-q-q13","domain":"Sound","prompt":"Pitch generally increases with:","options":["Frequency","Amplitude only","Wavelength only in every medium","Distance"],"answer":0,"explanation":"Higher frequency is perceived as higher pitch.","source":"unit-09","difficulty":"core","unit":"Unit 09","originalSource":"quiz"},{"id":"u09-q-q14","domain":"EM spectrum","prompt":"Which has higher frequency than visible light?","options":["Microwave","Ultraviolet","Radio","Infrared"],"answer":1,"explanation":"Ultraviolet lies above visible frequency.","source":"unit-09","difficulty":"core","unit":"Unit 09","originalSource":"quiz"},{"id":"u09-q-q15","domain":"Vacuum","prompt":"Which can travel through a vacuum?","options":["Seismic waves","Sound","Visible light","Water waves"],"answer":2,"explanation":"Electromagnetic waves can travel in vacuum.","source":"unit-09","difficulty":"core","unit":"Unit 09","originalSource":"quiz"},{"id":"u09-q-q16","domain":"Wave model","prompt":"Diffraction supports:","options":["A static-charge model","A circuit model","A chemical model","A wave description"],"answer":3,"explanation":"Spreading and interference are wave phenomena.","source":"unit-09","difficulty":"core","unit":"Unit 09","originalSource":"quiz"},{"id":"u09-q-q17","domain":"Digital","prompt":"Binary uses:","options":["Two symbols or levels","Ten continuous voltages only","No encoding","Only sound"],"answer":0,"explanation":"Binary represents states with two symbols.","source":"unit-09","difficulty":"core","unit":"Unit 09","originalSource":"quiz"},{"id":"u09-q-q18","domain":"Noise","prompt":"Error detection can:","options":["Remove all energy costs","Identify some corrupted data","Guarantee perfect security","Increase light speed"],"answer":1,"explanation":"It detects certain errors but is not complete protection.","source":"unit-09","difficulty":"core","unit":"Unit 09","originalSource":"quiz"},{"id":"u09-q-q19","domain":"Access","prompt":"A communication design should evaluate:","options":["Cost only","Color only","Accessibility, privacy, security, energy, and reliability","Speed only"],"answer":2,"explanation":"Engineering requires multiple tradeoffs.","source":"unit-09","difficulty":"core","unit":"Unit 09","originalSource":"quiz"},{"id":"u09-q-q20","domain":"Safety","prompt":"Which is prohibited?","options":["Using a battery holder with current limiting","Analyzing a recorded waveform","Encoding text in binary","Opening mains-powered equipment"],"answer":3,"explanation":"Mains equipment presents serious shock and fire hazards.","source":"unit-09","difficulty":"core","unit":"Unit 09","originalSource":"quiz"},{"id":"u09-a-a01","domain":"Charge","prompt":"3 A flows for 4 s. Charge is:","options":["12 C","24 C","0.75 C","7 C"],"answer":0,"explanation":"Q=It=12 C.","source":"unit-09","difficulty":"transfer","unit":"Unit 09","originalSource":"assessment"},{"id":"u09-a-a02","domain":"Voltage","prompt":"18 J transferred to 6 C gives:","options":["108 V","3 V","6 V","12 V"],"answer":1,"explanation":"V=18/6=3 V.","source":"unit-09","difficulty":"transfer","unit":"Unit 09","originalSource":"assessment"},{"id":"u09-a-a03","domain":"Resistance","prompt":"9 V and 0.3 A give resistance:","options":["9.3 Ω","27 Ω","30 Ω","2.7 Ω"],"answer":2,"explanation":"R=9/0.3=30 Ω.","source":"unit-09","difficulty":"transfer","unit":"Unit 09","originalSource":"assessment"},{"id":"u09-a-a04","domain":"Power","prompt":"A 12 V, 2 A device uses:","options":["144 W","6 W","14 W","24 W"],"answer":3,"explanation":"P=24 W.","source":"unit-09","difficulty":"transfer","unit":"Unit 09","originalSource":"assessment"},{"id":"u09-a-a05","domain":"Energy","prompt":"A 60 W device runs 120 s. Energy is:","options":["7200 J","7200 W","0.5 J","180 J"],"answer":0,"explanation":"E=Pt=7200 J.","source":"unit-09","difficulty":"transfer","unit":"Unit 09","originalSource":"assessment"},{"id":"u09-a-a06","domain":"Series","prompt":"3 Ω, 5 Ω, and 7 Ω in series equal:","options":["10 Ω","15 Ω","105 Ω","5 Ω"],"answer":1,"explanation":"Series total is 15 Ω.","source":"unit-09","difficulty":"transfer","unit":"Unit 09","originalSource":"assessment"},{"id":"u09-a-a07","domain":"Parallel","prompt":"A parallel circuit’s total resistance is:","options":["The sum of branches","Greater than every branch","Less than the smallest branch","Always zero"],"answer":2,"explanation":"Additional paths lower equivalent resistance.","source":"unit-09","difficulty":"transfer","unit":"Unit 09","originalSource":"assessment"},{"id":"u09-a-a08","domain":"Junction","prompt":"5 A enters; 2 A leaves one branch. Other branch current is:","options":["5 A","7 A","2.5 A","3 A"],"answer":3,"explanation":"5−2=3 A.","source":"unit-09","difficulty":"transfer","unit":"Unit 09","originalSource":"assessment"},{"id":"u09-a-a09","domain":"I–V graph","prompt":"A curved I–V graph indicates:","options":["Resistance changes over the range","Resistance is always zero","No current","Perfect proportionality"],"answer":0,"explanation":"Nonlinearity means V/I is not constant.","source":"unit-09","difficulty":"transfer","unit":"Unit 09","originalSource":"assessment"},{"id":"u09-a-a10","domain":"Safety","prompt":"Which is safe?","options":["Shorting a 9 V battery","Using an approved 3 V circuit kit with a resistor","Opening a power strip","Touching bare mains wires"],"answer":1,"explanation":"The approved low-voltage kit is appropriate.","source":"unit-09","difficulty":"transfer","unit":"Unit 09","originalSource":"assessment"},{"id":"u09-a-a11","domain":"Magnetic field","prompt":"Field lines around a bar magnet are:","options":["Sound paths","A physical substance","A representation of direction and relative strength","Electron orbits"],"answer":2,"explanation":"They are a model.","source":"unit-09","difficulty":"transfer","unit":"Unit 09","originalSource":"assessment"},{"id":"u09-a-a12","domain":"Motor effect","prompt":"Force on a current-carrying wire depends on:","options":["Only wire color","Only mass","No interaction","Current and magnetic field"],"answer":3,"explanation":"Current and magnetic field determine the effect.","source":"unit-09","difficulty":"transfer","unit":"Unit 09","originalSource":"assessment"},{"id":"u09-a-a13","domain":"Induction","prompt":"Increasing rate of flux change generally:","options":["Increases induced potential difference","Eliminates induction","Creates mass","Stops current everywhere"],"answer":0,"explanation":"Faster change generally increases induced emf.","source":"unit-09","difficulty":"transfer","unit":"Unit 09","originalSource":"assessment"},{"id":"u09-a-a14","domain":"Transformer","prompt":"A step-up transformer ideally increases voltage while:","options":["Increasing both without limit","Decreasing current for similar power transfer","Creating energy","Working on steady DC"],"answer":1,"explanation":"Ideal power is approximately conserved.","source":"unit-09","difficulty":"transfer","unit":"Unit 09","originalSource":"assessment"},{"id":"u09-a-a15","domain":"Wave equation","prompt":"A 300 m/s wave at 150 Hz has wavelength:","options":["45000 m","0.5 m","2 m","150 m"],"answer":2,"explanation":"λ=v/f=2 m.","source":"unit-09","difficulty":"transfer","unit":"Unit 09","originalSource":"assessment"},{"id":"u09-a-a16","domain":"Period","prompt":"Frequency 20 Hz means period:","options":["0.2 s","20 s","400 s","0.05 s"],"answer":3,"explanation":"T=1/20=0.05 s.","source":"unit-09","difficulty":"transfer","unit":"Unit 09","originalSource":"assessment"},{"id":"u09-a-a17","domain":"Refraction","prompt":"When light enters glass from air, its speed:","options":["Decreases","Becomes zero","Must stay identical","Increases"],"answer":0,"explanation":"Light travels slower in glass.","source":"unit-09","difficulty":"transfer","unit":"Unit 09","originalSource":"assessment"},{"id":"u09-a-a18","domain":"Frequency in refraction","prompt":"Across a boundary, frequency is:","options":["Zero","Set by source and stays constant","Always doubled","Always halved"],"answer":1,"explanation":"Frequency remains constant.","source":"unit-09","difficulty":"transfer","unit":"Unit 09","originalSource":"assessment"},{"id":"u09-a-a19","domain":"Diffraction","prompt":"Longer wavelengths generally diffract:","options":["Not at all","Only in vacuum","More strongly for the same opening","Less strongly always"],"answer":2,"explanation":"Relative opening size controls spreading.","source":"unit-09","difficulty":"transfer","unit":"Unit 09","originalSource":"assessment"},{"id":"u09-a-a20","domain":"Sound","prompt":"Which change raises pitch?","options":["Higher amplitude only","Greater distance","Longer exposure","Higher frequency"],"answer":3,"explanation":"Pitch tracks frequency.","source":"unit-09","difficulty":"transfer","unit":"Unit 09","originalSource":"assessment"},{"id":"u09-a-a21","domain":"Decibels","prompt":"Safe sound evaluation must consider:","options":["Level, duration, frequency, distance, and individual context","Frequency only","Color only","Mass only"],"answer":0,"explanation":"Exposure risk depends on multiple factors.","source":"unit-09","difficulty":"transfer","unit":"Unit 09","originalSource":"assessment"},{"id":"u09-a-a22","domain":"EM order","prompt":"Which sequence is increasing frequency?","options":["Microwave → radio → infrared → visible","Radio → microwave → infrared → visible","Visible → infrared → microwave → radio","Gamma → X-ray → UV → visible"],"answer":1,"explanation":"That is the correct increasing order.","source":"unit-09","difficulty":"transfer","unit":"Unit 09","originalSource":"assessment"},{"id":"u09-a-a23","domain":"Photon energy","prompt":"Higher-frequency electromagnetic radiation has:","options":["Same photon energy","No photons","Higher photon energy","Lower photon energy always"],"answer":2,"explanation":"E=hf.","source":"unit-09","difficulty":"transfer","unit":"Unit 09","originalSource":"assessment"},{"id":"u09-a-a24","domain":"Wave evidence","prompt":"Interference is strongest evidence for:","options":["Ohm’s law","Charge conservation","Series resistance","Wave behavior"],"answer":3,"explanation":"Interference arises from superposition.","source":"unit-09","difficulty":"transfer","unit":"Unit 09","originalSource":"assessment"},{"id":"u09-a-a25","domain":"Photon model","prompt":"Photoelectric evidence is explained using:","options":["Quantized photons","Only sound waves","Series circuits","Classical rays alone"],"answer":0,"explanation":"Photon energy explains threshold behavior.","source":"unit-09","difficulty":"transfer","unit":"Unit 09","originalSource":"assessment"},{"id":"u09-a-a26","domain":"Digital sampling","prompt":"If sampling frequency is too low:","options":["Bandwidth becomes infinite","Aliasing or information loss can occur","Reconstruction is guaranteed","Noise disappears"],"answer":1,"explanation":"Undersampling misrepresents the signal.","source":"unit-09","difficulty":"transfer","unit":"Unit 09","originalSource":"assessment"},{"id":"u09-a-a27","domain":"Parity","prompt":"Parity is a form of:","options":["Wave speed control","Resistance","Error detection","Encryption"],"answer":2,"explanation":"It checks data consistency.","source":"unit-09","difficulty":"transfer","unit":"Unit 09","originalSource":"assessment"},{"id":"u09-a-a29","domain":"System model","prompt":"A complete communication system includes:","options":["Source, encoding, channel, receiver, and decoding","Only a source","Only a wire","Only a battery"],"answer":0,"explanation":"All stages are needed.","source":"unit-09","difficulty":"transfer","unit":"Unit 09","originalSource":"assessment"},{"id":"u10-q-q01","domain":"Systems","prompt":"A reservoir is:","options":["A stored quantity of matter or energy","A transfer rate only","Always a lake","A feedback"],"answer":0,"explanation":"Reservoir means stored amount within a defined system.","source":"unit-10","difficulty":"core","unit":"Unit 10","originalSource":"quiz"},{"id":"u10-q-q02","domain":"Feedback","prompt":"A negative feedback:","options":["Amplifies an initial change","Opposes part of an initial change","Eliminates all change","Is always harmful"],"answer":1,"explanation":"Negative feedback dampens or opposes change.","source":"unit-10","difficulty":"core","unit":"Unit 10","originalSource":"quiz"},{"id":"u10-q-q03","domain":"Interior","prompt":"S waves support a liquid outer core because they:","options":["Measure age directly","Travel fastest in liquids","Do not propagate through liquids","Only occur at the surface"],"answer":2,"explanation":"S waves require shear rigidity.","source":"unit-10","difficulty":"core","unit":"Unit 10","originalSource":"quiz"},{"id":"u10-q-q04","domain":"Plate boundary","prompt":"Transform boundaries mainly involve:","options":["Crust creation only","Subduction only","No earthquakes","Lateral plate motion"],"answer":3,"explanation":"Transform plates slide past each other.","source":"unit-10","difficulty":"core","unit":"Unit 10","originalSource":"quiz"},{"id":"u10-q-q05","domain":"Rock cycle","prompt":"Which pathway is possible?","options":["Sedimentary rock melting and later crystallizing as igneous rock","Only one fixed sequence","Igneous rock never weathering","Metamorphic rock forming only at the surface"],"answer":0,"explanation":"The rock cycle has many pathways.","source":"unit-10","difficulty":"core","unit":"Unit 10","originalSource":"quiz"},{"id":"u10-q-q07","domain":"Water budget","prompt":"P=90, ET=35, runoff=40 mm. Δstorage is:","options":["165 mm","5 mm","15 mm","55 mm"],"answer":2,"explanation":"90−35−40=15 mm.","source":"unit-10","difficulty":"core","unit":"Unit 10","originalSource":"quiz"},{"id":"u10-q-q08","domain":"Groundwater","prompt":"Groundwater is stored mainly in:","options":["A single global underground river","Clouds","The inner core","Pores and fractures"],"answer":3,"explanation":"It occupies connected pore spaces and fractures.","source":"unit-10","difficulty":"core","unit":"Unit 10","originalSource":"quiz"},{"id":"u10-q-q09","domain":"Carbon","prompt":"Which transfers carbon from atmosphere to biosphere?","options":["Photosynthesis","Respiration","Combustion","Volcanism"],"answer":0,"explanation":"Photosynthesis fixes atmospheric CO₂.","source":"unit-10","difficulty":"core","unit":"Unit 10","originalSource":"quiz"},{"id":"u10-q-q10","domain":"Nitrogen","prompt":"Denitrification commonly returns nitrogen to:","options":["Sunlight","The atmosphere as N₂","Only rocks","The inner core"],"answer":1,"explanation":"Denitrification converts reactive nitrogen toward gaseous forms.","source":"unit-10","difficulty":"core","unit":"Unit 10","originalSource":"quiz"},{"id":"u10-q-q11","domain":"Phosphorus","prompt":"A major source of phosphate to ecosystems is:","options":["Solar radiation","Earth’s outer core","Rock weathering","Atmospheric N₂ fixation"],"answer":2,"explanation":"Weathering releases phosphate minerals.","source":"unit-10","difficulty":"core","unit":"Unit 10","originalSource":"quiz"},{"id":"u10-q-q12","domain":"Residence time","prompt":"Reservoir 500, outflow 25/year gives:","options":["25 years","12,500 years","5 years","20 years"],"answer":3,"explanation":"500/25=20 years.","source":"unit-10","difficulty":"core","unit":"Unit 10","originalSource":"quiz"},{"id":"u10-q-q13","domain":"Climate","prompt":"Earth’s long-term energy balance compares:","options":["Incoming, reflected, absorbed, and outgoing energy","Only rainfall","Only wind","Only plate speed"],"answer":0,"explanation":"Climate energy accounting tracks radiative flows.","source":"unit-10","difficulty":"core","unit":"Unit 10","originalSource":"quiz"},{"id":"u10-q-q14","domain":"Albedo","prompt":"Higher albedo means:","options":["Higher density","A larger reflected fraction","More absorption in every case","No reflection"],"answer":1,"explanation":"Albedo is the reflected fraction.","source":"unit-10","difficulty":"core","unit":"Unit 10","originalSource":"quiz"},{"id":"u10-q-q15","domain":"Greenhouse gas","prompt":"Which is a greenhouse gas?","options":["Argon only","Helium only","Carbon dioxide","Nitrogen only"],"answer":2,"explanation":"CO₂ absorbs and emits infrared radiation.","source":"unit-10","difficulty":"core","unit":"Unit 10","originalSource":"quiz"},{"id":"u10-q-q16","domain":"Climate evidence","prompt":"Which record directly measures atmospheric composition?","options":["A plate-boundary map","A mineral hardness test","A river cross-section","Instrumental gas concentration data"],"answer":3,"explanation":"Atmospheric monitoring measures gas concentrations.","source":"unit-10","difficulty":"core","unit":"Unit 10","originalSource":"quiz"},{"id":"u10-q-q17","domain":"Human modification","prompt":"Fertilizer can alter:","options":["Nitrogen and phosphorus fluxes","Plate velocity only","Earth’s core state","Solar output"],"answer":0,"explanation":"Fertilizer changes reactive nutrient transfers.","source":"unit-10","difficulty":"core","unit":"Unit 10","originalSource":"quiz"},{"id":"u10-q-q18","domain":"Hazards","prompt":"Hazard maps are best used to:","options":["Replace emergency plans","Support risk planning, not exact event timing","Predict the exact next earthquake","Prove no risk elsewhere"],"answer":1,"explanation":"They inform probabilities and exposure.","source":"unit-10","difficulty":"core","unit":"Unit 10","originalSource":"quiz"},{"id":"u10-q-q19","domain":"Justice","prompt":"Environmental risk is unequal because:","options":["Data are never useful","Hazards affect only cities","Exposure, vulnerability, resources, and decision power differ","Physical laws change by neighborhood"],"answer":2,"explanation":"Social and infrastructural conditions shape risk.","source":"unit-10","difficulty":"core","unit":"Unit 10","originalSource":"quiz"},{"id":"u10-a-a01","domain":"System boundary","prompt":"Why define a system boundary?","options":["To identify included reservoirs, transfers, inputs, and outputs","To prove the system is isolated","To remove uncertainty","To make every model exact"],"answer":0,"explanation":"Boundaries determine what is counted and what crosses the system.","source":"unit-10","difficulty":"transfer","unit":"Unit 10","originalSource":"assessment"},{"id":"u10-a-a02","domain":"Flux units","prompt":"Which unit is appropriate for a flux?","options":["degrees","kg/year","kg only","metres only"],"answer":1,"explanation":"A flux is amount per time.","source":"unit-10","difficulty":"transfer","unit":"Unit 10","originalSource":"assessment"},{"id":"u10-a-a03","domain":"Density","prompt":"A 240 g rock occupies 80 cm³. Density is:","options":["19,200 g/cm³","0.33 g/cm³","3.0 g/cm³","160 g/cm³"],"answer":2,"explanation":"240/80=3.0 g/cm³.","source":"unit-10","difficulty":"transfer","unit":"Unit 10","originalSource":"assessment"},{"id":"u10-a-a04","domain":"Seismic lag","prompt":"P arrives at 12 s and S at 21 s. S–P lag is:","options":["12 s","21 s","33 s","9 s"],"answer":3,"explanation":"21−12=9 s.","source":"unit-10","difficulty":"transfer","unit":"Unit 10","originalSource":"assessment"},{"id":"u10-a-a05","domain":"Epicenter","prompt":"One station’s S–P lag gives:","options":["A distance estimate only","Exact latitude and longitude","Earthquake magnitude only","Fault depth exactly"],"answer":0,"explanation":"Direction requires more stations or information.","source":"unit-10","difficulty":"transfer","unit":"Unit 10","originalSource":"assessment"},{"id":"u10-a-a06","domain":"Convection","prompt":"Convection is driven by:","options":["Magnetic poles alone","Density differences and gravity with energy transfer","Only sound waves","No material motion"],"answer":1,"explanation":"Buoyancy and gravity drive convective movement.","source":"unit-10","difficulty":"transfer","unit":"Unit 10","originalSource":"assessment"},{"id":"u10-a-a07","domain":"Divergent boundary","prompt":"A continental rift is associated with:","options":["Collision only","No tectonics","Divergence","Transform motion"],"answer":2,"explanation":"Rifts form where continental lithosphere extends.","source":"unit-10","difficulty":"transfer","unit":"Unit 10","originalSource":"assessment"},{"id":"u10-a-a08","domain":"Subduction","prompt":"Oceanic lithosphere commonly subducts because it is:","options":["Always younger than continental crust","Liquid","Made only of granite","Relatively dense"],"answer":3,"explanation":"Cooling oceanic lithosphere can become dense enough to sink.","source":"unit-10","difficulty":"transfer","unit":"Unit 10","originalSource":"assessment"},{"id":"u10-a-a09","domain":"Weathering","prompt":"Oxidation of iron-bearing minerals is:","options":["Chemical weathering","Physical erosion","Deposition","Melting"],"answer":0,"explanation":"Oxidation changes mineral chemistry.","source":"unit-10","difficulty":"transfer","unit":"Unit 10","originalSource":"assessment"},{"id":"u10-a-a10","domain":"Deposition","prompt":"Deposition occurs when:","options":["Gravity disappears","Transport capacity decreases","Weathering stops globally","Water becomes pure"],"answer":1,"explanation":"Sediment settles when transport can no longer carry it.","source":"unit-10","difficulty":"transfer","unit":"Unit 10","originalSource":"assessment"},{"id":"u10-a-a11","domain":"Water budget","prompt":"P=120, ET=55, runoff=45 mm. Storage change is:","options":["220 mm","10 mm","20 mm","65 mm"],"answer":2,"explanation":"120−55−45=20 mm.","source":"unit-10","difficulty":"transfer","unit":"Unit 10","originalSource":"assessment"},{"id":"u10-a-a12","domain":"Infiltration","prompt":"Which generally promotes infiltration?","options":["Continuous pavement","Compacted surface only","A sealed roof","Permeable soil and vegetation"],"answer":3,"explanation":"Permeability and roots favor entry of water.","source":"unit-10","difficulty":"transfer","unit":"Unit 10","originalSource":"assessment"},{"id":"u10-a-a13","domain":"Aquifer","prompt":"An aquifer is:","options":["A material body that stores and transmits useful groundwater","Any underground cavity","The water table itself","A surface watershed"],"answer":0,"explanation":"Aquifers transmit and store groundwater.","source":"unit-10","difficulty":"transfer","unit":"Unit 10","originalSource":"assessment"},{"id":"u10-a-a14","domain":"Carbon balance","prompt":"Inputs 90, outputs 75 units/year produce:","options":["165 units/year","+15 units/year","−15 units/year","0"],"answer":1,"explanation":"Net change is +15.","source":"unit-10","difficulty":"transfer","unit":"Unit 10","originalSource":"assessment"},{"id":"u10-a-a15","domain":"Carbon pathway","prompt":"Which is a slow carbon pathway?","options":["Photosynthesis","Daily air–sea exchange","Carbonate sediment burial","Respiration"],"answer":2,"explanation":"Geological burial is slow relative to biological exchange.","source":"unit-10","difficulty":"transfer","unit":"Unit 10","originalSource":"assessment"},{"id":"u10-a-a16","domain":"Nitrogen fixation","prompt":"Which can fix nitrogen?","options":["All animals directly","Sunlight alone","Phosphate rock only","Certain microbes"],"answer":3,"explanation":"Some microbes convert N₂ into reactive nitrogen.","source":"unit-10","difficulty":"transfer","unit":"Unit 10","originalSource":"assessment"},{"id":"u10-a-a17","domain":"Nitrification","prompt":"Nitrification converts reduced nitrogen toward:","options":["Nitrite and nitrate","Atmospheric carbon dioxide","Phosphate rock","Metallic iron"],"answer":0,"explanation":"Nitrifying microbes oxidize ammonium.","source":"unit-10","difficulty":"transfer","unit":"Unit 10","originalSource":"assessment"},{"id":"u10-a-a18","domain":"Phosphorus","prompt":"Why can phosphorus limitation occur?","options":["It is destroyed during uptake","Phosphate availability can be low and has no large atmospheric reservoir","Phosphorus is not biological","All rocks dissolve instantly"],"answer":1,"explanation":"Its supply is constrained by geological and biological processes.","source":"unit-10","difficulty":"transfer","unit":"Unit 10","originalSource":"assessment"},{"id":"u10-a-a19","domain":"Eutrophication","prompt":"A likely sequence is:","options":["Plate motion → nitrate loss only","Evaporation → radioactive decay","Nutrient input → high production → decomposition → oxygen decline","Oxygen rise → no organisms → more nutrients"],"answer":2,"explanation":"This is the classic eutrophication pathway.","source":"unit-10","difficulty":"transfer","unit":"Unit 10","originalSource":"assessment"},{"id":"u10-a-a20","domain":"Residence time","prompt":"A 3000-unit reservoir with 100-unit/year outflow has:","options":["100 years","300,000 years","3 years","30 years"],"answer":3,"explanation":"3000/100=30 years.","source":"unit-10","difficulty":"transfer","unit":"Unit 10","originalSource":"assessment"},{"id":"u10-a-a21","domain":"Albedo","prompt":"Incoming 340 W/m², albedo 0.25. Absorbed is:","options":["255 W/m²","340 W/m²","425 W/m²","85 W/m²"],"answer":0,"explanation":"340×0.75=255 W/m².","source":"unit-10","difficulty":"transfer","unit":"Unit 10","originalSource":"assessment"},{"id":"u10-a-a22","domain":"Energy imbalance","prompt":"Absorbed 241, outgoing 239 W/m² means:","options":["0","+2 W/m²","+480 W/m²","−2 W/m²"],"answer":1,"explanation":"241−239=+2 W/m².","source":"unit-10","difficulty":"transfer","unit":"Unit 10","originalSource":"assessment"},{"id":"u10-a-a23","domain":"Weather","prompt":"Which is weather?","options":["Long-term monsoon statistics","Thirty-year frost frequency","A tornado warning today","A 50-year temperature trend"],"answer":2,"explanation":"Weather is short-term atmospheric condition.","source":"unit-10","difficulty":"transfer","unit":"Unit 10","originalSource":"assessment"},{"id":"u10-a-a24","domain":"Climate forcing","prompt":"Increasing greenhouse-gas concentration is a:","options":["Plate boundary","Mineral property","Watershed outlet","Radiative forcing"],"answer":3,"explanation":"It alters Earth’s radiative energy balance.","source":"unit-10","difficulty":"transfer","unit":"Unit 10","originalSource":"assessment"},{"id":"u10-a-a25","domain":"Positive feedback","prompt":"Which is positive?","options":["Warming melts ice, lowering albedo and increasing absorption","Warming increases radiation to space","A thermostat turns cooling on","Weathering consumes some CO₂"],"answer":0,"explanation":"The ice–albedo loop amplifies the initial warming.","source":"unit-10","difficulty":"transfer","unit":"Unit 10","originalSource":"assessment"},{"id":"u10-a-a26","domain":"Uncertainty","prompt":"Uncertainty means:","options":["Models are useless","A quantified or described limit, not total ignorance","All conclusions are equally likely","No evidence exists"],"answer":1,"explanation":"Uncertainty defines confidence and limitations.","source":"unit-10","difficulty":"transfer","unit":"Unit 10","originalSource":"assessment"},{"id":"u10-a-a27","domain":"Mitigation","prompt":"Which is mitigation?","options":["Expanding evacuation routes","Installing cooling centers","Reducing greenhouse-gas emissions","Raising homes above flood level"],"answer":2,"explanation":"Mitigation reduces the cause or forcing.","source":"unit-10","difficulty":"transfer","unit":"Unit 10","originalSource":"assessment"},{"id":"u10-a-a28","domain":"Adaptation","prompt":"Which is adaptation?","options":["Reducing fossil-fuel combustion","Capturing methane at a landfill","Improving energy efficiency","Restoring wetlands to reduce coastal flood impacts"],"answer":3,"explanation":"Wetland restoration can reduce vulnerability to flooding.","source":"unit-10","difficulty":"transfer","unit":"Unit 10","originalSource":"assessment"},{"id":"u10-a-a29","domain":"Risk","prompt":"Risk depends on:","options":["Hazard, exposure, and vulnerability","Hazard alone","Population alone","Weather alone"],"answer":0,"explanation":"Risk emerges from the interaction of these factors.","source":"unit-10","difficulty":"transfer","unit":"Unit 10","originalSource":"assessment"},{"id":"u10-a-a30","domain":"Safety","prompt":"Which field action is inappropriate?","options":["Recording rainfall with a stable gauge","Entering an unstable sinkhole edge","Using public map data","Photographing a stream from a safe bridge"],"answer":1,"explanation":"Sinkholes can collapse and should not be approached.","source":"unit-10","difficulty":"transfer","unit":"Unit 10","originalSource":"assessment"},{"id":"u11-q-q01","domain":"Sky motion","prompt":"Day and night result from:","options":["Earth’s rotation","Earth’s orbit only","The Moon’s phases","The Sun orbiting Earth daily"],"answer":0,"explanation":"Earth rotates approximately once per day.","source":"unit-11","difficulty":"core","unit":"Unit 11","originalSource":"quiz"},{"id":"u11-q-q02","domain":"Lunar phases","prompt":"Ordinary lunar phases are caused by:","options":["Earth’s shadow covering the Moon","Changing viewing geometry of the Moon’s sunlit half","Cloud cover","The Moon producing different amounts of light"],"answer":1,"explanation":"The visible fraction changes with geometry.","source":"unit-11","difficulty":"core","unit":"Unit 11","originalSource":"quiz"},{"id":"u11-q-q03","domain":"Scale","prompt":"Which unit is most useful for nearby stellar distances?","options":["Pascal","Kilogram","Light-year","Ampere"],"answer":2,"explanation":"Light-years measure large distances.","source":"unit-11","difficulty":"core","unit":"Unit 11","originalSource":"quiz"},{"id":"u11-q-q04","domain":"Light-time","prompt":"If light travel time is 500 s and c=3.0×10⁸ m/s, distance is:","options":["6.0×10⁵ m","1.67×10⁻⁶ m","1.5×10⁶ m","1.5×10¹¹ m"],"answer":3,"explanation":"d=ct=3.0×10⁸×500=1.5×10¹¹ m.","source":"unit-11","difficulty":"core","unit":"Unit 11","originalSource":"quiz"},{"id":"u11-q-q05","domain":"Orbit","prompt":"Gravity in an orbit primarily changes:","options":["Velocity direction and sometimes magnitude","Mass into charge","Time into distance","The object’s chemical identity"],"answer":0,"explanation":"Gravity accelerates the orbiting object.","source":"unit-11","difficulty":"core","unit":"Unit 11","originalSource":"quiz"},{"id":"u11-q-q06","domain":"Formation","prompt":"Planetary systems form from:","options":["Black holes exclusively","Rotating disks of gas and dust around young stars","Only shattered planets","Empty space without matter"],"answer":1,"explanation":"Protoplanetary disks provide material for accretion.","source":"unit-11","difficulty":"core","unit":"Unit 11","originalSource":"quiz"},{"id":"u11-q-q07","domain":"Sun","prompt":"The photosphere is:","options":["A planet","The solar-system boundary","The Sun’s visible surface layer","The fusion core"],"answer":2,"explanation":"Most visible sunlight emerges from the photosphere.","source":"unit-11","difficulty":"core","unit":"Unit 11","originalSource":"quiz"},{"id":"u11-q-q08","domain":"Space weather","prompt":"Auroras are linked to:","options":["Lunar eclipses","Ocean tides only","Asteroid mining","Charged particles interacting with Earth’s magnetic environment and atmosphere"],"answer":3,"explanation":"Energetic particles excite atmospheric gases.","source":"unit-11","difficulty":"core","unit":"Unit 11","originalSource":"quiz"},{"id":"u11-q-q09","domain":"Spectrum","prompt":"A blueshift means observed wavelength is:","options":["Shorter than rest wavelength","Always exactly zero","Unrelated to motion","Longer than rest wavelength"],"answer":0,"explanation":"Approaching line-of-sight motion can shorten wavelength.","source":"unit-11","difficulty":"core","unit":"Unit 11","originalSource":"quiz"},{"id":"u11-q-q10","domain":"Telescopes","prompt":"Radio telescopes detect:","options":["Gravity directly","Radio-frequency electromagnetic waves","Sound traveling through space","Only visible light"],"answer":1,"explanation":"Radio is part of the electromagnetic spectrum.","source":"unit-11","difficulty":"core","unit":"Unit 11","originalSource":"quiz"},{"id":"u11-q-q11","domain":"Stars","prompt":"Main-sequence stability reflects balance between:","options":["Planetary tides only","Darkness and brightness","Inward gravity and outward pressure effects","Electric charge and magnet color"],"answer":2,"explanation":"Stars maintain dynamic hydrostatic balance.","source":"unit-11","difficulty":"core","unit":"Unit 11","originalSource":"quiz"},{"id":"u11-q-q12","domain":"Stellar evolution","prompt":"A lower-mass star is expected eventually to form:","options":["A supermassive black hole directly","A planet without mass loss","An asteroid belt only","A white dwarf after a red-giant and planetary-nebula stage"],"answer":3,"explanation":"Lower-mass stars end as white dwarfs.","source":"unit-11","difficulty":"core","unit":"Unit 11","originalSource":"quiz"},{"id":"u11-q-q13","domain":"Transit","prompt":"Transit depth mainly constrains:","options":["Planet-to-star area ratio","Galaxy age","Moon phase","Hubble constant"],"answer":0,"explanation":"Depth approximates squared radius ratio.","source":"unit-11","difficulty":"core","unit":"Unit 11","originalSource":"quiz"},{"id":"u11-q-q14","domain":"Exoplanet evidence","prompt":"One transit event alone is:","options":["Sufficient proof in every case","Evidence requiring repeat observations and false-positive analysis","Proof of life","A direct photograph"],"answer":1,"explanation":"Repeated signals and confirmation strengthen the interpretation.","source":"unit-11","difficulty":"core","unit":"Unit 11","originalSource":"quiz"},{"id":"u11-q-q15","domain":"Galaxy","prompt":"The Sun is located in:","options":["A globular cluster outside all galaxies","The center of the universe","The Milky Way galaxy","The Andromeda galaxy"],"answer":2,"explanation":"The Solar System is within the Milky Way.","source":"unit-11","difficulty":"core","unit":"Unit 11","originalSource":"quiz"},{"id":"u11-q-q16","domain":"Lookback time","prompt":"Observing a galaxy 10 million light-years away means seeing it approximately:","options":["10 million years in the future","With no time delay","As it is this instant","10 million years in the past"],"answer":3,"explanation":"Its light traveled for about 10 million years.","source":"unit-11","difficulty":"core","unit":"Unit 11","originalSource":"quiz"},{"id":"u11-q-q17","domain":"Redshift","prompt":"Cosmological redshift generally indicates:","options":["Increasing wavelength from large-scale recession/expansion","Chemical combustion","A star becoming visually red only","No motion or expansion"],"answer":0,"explanation":"Wavelengths are stretched in the expanding-universe context.","source":"unit-11","difficulty":"core","unit":"Unit 11","originalSource":"quiz"},{"id":"u11-q-q18","domain":"Big Bang evidence","prompt":"Which is independent evidence for a hot early universe?","options":["A solar eclipse","Cosmic microwave background","Earth’s seasons","Ocean tides"],"answer":1,"explanation":"The CMB is relic radiation from the early universe.","source":"unit-11","difficulty":"core","unit":"Unit 11","originalSource":"quiz"},{"id":"u11-q-q19","domain":"Responsibility","prompt":"Orbital debris can:","options":["Disappear immediately","Affect only the Moon","Threaten spacecraft through high-speed collisions","Improve every orbit"],"answer":2,"explanation":"Even small debris can cause serious damage at orbital speeds.","source":"unit-11","difficulty":"core","unit":"Unit 11","originalSource":"quiz"},{"id":"u11-a-a01","domain":"Earth rotation","prompt":"Earth’s west-to-east rotation makes the sky appear to move:","options":["East to west","North to south only","West to east","Without any pattern"],"answer":0,"explanation":"The apparent motion is opposite Earth’s rotation.","source":"unit-11","difficulty":"transfer","unit":"Unit 11","originalSource":"assessment"},{"id":"u11-a-a02","domain":"Seasons","prompt":"When a hemisphere tilts toward the Sun, it generally receives:","options":["Lower solar angle and shorter days","Higher solar angle and longer days","No sunlight","The same day length everywhere"],"answer":1,"explanation":"Tilt changes angle and duration.","source":"unit-11","difficulty":"transfer","unit":"Unit 11","originalSource":"assessment"},{"id":"u11-a-a03","domain":"Moon phases","prompt":"A full Moon occurs when:","options":["Earth’s shadow always covers the Moon","The Moon emits maximum light","The Moon is approximately opposite the Sun in Earth’s sky","The Moon is between Earth and the Sun"],"answer":2,"explanation":"The near side appears fully illuminated at opposition.","source":"unit-11","difficulty":"transfer","unit":"Unit 11","originalSource":"assessment"},{"id":"u11-a-a04","domain":"Light-year conversion","prompt":"Using 1 ly=9.46×10¹⁵ m, 2 ly is:","options":["9.46×10¹⁷ m","2 m","4.73×10¹⁵ m","1.892×10¹⁶ m"],"answer":3,"explanation":"2×9.46×10¹⁵=1.892×10¹⁶ m.","source":"unit-11","difficulty":"transfer","unit":"Unit 11","originalSource":"assessment"},{"id":"u11-a-a05","domain":"Light travel","prompt":"Time for light to travel 9.0×10¹⁰ m at 3.0×10⁸ m/s is:","options":["300 s","3000 s","2.7×10¹⁹ s","30 s"],"answer":0,"explanation":"t=d/c=300 s.","source":"unit-11","difficulty":"transfer","unit":"Unit 11","originalSource":"assessment"},{"id":"u11-a-a06","domain":"Orbital speed","prompt":"A circular path has r=1.0×10⁷ m and T=2.0×10⁴ s. Average speed is closest to:","options":["314 m/s","3140 m/s","31,400 m/s","6.28×10¹¹ m/s"],"answer":1,"explanation":"v=2πr/T≈3142 m/s.","source":"unit-11","difficulty":"transfer","unit":"Unit 11","originalSource":"assessment"},{"id":"u11-a-a07","domain":"Orbit direction","prompt":"For a circular orbit, velocity is approximately:","options":["Outward with no acceleration","Zero","Tangential while acceleration points inward","Inward while acceleration is tangential"],"answer":2,"explanation":"Velocity is tangent and gravity supplies inward acceleration.","source":"unit-11","difficulty":"transfer","unit":"Unit 11","originalSource":"assessment"},{"id":"u11-a-a08","domain":"Solar-system formation","prompt":"A shared orbital plane is evidence consistent with:","options":["Independent random capture of every planet","No gravity","A stationary cloud with no angular momentum","Formation from a flattened rotating disk"],"answer":3,"explanation":"Disk formation explains common direction and plane.","source":"unit-11","difficulty":"transfer","unit":"Unit 11","originalSource":"assessment"},{"id":"u11-a-a09","domain":"Planet types","prompt":"The inner planets are generally:","options":["Smaller and rocky","Larger and mostly hydrogen/helium","All dwarf planets","Made only of ice"],"answer":0,"explanation":"Mercury through Mars are terrestrial planets.","source":"unit-11","difficulty":"transfer","unit":"Unit 11","originalSource":"assessment"},{"id":"u11-a-a10","domain":"Solar fusion","prompt":"Fusion in the Sun’s core primarily converts:","options":["Light into matter only","Hydrogen into helium","Iron into hydrogen","Oxygen into carbon dioxide"],"answer":1,"explanation":"Hydrogen fusion powers the Sun.","source":"unit-11","difficulty":"transfer","unit":"Unit 11","originalSource":"assessment"},{"id":"u11-a-a11","domain":"Solar observation","prompt":"Which method is acceptable?","options":["Unfiltered camera viewfinder","Smoked glass","Certified solar filter used exactly as designed under supervision","Sunglasses with binoculars"],"answer":2,"explanation":"Only purpose-built certified protection is acceptable.","source":"unit-11","difficulty":"transfer","unit":"Unit 11","originalSource":"assessment"},{"id":"u11-a-a12","domain":"Spectrum","prompt":"An emission line occurs when:","options":["All wavelengths are absorbed equally","A planet blocks a star","A telescope loses focus","Atoms or ions emit photons at characteristic wavelengths"],"answer":3,"explanation":"Energy transitions produce characteristic photons.","source":"unit-11","difficulty":"transfer","unit":"Unit 11","originalSource":"assessment"},{"id":"u11-a-a13","domain":"Redshift calculation","prompt":"A line shifts from 600 nm to 603 nm. z is:","options":["0.005","0.05","1.005","0.0005"],"answer":0,"explanation":"z=(603−600)/600=0.005.","source":"unit-11","difficulty":"transfer","unit":"Unit 11","originalSource":"assessment"},{"id":"u11-a-a14","domain":"Velocity approximation","prompt":"For z=0.005 and c=300,000 km/s, v≈:","options":["150 km/s","1500 km/s","15,000 km/s","60,000,000 km/s"],"answer":1,"explanation":"v≈0.005×300,000=1500 km/s.","source":"unit-11","difficulty":"transfer","unit":"Unit 11","originalSource":"assessment"},{"id":"u11-a-a15","domain":"Spectral limitation","prompt":"A redshift measurement requires:","options":["No calibration","A nearby planet","A known or modeled rest wavelength for comparison","Only a color photograph"],"answer":2,"explanation":"Shift is defined relative to a rest wavelength.","source":"unit-11","difficulty":"transfer","unit":"Unit 11","originalSource":"assessment"},{"id":"u11-a-a16","domain":"Star stability","prompt":"A stable main-sequence star is in:","options":["No-gravity free expansion","Chemical equilibrium only","An orbit around every planet","Dynamic balance between gravity and pressure"],"answer":3,"explanation":"Hydrostatic balance maintains the star.","source":"unit-11","difficulty":"transfer","unit":"Unit 11","originalSource":"assessment"},{"id":"u11-a-a17","domain":"Mass and lifetime","prompt":"A high-mass star generally has:","options":["A shorter lifetime than a low-mass star","An infinite lifetime","No fusion","Lower core temperature in every case"],"answer":0,"explanation":"It consumes fuel much faster.","source":"unit-11","difficulty":"transfer","unit":"Unit 11","originalSource":"assessment"},{"id":"u11-a-a18","domain":"Supernova products","prompt":"A massive-star supernova can leave:","options":["No remnant","A neutron star or black hole","Only a rocky planet","A main-sequence Sun immediately"],"answer":1,"explanation":"Core collapse can form compact remnants.","source":"unit-11","difficulty":"transfer","unit":"Unit 11","originalSource":"assessment"},{"id":"u11-a-a19","domain":"Transit radius ratio","prompt":"A transit depth is 0.04. Rp/Rs≈:","options":["0.96","0.02","0.20","0.40"],"answer":2,"explanation":"√0.04=0.20.","source":"unit-11","difficulty":"transfer","unit":"Unit 11","originalSource":"assessment"},{"id":"u11-a-a20","domain":"Transit bias","prompt":"Which planet is easiest for a transit survey to find, all else equal?","options":["Small, long-period, face-on planet","A rogue planet with no star","A planet that never crosses the star","Large, short-period, edge-on planet"],"answer":3,"explanation":"It produces larger and more frequent transits.","source":"unit-11","difficulty":"transfer","unit":"Unit 11","originalSource":"assessment"},{"id":"u11-a-a21","domain":"Habitability claim","prompt":"Which statement is scientifically defensible?","options":["Habitable-zone position is one factor and does not prove life","Every habitable-zone planet has oceans","A transit proves biology","Atmospheres are irrelevant"],"answer":0,"explanation":"Many additional conditions and evidence are needed.","source":"unit-11","difficulty":"transfer","unit":"Unit 11","originalSource":"assessment"},{"id":"u11-a-a22","domain":"Cosmic nesting","prompt":"The Local Group is:","options":["The entire universe","A group of galaxies including the Milky Way","A group of planets around the Sun","A cluster of asteroids"],"answer":1,"explanation":"It is the Milky Way’s galactic neighborhood.","source":"unit-11","difficulty":"transfer","unit":"Unit 11","originalSource":"assessment"},{"id":"u11-a-a23","domain":"Distance evidence","prompt":"Parallax is most useful for:","options":["Measuring planet mass directly","Dating meteorites","Relatively nearby stars","The most distant galaxies only"],"answer":2,"explanation":"Parallax angles become too small at great distances.","source":"unit-11","difficulty":"transfer","unit":"Unit 11","originalSource":"assessment"},{"id":"u11-a-a24","domain":"Hubble law","prompt":"At H₀=70 km/s/Mpc, d=40 Mpc gives:","options":["28,000 km/s","0.57 km/s","110 km/s","2800 km/s"],"answer":3,"explanation":"v=70×40=2800 km/s.","source":"unit-11","difficulty":"transfer","unit":"Unit 11","originalSource":"assessment"},{"id":"u11-a-a25","domain":"Hubble interpretation","prompt":"Hubble’s relation is best treated as:","options":["A large-scale empirical/model relation with scatter and calibration limits","An exact law for every nearby object","Proof Earth is central","A chemical equation"],"answer":0,"explanation":"Peculiar velocities and measurement uncertainty create scatter.","source":"unit-11","difficulty":"transfer","unit":"Unit 11","originalSource":"assessment"},{"id":"u11-a-a26","domain":"CMB evidence","prompt":"The CMB is important because it is:","options":["Proof of one specific galaxy’s age","Relic electromagnetic radiation from an early hot universe","Sunlight reflected by dust only","A local radio station"],"answer":1,"explanation":"It records conditions from the early universe.","source":"unit-11","difficulty":"transfer","unit":"Unit 11","originalSource":"assessment"},{"id":"u11-a-a27","domain":"Primordial composition","prompt":"The abundance of hydrogen and helium supports:","options":["Plate tectonics","Only solar weather","Models of early-universe nucleosynthesis","Lunar-phase theory"],"answer":2,"explanation":"Predicted light-element abundances provide independent evidence.","source":"unit-11","difficulty":"transfer","unit":"Unit 11","originalSource":"assessment"},{"id":"u11-a-a28","domain":"Big Bang misconception","prompt":"Which statement is incorrect?","options":["Redshift trends support expansion","The expansion has no required ordinary spatial center","The model describes evolution from an early hot dense state","Every galaxy is moving through space away from Earth as the unique center"],"answer":3,"explanation":"Earth is not modeled as the unique expansion center.","source":"unit-11","difficulty":"transfer","unit":"Unit 11","originalSource":"assessment"},{"id":"u11-a-a29","domain":"Space responsibility","prompt":"Planetary protection aims to:","options":["Reduce harmful biological contamination between worlds","Claim ownership of planets","Increase debris","Hide all data"],"answer":0,"explanation":"It protects scientific integrity and environments.","source":"unit-11","difficulty":"transfer","unit":"Unit 11","originalSource":"assessment"},{"id":"u11-a-a30","domain":"Night observation safety","prompt":"Which plan is appropriate?","options":["Enter private land without permission","Observe with an adult from a permitted stable location away from traffic and check weather","Stand on a roof edge alone","Stop on a highway shoulder"],"answer":1,"explanation":"Safe observation requires permission, stable access, supervision, and weather awareness.","source":"unit-11","difficulty":"transfer","unit":"Unit 11","originalSource":"assessment"},{"id":"u12-q-q01","domain":"Problem definition","prompt":"A good need statement should:","options":["Describe users and desired improvement without assuming a solution","Exclude affected communities","Avoid measurable outcomes","Embed one required technology"],"answer":0,"explanation":"It should frame the need without premature solution lock-in.","source":"unit-12","difficulty":"core","unit":"Unit 12","originalSource":"quiz"},{"id":"u12-q-q02","domain":"Stakeholders","prompt":"A stakeholder is:","options":["Only the paying customer","Anyone affected by, using, maintaining, governing, or deciding about the system","Only the engineer","Only a regulator"],"answer":1,"explanation":"Stakeholders include many affected and responsible groups.","source":"unit-12","difficulty":"core","unit":"Unit 12","originalSource":"quiz"},{"id":"u12-q-q03","domain":"Criteria","prompt":"A criterion should be:","options":["Changed after results to favor a design","Identical to a constraint","Measurable when possible","Hidden from reviewers"],"answer":2,"explanation":"Criteria should support objective verification.","source":"unit-12","difficulty":"core","unit":"Unit 12","originalSource":"quiz"},{"id":"u12-q-q04","domain":"Constraint","prompt":"A budget cap is usually:","options":["A scientific law","A test result","A feedback loop","A constraint"],"answer":3,"explanation":"It limits feasible solutions.","source":"unit-12","difficulty":"core","unit":"Unit 12","originalSource":"quiz"},{"id":"u12-q-q05","domain":"Baseline","prompt":"A baseline records:","options":["Conditions before the intervention","Only the final design","A marketing claim","The preferred future without evidence"],"answer":0,"explanation":"Improvement is judged relative to current conditions.","source":"unit-12","difficulty":"core","unit":"Unit 12","originalSource":"quiz"},{"id":"u12-q-q06","domain":"Decision matrix","prompt":"Weighted scores are most useful when:","options":["Scores are invented after selection","Weights and scoring evidence are transparent","Hard constraints are ignored","Only one concept exists"],"answer":1,"explanation":"Transparency enables review and sensitivity analysis.","source":"unit-12","difficulty":"core","unit":"Unit 12","originalSource":"quiz"},{"id":"u12-q-q07","domain":"Concept generation","prompt":"Why generate several concepts?","options":["To eliminate constraints","To delay all decisions forever","To reduce premature fixation and enable combination of strong features","To avoid science"],"answer":2,"explanation":"Diverse concepts increase design-space exploration.","source":"unit-12","difficulty":"core","unit":"Unit 12","originalSource":"quiz"},{"id":"u12-q-q08","domain":"Biomimicry","prompt":"A biological analogy is:","options":["A patent automatically","Always sustainable","Proof the design will work","A source of hypotheses requiring engineering tests"],"answer":3,"explanation":"Inspiration must be tested in context.","source":"unit-12","difficulty":"core","unit":"Unit 12","originalSource":"quiz"},{"id":"u12-q-q09","domain":"Prototype","prompt":"A prototype should primarily:","options":["Answer a defined design question","Look identical to the final product","Use dangerous materials","Avoid measurement"],"answer":0,"explanation":"Prototype form should match the question being tested.","source":"unit-12","difficulty":"core","unit":"Unit 12","originalSource":"quiz"},{"id":"u12-q-q10","domain":"Trials","prompt":"Repeated trials help estimate:","options":["Universal optimality","Variation and repeatability","Aesthetic preference only","Legal approval"],"answer":1,"explanation":"They reveal performance spread.","source":"unit-12","difficulty":"core","unit":"Unit 12","originalSource":"quiz"},{"id":"u12-q-q11","domain":"Uncertainty","prompt":"Measurement resolution is:","options":["A hard constraint","A stakeholder","The smallest change an instrument can meaningfully display or distinguish","The sample mean"],"answer":2,"explanation":"Resolution limits reported precision.","source":"unit-12","difficulty":"core","unit":"Unit 12","originalSource":"quiz"},{"id":"u12-q-q12","domain":"Optimization","prompt":"Optimization means:","options":["Maximizing one criterion regardless of harm","Eliminating all tradeoffs","Ignoring failed tests","Improving performance across prioritized criteria within constraints"],"answer":3,"explanation":"Optimization is constrained and multi-criteria.","source":"unit-12","difficulty":"core","unit":"Unit 12","originalSource":"quiz"},{"id":"u12-q-q13","domain":"Life cycle","prompt":"Cradle-to-grave analysis includes:","options":["Extraction through end-of-life","Use phase only","Purchase price only","Recycling only"],"answer":0,"explanation":"It considers the full life cycle.","source":"unit-12","difficulty":"core","unit":"Unit 12","originalSource":"quiz"},{"id":"u12-q-q14","domain":"Functional unit","prompt":"A functional unit defines:","options":["A legal permit","The service used as the comparison basis","A company name","The criterion weight total"],"answer":1,"explanation":"It enables fair comparison of alternatives.","source":"unit-12","difficulty":"core","unit":"Unit 12","originalSource":"quiz"},{"id":"u12-q-q15","domain":"Reliability","prompt":"Reliability requires stated:","options":["Only cost","Only probability category","Function, conditions, and time","Color, logo, and owner"],"answer":2,"explanation":"Reliability is conditional on required service and context.","source":"unit-12","difficulty":"core","unit":"Unit 12","originalSource":"quiz"},{"id":"u12-q-q16","domain":"Risk control","prompt":"Which hierarchy is strongest?","options":["Use warnings before removing the hazard","Ignore low-frequency severe hazards","Transfer all responsibility to users","Eliminate the hazard before relying only on warnings"],"answer":3,"explanation":"Elimination is generally more effective than warnings alone.","source":"unit-12","difficulty":"core","unit":"Unit 12","originalSource":"quiz"},{"id":"u12-q-q17","domain":"Accessibility","prompt":"Universal design aims to:","options":["Increase usable access for the widest practical range of people","Design only for an average user","Remove all customization","Avoid stakeholder input"],"answer":0,"explanation":"It broadens access without unnecessary exclusion.","source":"unit-12","difficulty":"core","unit":"Unit 12","originalSource":"quiz"},{"id":"u12-q-q18","domain":"Ethics","prompt":"Informed consent is relevant when:","options":["The project is fictional","People provide personal data or participate in tests","Only machines are measured","No people are affected"],"answer":1,"explanation":"Human participation and personal data require ethical protections.","source":"unit-12","difficulty":"core","unit":"Unit 12","originalSource":"quiz"},{"id":"u12-q-q19","domain":"Communication","prompt":"A technical claim should include:","options":["No units","No alternative explanation","Evidence, assumptions, uncertainty, and limitations","Only the strongest result"],"answer":2,"explanation":"Transparent communication supports responsible decisions.","source":"unit-12","difficulty":"core","unit":"Unit 12","originalSource":"quiz"},{"id":"u12-q-q20","domain":"Course completion","prompt":"A course completion record:","options":["Automatically grants every professional license","Eliminates future learning","Proves a design is commercially certified","Documents demonstrated coursework but does not override local credit law or policy"],"answer":3,"explanation":"Academic records do not replace jurisdictional requirements.","source":"unit-12","difficulty":"core","unit":"Unit 12","originalSource":"quiz"},{"id":"u12-a-a01","domain":"Need statement","prompt":"Which is the best need statement?","options":["Residents need safer household water treatment that is affordable, maintainable, and locally serviceable","Use ultraviolet LEDs because they are modern","Purchase the most expensive filter","Build a solar purifier immediately"],"answer":0,"explanation":"It states users and need without locking one solution.","source":"unit-12","difficulty":"transfer","unit":"Unit 12","originalSource":"assessment"},{"id":"u12-a-a02","domain":"Boundary","prompt":"A system boundary should identify:","options":["No exclusions","Included processes and important exchanges","Only the product color","A universal solution"],"answer":1,"explanation":"Boundaries clarify what is counted and controlled.","source":"unit-12","difficulty":"transfer","unit":"Unit 12","originalSource":"assessment"},{"id":"u12-a-a03","domain":"Criterion","prompt":"Which is measurable?","options":["Should feel better","Must be innovative","Remove at least 95% of the specified test particles","Should be popular"],"answer":2,"explanation":"It provides a quantitative threshold and defined target.","source":"unit-12","difficulty":"transfer","unit":"Unit 12","originalSource":"assessment"},{"id":"u12-a-a04","domain":"Constraint","prompt":"Which is not negotiable?","options":["Highest possible score","Preferred blue color","Optional decorative feature","No exposed sharp edge during normal use"],"answer":3,"explanation":"Safety constraints are non-negotiable.","source":"unit-12","difficulty":"transfer","unit":"Unit 12","originalSource":"assessment"},{"id":"u12-a-a05","domain":"Weights","prompt":"Weights 0.50, 0.30, and 0.20 sum to:","options":["1.00","1.20","0.50","0.80"],"answer":0,"explanation":"They sum to 1.00.","source":"unit-12","difficulty":"transfer","unit":"Unit 12","originalSource":"assessment"},{"id":"u12-a-a06","domain":"Weighted score","prompt":"Scores 6, 8, 9 with weights 0.5, 0.3, 0.2 give:","options":["6.6","7.2","7.8","8.4"],"answer":1,"explanation":"6×0.5+8×0.3+9×0.2=7.2.","source":"unit-12","difficulty":"transfer","unit":"Unit 12","originalSource":"assessment"},{"id":"u12-a-a07","domain":"Constraint failure","prompt":"A concept violates the maximum mass constraint. Correct action:","options":["Report it as compliant","Select it if weighted score is high","Reject or redesign it before ranking as feasible","Delete the mass constraint after testing"],"answer":2,"explanation":"Constraint failure makes it infeasible.","source":"unit-12","difficulty":"transfer","unit":"Unit 12","originalSource":"assessment"},{"id":"u12-a-a08","domain":"Sensitivity","prompt":"A ranking that reverses under very small reasonable weight changes is:","options":["A physical law","Free of value judgments","Highly robust","Sensitive and should be reported cautiously"],"answer":3,"explanation":"Instability indicates sensitivity.","source":"unit-12","difficulty":"transfer","unit":"Unit 12","originalSource":"assessment"},{"id":"u12-a-a09","domain":"Mean","prompt":"Trials 12, 13, 14, 15 have mean:","options":["13.5","14","54","13"],"answer":0,"explanation":"54/4=13.5.","source":"unit-12","difficulty":"transfer","unit":"Unit 12","originalSource":"assessment"},{"id":"u12-a-a10","domain":"Range","prompt":"Trials 12, 13, 14, 15 have range:","options":["2","3","13.5","15"],"answer":1,"explanation":"15−12=3.","source":"unit-12","difficulty":"transfer","unit":"Unit 12","originalSource":"assessment"},{"id":"u12-a-a11","domain":"Percent improvement","prompt":"Baseline energy 100 kWh, redesign 70 kWh; lower is better. Improvement:","options":["70%","15%","30%","43%"],"answer":2,"explanation":"(100−70)/100=30%.","source":"unit-12","difficulty":"transfer","unit":"Unit 12","originalSource":"assessment"},{"id":"u12-a-a12","domain":"Success rate","prompt":"17 successes in 20 trials equals:","options":["117.6%","17%","20%","85%"],"answer":3,"explanation":"17/20=85%.","source":"unit-12","difficulty":"transfer","unit":"Unit 12","originalSource":"assessment"},{"id":"u12-a-a13","domain":"Systematic error","prompt":"A thermometer is consistently 1.5°C high. This is:","options":["Systematic bias","A larger sample","Reliability","Random variation"],"answer":0,"explanation":"The offset is systematic.","source":"unit-12","difficulty":"transfer","unit":"Unit 12","originalSource":"assessment"},{"id":"u12-a-a14","domain":"Test validity","prompt":"Which is best?","options":["Change prototype, test load, and instrument together","Use calibrated instruments and a controlled comparison","Keep only successful trials","Round every value to a whole number"],"answer":1,"explanation":"Calibration and control support valid comparison.","source":"unit-12","difficulty":"transfer","unit":"Unit 12","originalSource":"assessment"},{"id":"u12-a-a15","domain":"Material impact","prompt":"3 kg at 4 units/kg contributes:","options":["0.75 units","7 units","12 units","24 units"],"answer":2,"explanation":"3×4=12.","source":"unit-12","difficulty":"transfer","unit":"Unit 12","originalSource":"assessment"},{"id":"u12-a-a16","domain":"Transport impact","prompt":"Mass 2 t, distance 100 km, factor 0.05 units/(t·km) gives:","options":["100 units","1000 units","0.1 units","10 units"],"answer":3,"explanation":"2×100×0.05=10.","source":"unit-12","difficulty":"transfer","unit":"Unit 12","originalSource":"assessment"},{"id":"u12-a-a17","domain":"Use impact","prompt":"0.5 kWh/day for 200 days at 0.4 units/kWh gives:","options":["40 units","100 units","400 units","20 units"],"answer":0,"explanation":"0.5×200×0.4=40.","source":"unit-12","difficulty":"transfer","unit":"Unit 12","originalSource":"assessment"},{"id":"u12-a-a18","domain":"Annualized impact","prompt":"Total 300 units over 10 years is:","options":["3 units/year","30 units/year","290 units/year","3000 units/year"],"answer":1,"explanation":"300/10=30.","source":"unit-12","difficulty":"transfer","unit":"Unit 12","originalSource":"assessment"},{"id":"u12-a-a19","domain":"Recovery","prompt":"6 kg recovered from 8 kg total equals:","options":["25%","60%","75%","133%"],"answer":2,"explanation":"6/8=75%.","source":"unit-12","difficulty":"transfer","unit":"Unit 12","originalSource":"assessment"},{"id":"u12-a-a20","domain":"Life-cycle comparison","prompt":"Which is required?","options":["Same brand","Same color","Same advertising","Same functional service and compatible boundaries"],"answer":3,"explanation":"Functional equivalence and consistent boundaries enable fair comparison.","source":"unit-12","difficulty":"transfer","unit":"Unit 12","originalSource":"assessment"},{"id":"u12-a-a21","domain":"Risk score","prompt":"Likelihood 4 × severity 5 gives:","options":["20","25","45","9"],"answer":0,"explanation":"4×5=20.","source":"unit-12","difficulty":"transfer","unit":"Unit 12","originalSource":"assessment"},{"id":"u12-a-a22","domain":"Risk reduction","prompt":"Score falls from 15 to 6. Reduction:","options":["40%","60%","90%","150%"],"answer":1,"explanation":"(15−6)/15=60%.","source":"unit-12","difficulty":"transfer","unit":"Unit 12","originalSource":"assessment"},{"id":"u12-a-a23","domain":"Series reliability","prompt":"Independent reliabilities 0.95 and 0.80 give:","options":["0.95","1.75","0.76","0.875"],"answer":2,"explanation":"0.95×0.80=0.76.","source":"unit-12","difficulty":"transfer","unit":"Unit 12","originalSource":"assessment"},{"id":"u12-a-a24","domain":"Redundancy","prompt":"A backup pump primarily improves:","options":["Material toxicity","Criterion ambiguity","Stakeholder exclusion","Functional resilience if the primary fails"],"answer":3,"explanation":"A backup can preserve required service.","source":"unit-12","difficulty":"transfer","unit":"Unit 12","originalSource":"assessment"},{"id":"u12-a-a25","domain":"Residual risk","prompt":"After controls, remaining risk should be:","options":["Documented, reviewed, and accepted or further reduced","Assumed zero","Converted into a preference","Hidden"],"answer":0,"explanation":"Residual risk needs accountable treatment.","source":"unit-12","difficulty":"transfer","unit":"Unit 12","originalSource":"assessment"},{"id":"u12-a-a26","domain":"Accessibility","prompt":"Which is most inclusive?","options":["Single tiny text-only control","Multiple perceivable control methods with clear labels","Color-only warnings","Steps requiring perfect grip strength"],"answer":1,"explanation":"Multiple accessible modes reduce exclusion.","source":"unit-12","difficulty":"transfer","unit":"Unit 12","originalSource":"assessment"},{"id":"u12-a-a27","domain":"Privacy","prompt":"A prototype app collects location data. Best practice:","options":["Use hidden tracking","Collect everything indefinitely","Minimize collection, obtain consent, secure data, and define deletion","Publish raw records"],"answer":2,"explanation":"Privacy-by-design reduces risk.","source":"unit-12","difficulty":"transfer","unit":"Unit 12","originalSource":"assessment"},{"id":"u12-a-a28","domain":"Optimization","prompt":"A redesign improves efficiency but doubles injury risk. It is:","options":["Proven sustainable","Ready for release","Automatically optimal","Not acceptable without addressing safety constraint and tradeoff"],"answer":3,"explanation":"Optimization cannot ignore safety.","source":"unit-12","difficulty":"transfer","unit":"Unit 12","originalSource":"assessment"},{"id":"u12-a-a29","domain":"Communication","prompt":"Which statement is strongest?","options":["Under the stated tests, mean performance improved 18%, with a 4% range and two untested conditions","Everyone will benefit","No uncertainty exists","The design is perfect"],"answer":0,"explanation":"It reports evidence, variability, and limits.","source":"unit-12","difficulty":"transfer","unit":"Unit 12","originalSource":"assessment"},{"id":"u12-a-a30","domain":"Capstone","prompt":"A defensible engineering conclusion should connect:","options":["Only the first prototype","Need, science, criteria, test data, life cycle, risk, revision, and stakeholder impacts","Only appearance","Only lowest cost"],"answer":1,"explanation":"A capstone integrates the full evidence chain.","source":"unit-12","difficulty":"transfer","unit":"Unit 12","originalSource":"assessment"}];
